/// How long a released press still counts as the hold that just fired.
///
/// A hold opens a sheet over the pill, so the release usually lands on the
/// sheet rather than the pill; this window covers the frame where it does not.
const LONG_PRESS_ECHO_MS: u64 = 600;
/// How long the new-session page's introduction takes to fade in.
const PAGE_ENTRANCE_MS: u64 = 200;
/// How close to the top the reader has to be for older history to be fetched.
///
/// One and a half screens: the page is already there when the reader arrives,
/// and reaching the very top never waits on a request. The unit is turns, the
/// list's own, because that is what its scroll handler reports.
const TIMELINE_OLDER_PREFETCH_SCREENS: f32 = 1.5;
const TIMELINE_LIST_OVERDRAW_PX: f32 = 800.0;
const TIMELINE_TURN_ESTIMATED_HEIGHT_PX: f32 = 180.0;
const TIMELINE_ACTION_BUTTON_SIZE_PX: f32 = 32.0;
const TIMELINE_EVENT_BATCH_LIMIT: usize = 256;
const TIMELINE_EVENT_COALESCE_DELAY: Duration = Duration::from_millis(16);
const TIMELINE_MARKDOWN_VIEW_CACHE_LIMIT: usize = 64;
/// How many past prompts the history sheet shows before its "show older"
/// control. The sheet is for recall, not for reading a transcript.
const COMPOSER_HISTORY_PAGE: usize = 20;
/// The distance from one queue row's top to the next, used to turn a drag's
/// travel into a drop index. It must match what the queue paints — a touch
/// target plus the gap between rows — or a drag lands one row off.
const COMPOSER_QUEUE_ROW_PITCH_PX: f32 = theme::TOUCH_TARGET + theme::SPACING_XS;
const TIMELINE_RUNTIME_LABEL_MAX_CHARS: usize = 48;
/// One complete sweep of the collapsed thinking label's shimmer. Desktop
/// parity: `AGENT_THINKING_SHIMMER_SWEEP` — the hand-rolled indicator ran ten
/// passes through a twelve-second loop, so keep the same pace now that the
/// kit's `ShimmerText` measures one sweep per duration.
const TIMELINE_SHIMMER_SWEEP: Duration = Duration::from_millis(1_200);
/// Highlight half-width as a fraction of the label width. Desktop parity:
/// `AGENT_THINKING_SHIMMER_SPREAD`.
const TIMELINE_SHIMMER_SPREAD: f32 = 0.42;
/// Desktop parity: `AGENT_THINKING_LABEL_MAX_CHARS`.
const AGENT_THINKING_LABEL_MAX_CHARS: usize = 48;
/// Reasoning preview cache bounds — one entry per visible reasoning row.
const REASONING_SUMMARY_CACHE_LIMIT: usize = 64;
/// One full sweep of the connecting page's wordmark. Desktop parity:
/// `STARTUP_WORDMARK_SHIMMER_DURATION` — the launch page and the phone's
/// connecting page are the same brand moment, so they breathe at the same pace.
const CONNECTING_WORDMARK_SHIMMER_DURATION: Duration = Duration::from_secs(12);
/// How many sweep passes that loop carries. Desktop parity:
/// `SHIMMER_SCAN_PASSES`.
const CONNECTING_WORDMARK_SCAN_PASSES: f32 = 10.0;
/// Highlight half-width, as a fraction of the lockup's walk from the mark's
/// start to the label's end. Desktop parity: `STARTUP_WORDMARK_SHIMMER_SPREAD`.
const CONNECTING_WORDMARK_SCAN_SPREAD: f32 = 0.42;
/// Frames per second the sweep is sampled at. Desktop parity:
/// `REPEATING_ANIMATION_MAX_FPS`; a slow sweep looks identical at half the
/// repaints, and the connecting page is otherwise static.
const CONNECTING_WORDMARK_SHIMMER_MAX_FPS: f32 = 30.0;
/// The label size of the connecting page's wordmark.
///
/// Exactly the pairing page's [`theme::FONT_WORDMARK`], not a step over it: the
/// lockup is the same product signature on both screens, and an oversized
/// version read as a splash poster on a phone rather than as this app's name.
/// The mark is scaled from this size by [`theme::wordmark_mark`], the same
/// authored geometry the other lockups use.
const CONNECTING_WORDMARK_FONT: f32 = theme::FONT_WORDMARK;

#[derive(Clone)]
struct ReasoningRowSummary {
    source_hash: u64,
    preview: String,
}

struct ReasoningSummaryCache(Mutex<BTreeMap<String, (i64, ReasoningRowSummary)>>);

impl ReasoningSummaryCache {
    fn lock_or_insert(&self) -> MutexGuard<'_, BTreeMap<String, (i64, ReasoningRowSummary)>> {
        self.0
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

static REASONING_SUMMARY_CACHE: LazyLock<ReasoningSummaryCache> =
    LazyLock::new(|| ReasoningSummaryCache(Mutex::new(BTreeMap::new())));
const MAX_INLINE_ATTACHMENT_BYTES: usize = 64 * 1024 * 1024;
const RESUME_RECOVERY_POLL_INTERVAL: Duration = Duration::from_millis(100);
const RESUME_RECOVERY_POLL_ATTEMPTS: usize = 600;
const RUNTIME_FEATURE_VALUE_LIMIT: usize = 256;

/// What a resumed phone should do about the connection it came back to.
///
/// The transport owns recovery, so this only says when the wait is over:
/// `Online` is the recovery, a credential the runtime has already refused is
/// the end of the line, and every state in between is still work in progress.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ResumeRecoveryOutcome {
    Recovered,
    Unrecoverable,
    Pending,
}

fn resume_recovery_outcome(state: RemoteConnectionState) -> ResumeRecoveryOutcome {
    if state == RemoteConnectionState::Online {
        ResumeRecoveryOutcome::Recovered
    } else if crate::background_connection::is_terminal(state) {
        ResumeRecoveryOutcome::Unrecoverable
    } else {
        ResumeRecoveryOutcome::Pending
    }
}

/// Why a connection will never come up with the credential the phone holds.
fn unrecoverable_connection_copy(state: RemoteConnectionState) -> &'static str {
    if state == RemoteConnectionState::Revoked {
        locale::text(
            "This phone's access was revoked. Pair it again from the desktop",
            "这台手机的授权已失效，请在桌面端重新配对",
            "這台手機的授權已失效，請在桌面版重新配對",
        )
    } else {
        locale::text(
            "This desktop and this app are not compatible. Update one of them",
            "桌面端与当前应用版本不兼容，请更新其中一端",
            "桌面版與目前應用程式版本不相容，請更新其中一端",
        )
    }
}

/// The runtime sheet pins its view bands (Agent strip, search row, model
/// list) at fixed heights so each band scrolls inside itself instead of
/// growing the card; the session-options band fills whatever remains.
const RUNTIME_SHEET_AGENT_STRIP_HEIGHT: f32 = 52.0;
const RUNTIME_SHEET_SEARCH_HEIGHT: f32 = 44.0;
const RUNTIME_SHEET_MODEL_LIST_HEIGHT: f32 = 216.0;

/// The list owns following the live end.
///
/// `FollowMode::Tail` is decided inside the list's own scroll handling: any
/// gesture toward older content stops following on that very event, and
/// following resumes only once layout finds the viewport at the true bottom.
/// Deciding it in the view instead — from reported offsets a frame late, or
/// from which turn the top landed on — cannot see a reader scrolling inside
/// the one tall turn that is streaming, and handed them back to the end under
/// their own finger.
fn timeline_list_state(turn_count: usize) -> ListState {
    let state = ListState::new(
        turn_count,
        ListAlignment::Top,
        px(TIMELINE_LIST_OVERDRAW_PX),
    )
    .with_uniform_item_height(px(TIMELINE_TURN_ESTIMATED_HEIGHT_PX));
    state.set_follow_mode(FollowMode::Tail);
    state
}

/// Points the timeline list's scroll reports at the view.
///
/// Older history is prefetched from them. The handler runs while the list
/// state is mutably borrowed, so it only hands the viewport to the view; every
/// list call happens on the view's turn.
fn install_timeline_scroll_handler(state: &ListState, owner: WeakEntity<MobileApp>) {
    state.set_scroll_handler(move |event, _window, cx| {
        let viewport = TimelineViewport {
            first_visible: event.visible_range.start,
            visible: event
                .visible_range
                .end
                .saturating_sub(event.visible_range.start),
        };
        let _ = owner.update(cx, |app, cx| {
            app.timeline_viewport = Some(viewport);
            app.prefetch_older_history_if_near_top(cx);
        });
    });
}

/// Gives every row the list has not measured yet the timeline's uniform height.
///
/// A spliced row carries no size hint, and the list summarises a hintless row as
/// zero height: a turn appended during streaming would contribute nothing to
/// the extent the list reports, and `ListState` clamps its own scrolling to that
/// extent — so the reader's first upward gesture gets clipped to a stretch
/// shorter than what is painted. The hint is what every unmeasured turn weighs.
///
/// `ListState` exposes the hint as a builder call and is `Rc`-backed and
/// cloneable, so applying it to a clone applies it to the one state behind both
/// handles. The alternative, `reset_with_uniform_height`, would also throw away
/// every height the list has already measured, and re-hinting measured turns at
/// 180px moves the reader in its own way. Applying the hint leaves a measured
/// row's own size in place, so this only ever fills the gaps.
fn hint_unmeasured_timeline_rows(list: &ListState) {
    let _ = list
        .clone()
        .with_uniform_item_height(px(TIMELINE_TURN_ESTIMATED_HEIGHT_PX));
}

/// The reader's place in the timeline, as the list last reported it.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct TimelineViewport {
    first_visible: usize,
    visible: usize,
}

/// A reading position that survives the item table being replaced.
///
/// The list's own position is a logical offset into the item table it was last
/// laid out with, so replacing the table — which an authoritative refetch does
/// — leaves that offset describing a different item. Naming the turn keeps the
/// reader where they were across the swap.
///
/// The id alone is not enough. A turn is named after whichever of its rows the
/// projection saw first — `turn:{user item}`, or `turn:continuation:{first
/// response item}` when the window opens inside the turn — so a page that
/// reaches back to the turn's own message renames the turn the reader is
/// looking at. That is exactly when the anchor has to resolve, and the id stops
/// resolving at that moment. The span is the turn's own content and survives
/// the rename, so it carries the anchor across one that the id cannot.
#[derive(Clone, PartialEq, Eq, Debug)]
struct TimelineScrollAnchor {
    /// The turn under the viewport top, as the projection named it.
    turn_id: String,
    /// The sequences that turn covers, when they are known.
    span: Option<TimelineAnchorSpan>,
    /// How far into the turn the viewport starts, in pixels.
    offset_in_item: i32,
}

/// The sequences one turn covers, as the desktop model defines a span.
///
/// Derived from the rows the turn already renders: the anchor needs the same
/// identity the desktop records, and a turn whose rows carry no sequence — a
/// locally projected one — has none to record.
fn timeline_turn_anchor_span(turn: &TimelineConversationTurn) -> Option<TimelineAnchorSpan> {
    let rows = turn
        .user_row
        .iter()
        .chain(turn.process_rows.iter())
        .chain(turn.conclusion_row.iter());
    let mut span: Option<TimelineAnchorSpan> = None;
    for row in rows {
        span = Some(match span {
            Some(current) => TimelineAnchorSpan {
                first_sequence: current.first_sequence.min(row.first_sequence),
                last_sequence: current.last_sequence.max(row.last_sequence),
            },
            None => TimelineAnchorSpan {
                first_sequence: row.first_sequence,
                last_sequence: row.last_sequence,
            },
        });
    }
    span
}

/// The row an anchor names in the table that is current now.
///
/// The id wins when it still exists, because it names the turn outright. A
/// page that lands above the reader renames the leading turn, so the recorded
/// span is the fallback: the turn overlapping it most is the one the reader was
/// looking at, and a turn that shares no sequence with it was not that turn.
fn timeline_anchor_row_index(
    turns: &[TimelineConversationTurn],
    anchor: &TimelineScrollAnchor,
) -> Option<usize> {
    if let Some(index) = turns.iter().position(|turn| turn.id == anchor.turn_id) {
        return Some(index);
    }
    let span = anchor.span?;
    turns
        .iter()
        .enumerate()
        .filter_map(|(index, turn)| {
            let turn = timeline_turn_anchor_span(turn)?;
            let overlap = span.overlap(turn.first_sequence, turn.last_sequence);
            (overlap > 0).then_some((index, overlap))
        })
        .max_by_key(|(_, overlap)| *overlap)
        .map(|(index, _)| index)
}

/// Whether a reported viewport sits within the older-history prefetch band.
///
/// The unit is turns because that is what the list reports; a turn can be
/// taller than a screen, so this is deliberately generous — fetching early
/// costs a page that the reader was about to want anyway.
fn timeline_viewport_is_near_top(first_visible: usize, visible: usize) -> bool {
    visible > 0 && first_visible as f32 <= visible as f32 * TIMELINE_OLDER_PREFETCH_SCREENS
}

fn should_present_agent_notification(
    app_backgrounded: bool,
    workbench_open: bool,
    selected_session_id: Option<&VibexSessionId>,
    target_session_id: &VibexSessionId,
    preferences: &NotificationPreferences,
) -> bool {
    if !preferences.enabled {
        return false;
    }
    if !(app_backgrounded || workbench_open || selected_session_id != Some(target_session_id)) {
        return false;
    }
    true
}

/// The notification categories the phone is allowed to raise.
#[derive(Clone, Copy, Debug)]
struct NotificationPreferences {
    enabled: bool,
    completed: bool,
    needs_input: bool,
    failed: bool,
}

impl From<&AppSettings> for NotificationPreferences {
    fn from(settings: &AppSettings) -> Self {
        Self {
            enabled: settings.notifications,
            completed: settings.notify_completed,
            needs_input: settings.notify_needs_input,
            failed: settings.notify_failed,
        }
    }
}

impl NotificationPreferences {
    /// Whether one event's category is switched on.
    fn allows(&self, notification: &vibex_core::AgentNotificationIntent) -> bool {
        use vibex_core::AgentNotificationKind as Kind;
        match notification.kind {
            Kind::TurnCompleted => self.completed,
            Kind::ApprovalRequired { .. } | Kind::InputRequired { .. } => self.needs_input,
            Kind::TurnFailed => self.failed,
        }
    }
}

fn sidebar_refresh_required(event: &BackendEvent) -> bool {
    match event {
        BackendEvent::ProjectionInvalidated(BackendProjection::Sidebar) => true,
        BackendEvent::Lagged { refetch, .. } => {
            refetch.projection == Some(BackendProjection::Sidebar)
        }
        _ => false,
    }
}

