    fn render_turn_file_changes_card(
        &self,
        turn: &TimelineConversationTurn,
        cx: &mut Context<Self>,
    ) -> Option<gpui::AnyElement> {
        if !turn.complete {
            return None;
        }
        let mut seen_paths = BTreeSet::new();
        let mut changed_rows = Vec::new();
        for row in turn.process_rows.iter().rev() {
            if row.kind != TimelineRowKind::FileOperation {
                continue;
            }
            let changed = match self.timeline_row_latest_payload(row) {
                Some(TimelinePayload::FileOperation(operation)) => {
                    operation.operation != vibex_core::FileOperationKind::Read
                }
                _ => true,
            };
            if !changed {
                continue;
            }
            let path = row.file_path.as_deref().unwrap_or(row.title.as_str());
            if seen_paths.insert(path.to_string()) {
                changed_rows.push(row);
            }
        }
        if changed_rows.is_empty() {
            return None;
        }
        changed_rows.reverse();
        let expansion_id = format!("turn-file-changes:{}", turn.id);
        let expanded = self.timeline_row_expanded(&expansion_id);
        let visible_count = if expanded {
            changed_rows.len()
        } else {
            changed_rows.len().min(3)
        };
        let hidden_count = changed_rows.len().saturating_sub(visible_count);
        let expansion_id_for_toggle = expansion_id.clone();
        Some(
            div()
                .id(expansion_id)
                .w_full()
                .min_w_0()
                .overflow_hidden()
                .rounded(px(theme::RADIUS_CARD))
                .border_1()
                .border_color(theme::border_default())
                .bg(theme::bg_card_dim())
                .child(
                    div()
                        .id(format!("turn-file-changes-header:{}", turn.id))
                        .w_full()
                        .min_h(px(40.0))
                        .px_3()
                        .flex()
                        .items_center()
                        .gap_2()
                        .when(changed_rows.len() > 3, |header| {
                            header
                                .cursor_pointer()
                                .active(|style| style.bg(theme::row_pressed_bg()))
                                .on_mouse_up(
                                    MouseButton::Left,
                                    cx.listener(move |this, _, _, cx| {
                                        this.toggle_timeline_row(
                                            expansion_id_for_toggle.clone(),
                                            cx,
                                        )
                                    }),
                                )
                        })
                        .child(
                            svg()
                                .path("icons/file-code.svg")
                                .size(px(theme::ICON_SM))
                                .flex_shrink_0()
                                .text_color(theme::accent_blue()),
                        )
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .text_size(theme::font_caption())
                                .text_color(theme::text_secondary())
                                .child(format!(
                                    "{} {}",
                                    changed_rows.len(),
                                    locale::text("files changed", "个文件变更", "個檔案變更")
                                )),
                        )
                        .when(changed_rows.len() > 3, |header| {
                            header.child(
                                svg()
                                    .path(if expanded {
                                        "icons/chevron-down.svg"
                                    } else {
                                        "icons/chevron-right.svg"
                                    })
                                    .size(px(theme::ICON_SM))
                                    .flex_shrink_0()
                                    .text_color(theme::text_muted()),
                            )
                        }),
                )
                .child(
                    div()
                        .border_t_1()
                        .border_color(theme::border_subtle())
                        .flex()
                        .flex_col()
                        .children(
                            changed_rows
                                .iter()
                                .take(visible_count)
                                .map(|row| self.render_turn_file_change_row(row, cx)),
                        )
                        .when(hidden_count > 0, |rows| {
                            rows.child(
                                div()
                                    .px_3()
                                    .py_2()
                                    .text_size(theme::font_micro())
                                    .text_color(theme::text_muted())
                                    .child(format!(
                                        "{} {}",
                                        locale::text("Show", "显示", "顯示"),
                                        hidden_count
                                    )),
                            )
                        }),
                )
                .into_any_element(),
        )
    }

    fn render_turn_file_change_row(
        &self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let operation_path =
            self.timeline_row_latest_payload(row)
                .and_then(|payload| match payload {
                    TimelinePayload::FileOperation(operation) => Some(operation.path.clone()),
                    _ => None,
                });
        let title = match &operation_path {
            Some(path) => format!(
                "{} {}",
                self.timeline_row_latest_payload(row)
                    .and_then(|payload| match payload {
                        TimelinePayload::FileOperation(operation) => {
                            Some(file_operation_verb(operation.operation))
                        }
                        _ => None,
                    })
                    .unwrap_or_default(),
                path
            ),
            None => process_title(row),
        };
        // The change's size is what tells one row from another at a glance; a
        // row whose operation carries no readable patch simply has none.
        let counts = self
            .timeline_row_latest_payload(row)
            .and_then(|payload| match payload {
                TimelinePayload::FileOperation(operation) => {
                    crate::file_diff::line_counts(operation)
                }
                _ => None,
            });
        let diff_row = row.clone();
        let diff_path = operation_path.clone();
        let mut element = div()
            .id(format!("timeline-file-row:{title}"))
            .w_full()
            .min_w_0()
            .min_h(px(44.0))
            .px_3()
            .flex()
            .items_center()
            .gap_2()
            .border_b_1()
            .border_color(theme::border_subtle());
        // A path the agent wrote is a door, not a label: the desktop opens the
        // file, and so does the phone — into the right rail's editor.
        if let Some(path) = operation_path {
            element = element
                .cursor_pointer()
                .aria_label(path.clone())
                .active(|style| style.bg(theme::row_pressed_bg()))
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, event, window, cx| {
                        this.open_timeline_file(path.clone(), event, window, cx)
                    }),
                );
        }
        element = element
            .child(
                svg()
                    .path("icons/file-code.svg")
                    .size(px(theme::ICON_SM))
                    .flex_shrink_0()
                    .text_color(theme::accent_blue()),
            )
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .overflow_hidden()
                    .text_ellipsis()
                    .whitespace_nowrap()
                    .text_size(theme::font_micro())
                    .text_color(theme::text_secondary())
                    .child(title),
            )
            .when_some(counts, |row, (added, removed)| {
                row.child(
                    div()
                        .flex_shrink_0()
                        .flex()
                        .items_center()
                        .gap_1()
                        .text_size(theme::font_micro())
                        .when(added > 0, |counts| {
                            counts.child(
                                div()
                                    .text_color(theme::accent_green())
                                    .child(format!("+{added}")),
                            )
                        })
                        .when(removed > 0, |counts| {
                            counts.child(
                                div()
                                    .text_color(theme::accent_red())
                                    .child(format!("−{removed}")),
                            )
                        }),
                )
            })
            // The row itself opens the file, which is what a reader wants most
            // of the time. The change is the second question, so it gets the
            // second control rather than replacing the first.
            .when_some(diff_path, |row, path| {
                row.child(
                    timeline_action_button(
                        format!("timeline-file-diff:{}", diff_row.id),
                        "icons/chevrons-right-left.svg",
                        locale::text("View changes", "查看变更", "檢視變更"),
                    )
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(move |this, _, _, cx| {
                            cx.stop_propagation();
                            this.open_timeline_file_diff(&diff_row, path.clone(), cx);
                        }),
                    ),
                )
            });
        element.into_any_element()
    }

    /// Opens one file change as a full screen.
    fn open_timeline_file_diff(&mut self, row: &TimelineRow, path: String, cx: &mut Context<Self>) {
        let preview = self
            .timeline_row_latest_payload(row)
            .and_then(|payload| match payload {
                TimelinePayload::FileOperation(operation) => crate::file_diff::project(operation),
                _ => None,
            });
        let Some(preview) = preview else {
            self.hint(
                Tone::Info,
                locale::text(
                    "This change carries no readable diff",
                    "这次变更没有可读的差异内容",
                    "這次變更沒有可讀的差異內容",
                ),
            );
            cx.notify();
            return;
        };
        self.timeline_file_diff = Some(MobileTimelineFileDiff { path, preview });
        cx.notify();
    }

    fn render_composer(
        &self,
        running: bool,
        state: Option<AgentSessionState>,
        turns: &[TimelineConversationTurn],
        _window: &Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let latest_ended_normally = turns
            .last()
            .map(|turn| turn.complete && !turn.failed && !turn.pending_permission);
        let needs_continue = state.is_some_and(|state| {
            agent_session_turn_requires_continuation(state, latest_ended_normally)
        });
        let runtime_switch_pending = self.runtime_switch_busy_generation.is_some();
        let has_text = !self.composer_input.read(cx).value().trim().is_empty();
        // An image on its own is a prompt: the manager takes a message whose
        // text is empty as long as it carries an attachment.
        let has_content = has_text || !self.composer_attachments.is_empty();
        // A live turn does not close the composer. It changes what Send means:
        // the prompt is held in the queue above the field and goes out when the
        // turn settles, which is the only way a phone can write ahead.
        let turn_live = running || self.turn_submissions_in_flight > 0;
        let send_enabled = has_content && state.is_some() && !self.composer_busy();
        let attach_enabled = state.is_some()
            && !self.composer_busy()
            && self.composer_attachments.len() < MOBILE_MAX_COMPOSER_ATTACHMENTS;
        let editing_message = self.composer_message_edit.is_some();
        let stop_enabled = state.is_some()
            && !self.composer_busy()
            && !self.turn_interrupt_in_flight
            && !runtime_switch_pending;
        // The single primary control is Stop only while a turn runs and there
        // is nothing to send; the moment the reader writes anything it is Send
        // again, so the field and the button never disagree about the action.
        let primary_stop = turn_live && !has_content;
        // The clock is a permanent resident of the card's top-right corner
        // whenever a session is open, so the field's clearance and the control
        // itself do not jump as the reader types. It only becomes armed — and
        // only opens the sheet — once there is something to schedule.
        let schedule_shown = state.is_some() && !editing_message;
        let schedule_enabled = schedule_shown && has_content;
        let usage_fraction = self.token_usage.as_ref().and_then(token_usage_fraction);
        let usage_percent = usage_fraction.unwrap_or(0.0) * 100.0;
        let usage_color = match usage_fraction {
            Some(fraction) if fraction > 0.9 => theme::accent_red(),
            Some(fraction) if fraction >= 0.7 => theme::accent_yellow(),
            _ => theme::text_muted(),
        };
        let usage_reported = self.token_usage.is_some();
        let suggestions = self.composer_suggestions(cx);
        let composer_plan = self.render_composer_plan(cx);
        let composer_goal = self.render_composer_goal(cx);
        let delegation_target = self.composer_delegation_target(cx);
        let queued = self.composer_queue_for_open_session();
        let runtime_selection = self.controller.as_ref().and_then(|controller| {
            controller
                .state
                .runtime_selection
                .value
                .as_ref()
                .map(|state| &state.desired)
        });
        let runtime_catalog = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.runtime_options.value.as_ref());
        let runtime_summary = runtime_selection_summary(runtime_catalog, runtime_selection);
        // The control row names the model rather than the whole runtime: the
        // chip has one line, and the sheet behind it is where the Agent, the
        // authentication source and the mode are read together.
        let model_id = match runtime_selection.map(|selection| &selection.model) {
            Some(vibex_core::RuntimeModelSelection::Explicit { model_id }) => {
                Some(model_id.clone())
            }
            _ => None,
        };
        let model_label = runtime_catalog
            .zip(runtime_selection)
            .and_then(|(catalog, selection)| matching_runtime_option(&catalog.options, selection))
            .map(|option| option.model_label.clone())
            .unwrap_or_else(|| {
                model_id
                    .clone()
                    .unwrap_or_else(|| locale::common("Default").to_string())
            });
        // Which of the Agent's own options the control row offers, and which of
        // them the session has been moved off the Agent's default for.
        let projection = runtime_catalog
            .zip(runtime_selection)
            .map(|(catalog, selection)| RuntimeCascadeProjection::from_catalog(catalog, selection))
            .unwrap_or_default();
        let reasoning_offered = !projection.reasoning_efforts.is_empty();
        let modes_offered = !projection.modes.is_empty();
        let features_offered = !projection.features.is_empty();
        let reasoning_set =
            runtime_selection.is_some_and(|selection| selection.reasoning_effort.is_some());
        let mode_set = runtime_selection.is_some_and(|selection| selection.mode_id.is_some());
        let options_set =
            runtime_selection.is_some_and(|selection| !selection.config_values.is_empty());
        div()
            .flex_shrink_0()
            .bg(theme::bg_primary())
            .p(px(theme::SPACING_MD))
            // The trigger's panel sits directly above the field it is
            // completing, the way a phone keyboard's own suggestion strip does.
            .when_some(suggestions, |composer, suggestions| {
                composer.child(self.render_composer_suggestion_panel(
                    &suggestions,
                    ComposerSuggestionTarget::Session,
                    cx,
                ))
            })
            // What the Agent is working through, then what the reader has
            // written ahead: both sit between the suggestions and the field.
            // Handing the draft to someone else is a choice about the whole
            // message, so it sits with the goal and the plan rather than in the
            // field's own control strip.
            .when_some(delegation_target, |composer, target| {
                composer.child(self.render_composer_delegation(&target, cx))
            })
            // The standing objective sits above the plan it is being worked
            // through: the goal is why, the plan is how.
            .when_some(composer_goal, |composer, goal| composer.child(goal))
            .when_some(composer_plan, |composer, plan| composer.child(plan))
            .when(!queued.is_empty(), |composer| {
                composer.child(self.render_composer_queue(&queued, cx))
            })
            .when(editing_message, |composer| {
                composer.child(self.render_composer_edit_banner(cx))
            })
            .when(needs_continue, |composer| {
                composer.child(
                    div()
                        .id("continue-turn")
                        .mb(px(theme::SPACING_SM))
                        .h(px(36.0))
                        .rounded(px(theme::RADIUS_CONTROL))
                        .border_1()
                        .border_color(theme::border_default())
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_size(theme::font_body())
                        .text_color(if self.operation_busy {
                            theme::text_muted()
                        } else {
                            theme::text_secondary()
                        })
                        .when(!self.operation_busy, |button| {
                            button
                                .cursor_pointer()
                                .active(|style| style.bg(theme::row_pressed_bg()))
                                .on_mouse_up(MouseButton::Left, cx.listener(Self::continue_turn))
                        })
                        .child(if self.operation_busy {
                            locale::text("Continuing…", "继续中…", "繼續中…")
                        } else {
                            locale::common("Continue")
                        }),
                )
            })
            // One card, two lines: what the reader is writing on top, and what
            // it will run on underneath. The runtime row and the token row that
            // used to sit below the field are gone — the chip reports the first
            // and the ring the second, on the line the reader is already using.
            .child(
                div()
                    .id("mobile-composer-card")
                    .relative()
                    .min_h(px(52.0))
                    // The card is a message being written, so it wears the
                    // message plate's fill and radius. Its corners are all
                    // round: the one square corner it used to carry at the
                    // top-right read as a cut-off edge on a phone rather than
                    // as an affordance.
                    .rounded(px(theme::RADIUS_COMPOSER))
                    .border_1()
                    .border_color(theme::border_default())
                    .bg(theme::composer_surface())
                    .p(px(theme::SPACING_MD))
                    .flex()
                    .flex_col()
                    .gap(px(theme::SPACING_SM))
                    // What the message carries sits inside the field it
                    // belongs to: the chips are part of the draft, and a phone
                    // has no text editor to draw them in the typing line.
                    .when(!self.composer_attachments.is_empty(), |card| {
                        card.child(self.render_composer_attachments(cx))
                    })
                    .child(
                        div()
                            .w_full()
                            // Keep the typed line clear of the schedule control
                            // parked in the card's top-right corner.
                            .when(schedule_shown, |field| field.pr(px(theme::TOUCH_TARGET)))
                            .min_h(px(theme::TOUCH_TARGET))
                            .on_mouse_down(MouseButton::Left, resume_keyboard_on_tap)
                            .child(
                                Textarea::new(&self.composer_input)
                                    .appearance(false)
                                    .text_size(theme::font_composer())
                                    // The field is where the reader writes, so
                                    // its text is body copy rather than the
                                    // chrome grey the rest of the window
                                    // inherits; the placeholder keeps the
                                    // kit's muted tone.
                                    .text_color(theme::text_primary())
                                    // The long press hook is the only signal the
                                    // platform gives for "the user selected this
                                    // word": open the touch toolbar instead of the
                                    // kit's keyboard-oriented menu, which would
                                    // take focus and collapse the keyboard.
                                    .context_menu({
                                        let menu = self.selection_menu.downgrade();
                                        move |items, _window, cx| {
                                            if let Some(menu) = menu.upgrade() {
                                                menu.update(cx, |menu, cx| menu.open(cx));
                                            }
                                            items
                                        }
                                    }),
                            ),
                    )
                    .child(
                        div()
                            .w_full()
                            .h(px(theme::TOUCH_TARGET))
                            .flex()
                            .items_center()
                            // The attach menu offers the two things a phone can
                            // hand over: a photo the host scales down, or a file
                            // it carries whole. It sits against the card's own
                            // leading inset rather than a control row's, so the
                            // options beside it keep their full width.
                            .child(
                                composer_icon_button(
                                    "attach-file",
                                    "icons/plus.svg",
                                    locale::text("Attach a file", "添加附件", "新增附件")
                                        .to_string(),
                                    attach_enabled,
                                    cx.listener(Self::open_composer_attach_menu),
                                )
                                .ml(px(-theme::SPACING_MD)),
                            )
                            // The model is the chip's whole story here: the mode
                            // the session is running under was chosen when it
                            // started, and the drawer behind this chip is where
                            // either one is read or changed. Its name is always
                            // spelled: the chip takes what the row has left and
                            // is the first thing to give way when the Agent's own
                            // glyphs need it, rather than the reader being told
                            // only which brand answered.
                            .child(
                                composer_chip(
                                    "composer-runtime-options",
                                    runtime_model_icon(
                                        model_id.as_deref(),
                                        px(theme::ICON_MD),
                                        theme::text_secondary(),
                                    ),
                                    model_label,
                                    !runtime_summary.available,
                                    false,
                                    true,
                                    ComposerChipAction::SessionModel,
                                    cx,
                                )
                                .flex_1()
                                .min_w_0(),
                            )
                            // The Agent's own options, as glyphs and nothing
                            // else: the value of a reasoning effort or a
                            // permission mode is read in the drawer it opens,
                            // and reading four of them off the control row is
                            // what used to squeeze the model chip out of it.
                            .when(reasoning_offered, |row| {
                                row.child(composer_option_button(
                                    "composer-reasoning",
                                    "icons/brain.svg",
                                    locale::common("Reasoning").to_string(),
                                    reasoning_set,
                                    !self.operation_busy && !runtime_switch_pending,
                                    cx.listener(Self::open_runtime_reasoning_drawer),
                                ))
                            })
                            .when(modes_offered, |row| {
                                row.child(composer_option_button(
                                    "composer-mode",
                                    "icons/shield-alert.svg",
                                    locale::common("Mode").to_string(),
                                    mode_set,
                                    !self.operation_busy && !runtime_switch_pending,
                                    cx.listener(Self::open_runtime_mode_drawer),
                                ))
                            })
                            .when(features_offered, |row| {
                                row.child(composer_option_button(
                                    "composer-session-options",
                                    "icons/sliders-horizontal.svg",
                                    locale::text("Session options", "会话选项", "工作階段選項")
                                        .to_string(),
                                    options_set,
                                    !self.operation_busy && !runtime_switch_pending,
                                    cx.listener(Self::open_session_options_drawer),
                                ))
                            })
                            // The ring: the one usage surface a phone gets, and
                            // the only place the reader can tell how full the
                            // context window is before the next turn fails on it.
                            .child(
                                div()
                                    .id("composer-token-usage")
                                    .size(px(theme::COMPOSER_OPTION_SIZE))
                                    .flex_shrink_0()
                                    .rounded_full()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .aria_label(locale::text(
                                        "Token usage",
                                        "Token 使用情况",
                                        "Token 使用情況",
                                    ))
                                    .cursor_pointer()
                                    .active(|style| style.bg(theme::row_pressed_bg()))
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(|this, _, _, cx| this.show_token_usage(cx)),
                                    )
                                    .child(
                                        // The ring is drawn at the size of the
                                        // glyphs beside it rather than the
                                        // kit's, inside the same target every
                                        // other control on the row keeps.
                                        div().size(px(theme::COMPOSER_RING_SIZE)).child(
                                            ProgressCircle::new("composer-token-ring")
                                                .value(usage_percent)
                                                .size_full()
                                                .color(if usage_reported {
                                                    usage_color
                                                } else {
                                                    theme::text_muted()
                                                }),
                                        ),
                                    ),
                            )
                            // Send and Stop are the same target, so the row keeps
                            // one slot for the page's commitment. With an empty
                            // field and a turn running it stops the turn; with
                            // anything written it sends — queueing the message
                            // against the running turn rather than replacing the
                            // control the reader needs to speak.
                            .child(if primary_stop {
                                composer_primary_button(
                                    "stop-turn",
                                    locale::common("Stop").to_string(),
                                    ComposerPrimaryAction::Stop,
                                    stop_enabled,
                                    false,
                                    cx.listener(Self::interrupt),
                                )
                            } else {
                                composer_primary_button(
                                    "send-message",
                                    if editing_message {
                                        locale::text("Replace message", "替换消息", "取代訊息")
                                            .to_string()
                                    } else if turn_live {
                                        // A live turn cannot take a prompt over
                                        // the wire, so this is not a steer: the
                                        // message is held and goes out when the
                                        // turn settles.
                                        locale::text(
                                            "Queue for the turn",
                                            "排入队列，回合结束后发送",
                                            "排入佇列，回合結束後傳送",
                                        )
                                        .to_string()
                                    } else {
                                        locale::common("Send").to_string()
                                    },
                                    ComposerPrimaryAction::Send,
                                    send_enabled,
                                    false,
                                    cx.listener(Self::send_message),
                                )
                            }),
                    )
                    // Scheduling is the one thing a phone cannot do for itself:
                    // the queue belongs to the desktop, so the message travels
                    // there and waits. It lives in the card's top-right corner,
                    // the same corner the desktop keeps it in, and stays there
                    // for as long as the session is: dimmed until there is
                    // something to schedule, so the corner never shifts.
                    .when(schedule_shown, |card| {
                        card.child(
                            div()
                                .id("schedule-message")
                                .debug_selector(|| "schedule-message".to_string())
                                .aria_label(
                                    locale::text("Schedule send", "定时发送", "定時傳送")
                                        .to_string(),
                                )
                                .absolute()
                                .top(px(theme::SPACING_SM))
                                .right(px(theme::SPACING_SM))
                                .size(px(theme::TOUCH_TARGET))
                                .rounded_full()
                                .flex()
                                .items_center()
                                .justify_center()
                                .when(schedule_enabled, |clock| {
                                    clock
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(|this, _, _, cx| {
                                                this.begin_composer_schedule(cx)
                                            }),
                                        )
                                })
                                .when(!schedule_enabled, |clock| clock.opacity(0.42))
                                .child(
                                    svg()
                                        .path("icons/clock.svg")
                                        .size(px(theme::ICON_MD))
                                        .text_color(if schedule_enabled {
                                            theme::text_secondary()
                                        } else {
                                            theme::text_muted()
                                        }),
                                ),
                        )
                    }),
            )
    }

    /// The `/`, `@`, and `$` suggestion panel, drawn as the tabs its trigger
    /// opens.
    ///
    /// One panel serves both pages and all three characters: the header is what
    /// says which trigger opened it, and each tab is one of the lists that
    /// trigger carries. Choosing a command either arms the draft with something
    /// executable or inserts reusable text; choosing a reference inserts its
    /// label and remembers the reference; a skill inserts its own `$name`
    /// invocation.
    fn render_composer_suggestion_panel(
        &self,
        suggestions: &ComposerSuggestions,
        target: ComposerSuggestionTarget,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let tabs = suggestions.tabs();
        let active = suggestions.active_tab(target.tab(self));
        let rows = suggestions.rows(active);
        let action = suggestion_action(suggestions.trigger, active);
        let muted_note = if suggestions.loading {
            locale::text("Loading…", "加载中…", "載入中…").to_string()
        } else if active == ComposerSuggestionTab::Phrases && suggestions.query.is_empty() {
            locale::text("No quick phrases yet", "还没有快捷短语", "還沒有快捷短語").to_string()
        } else {
            locale::text("No matches", "没有匹配项", "沒有符合項目").to_string()
        };
        div()
            .id(target.element_id())
            .debug_selector(move || target.element_id().to_string())
            .mb(px(theme::SPACING_SM))
            .max_h(px(200.0))
            .rounded(px(theme::RADIUS_CARD))
            .border_1()
            .border_color(theme::border_default())
            .bg(theme::bg_card())
            .overflow_hidden()
            .flex()
            .flex_col()
            // A trigger with one list wears no header: `$` is a list, not a
            // pair of lists, and a tab bar with one tab is furniture.
            .when(tabs.len() > 1, |panel| {
                panel.child(self.render_composer_suggestion_tabs(suggestions, target, active, cx))
            })
            .child(
                div()
                    .id(target.scroll_id())
                    .overflow_y_scroll()
                    .restrict_scroll_to_axis()
                    .when(rows.is_empty(), |body| {
                        body.child(
                            div()
                                .min_h(px(theme::TOUCH_TARGET))
                                .px(px(theme::SPACING_MD))
                                .flex()
                                .items_center()
                                .text_size(theme::font_micro())
                                .text_color(theme::text_muted())
                                .child(muted_note),
                        )
                    })
                    .children(rows.iter().map(|entry| {
                        self.render_composer_suggestion_row(entry, action, target, cx)
                    })),
            )
            .into_any_element()
    }

    /// The tab header of a trigger that opens more than one list.
    ///
    /// The tabs are text with the accent's underline on the open one, the way
    /// the desktop's popup draws them: a bar of pills would compete with the
    /// rows under it, and the rows are what the reader came for.
    fn render_composer_suggestion_tabs(
        &self,
        suggestions: &ComposerSuggestions,
        target: ComposerSuggestionTarget,
        active: ComposerSuggestionTab,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        div()
            .flex_shrink_0()
            .h(px(theme::TOUCH_TARGET))
            .px(px(theme::SPACING_SM))
            .flex()
            .items_center()
            .border_b_1()
            .border_color(theme::border_subtle())
            .children(suggestions.tabs().iter().copied().map(|tab| {
                let selected = tab == active;
                div()
                    .id(format!("{}-tab:{}", target.element_id(), tab.id()))
                    .debug_selector(move || format!("{}-tab:{}", target.element_id(), tab.id()))
                    .h_full()
                    .px(px(theme::SPACING_SM))
                    .flex()
                    .items_center()
                    .border_b_2()
                    .border_color(if selected {
                        theme::accent_blue()
                    } else {
                        theme::border_subtle().opacity(0.0)
                    })
                    .text_size(theme::font_caption())
                    .text_color(if selected {
                        theme::text_primary()
                    } else {
                        theme::text_muted()
                    })
                    .cursor_pointer()
                    .aria_label(tab.label())
                    .aria_selected(selected)
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(move |this, _, _, cx| {
                            this.select_composer_suggestion_tab(target, tab, cx)
                        }),
                    )
                    .child(tab.label())
            }))
            .into_any_element()
    }

    /// One row of the suggestion panel.
    ///
    /// What the row reads as follows the tab it belongs to: a command leads with
    /// the `/name` the draft will become, a skill with its `$name`, a reference
    /// with the `@name` it inserts, and a quick phrase — which has no trigger
    /// character — with its own name. The line beside the token is what the row
    /// is: the authority's description, the path behind a file, the account and
    /// model behind a collaborator.
    fn render_composer_suggestion_row(
        &self,
        entry: &AgentCommandEntry,
        action: ComposerSuggestionAction,
        target: ComposerSuggestionTarget,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let entry = entry.clone();
        let destructive = entry.destructive;
        let executable =
            action == ComposerSuggestionAction::Command && is_executable_command_source(&entry);
        let refers = action == ComposerSuggestionAction::Mention;
        // A file reference shows the path behind its name; every other
        // reference shows the description the authority wrote — a
        // collaborator's account and model, a session's Agent — because those
        // have no path and the configurations of one Agent are otherwise
        // identical rows. The same split the desktop draws.
        let description = entry
            .reference_path
            .clone()
            .filter(|_| entry.source_kind == AgentCommandSourceKind::Reference)
            .or_else(|| entry.description.as_deref().map(runtime_attribution_line));
        let name = entry
            .command_name
            .clone()
            .unwrap_or_else(|| entry.label.clone());
        // The token is what the field will hold; the line beside it says what
        // the row is. A row the authority described no further stands on its
        // token alone rather than repeating it: `/review` over "review" would
        // tell the reader nothing twice.
        let (leading, detail) = match action {
            ComposerSuggestionAction::Phrase => (entry.label.clone(), description.clone()),
            ComposerSuggestionAction::Command => (
                format!("/{}", name.trim_start_matches('/')),
                description.clone(),
            ),
            ComposerSuggestionAction::Skill => (
                format!("${}", name.trim_start_matches('$')),
                description.clone(),
            ),
            ComposerSuggestionAction::Mention => (entry.label.clone(), description.clone()),
        };
        let aria_label = match detail.as_deref() {
            Some(detail) => format!("{leading}, {detail}"),
            None => leading.clone(),
        };
        let row_id = format!("composer-suggestion:{}:{}", target.element_id(), entry.id);
        div()
            .id(row_id)
            .min_h(px(theme::TOUCH_TARGET))
            .px(px(theme::SPACING_MD))
            .flex()
            .items_center()
            .gap(px(theme::SPACING_SM))
            .border_b_1()
            .border_color(theme::border_subtle())
            .cursor_pointer()
            .aria_label(aria_label)
            .active(|style| style.bg(theme::row_pressed_bg()))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(move |this, _, window, cx| {
                    let entry = entry.clone();
                    match (target, action) {
                        (ComposerSuggestionTarget::Session, ComposerSuggestionAction::Command) => {
                            this.choose_composer_command(entry, window, cx)
                        }
                        (ComposerSuggestionTarget::Session, ComposerSuggestionAction::Skill) => {
                            this.choose_composer_skill(entry, window, cx)
                        }
                        (ComposerSuggestionTarget::Session, ComposerSuggestionAction::Mention) => {
                            this.choose_composer_mention(entry, window, cx)
                        }
                        (ComposerSuggestionTarget::Session, ComposerSuggestionAction::Phrase) => {
                            this.choose_composer_command(entry, window, cx)
                        }
                        (
                            ComposerSuggestionTarget::NewSession,
                            ComposerSuggestionAction::Command,
                        ) => this.choose_new_session_command(entry, window, cx),
                        (ComposerSuggestionTarget::NewSession, ComposerSuggestionAction::Skill) => {
                            this.choose_new_session_skill(entry, window, cx)
                        }
                        (
                            ComposerSuggestionTarget::NewSession,
                            ComposerSuggestionAction::Mention,
                        ) => this.choose_new_session_mention(entry, window, cx),
                        (
                            ComposerSuggestionTarget::NewSession,
                            ComposerSuggestionAction::Phrase,
                        ) => this.choose_new_session_command(entry, window, cx),
                    }
                }),
            )
            .child(
                div()
                    .flex_shrink_0()
                    .max_w(px(140.0))
                    .overflow_hidden()
                    .text_ellipsis()
                    .whitespace_nowrap()
                    .font_family(theme::MONO_FONT_FAMILY)
                    .text_size(theme::font_caption())
                    .text_color(if destructive {
                        theme::accent_red()
                    } else {
                        theme::accent_blue()
                    })
                    .child(leading),
            )
            .child(div().flex_1().min_w_0().flex().flex_col().when_some(
                detail,
                |labels, detail| {
                    labels.child(
                        div()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_micro())
                            .text_color(theme::text_primary())
                            .child(detail),
                    )
                },
            ))
            .child(
                div()
                    .flex_shrink_0()
                    .text_size(theme::font_micro())
                    .text_color(theme::text_muted())
                    .child(if refers {
                        locale::text("Refers", "引用", "引用")
                    } else if executable {
                        locale::text("Runs", "执行", "執行")
                    } else {
                        locale::text("Inserts", "插入", "插入")
                    }),
            )
            .into_any_element()
    }

    /// Switches the panel to `tab` from a tap on its header.
    fn select_composer_suggestion_tab(
        &mut self,
        target: ComposerSuggestionTarget,
        tab: ComposerSuggestionTab,
        cx: &mut Context<Self>,
    ) {
        let current = match target {
            ComposerSuggestionTarget::Session => &mut self.composer_suggestion_tab,
            ComposerSuggestionTarget::NewSession => &mut self.new_session_suggestion_tab,
        };
        if *current == tab {
            return;
        }
        *current = tab;
        cx.notify();
    }

    /// The plan bar above the composer.
    ///
    /// The desktop keeps the running plan one click from the input, and a phone
    /// needs it more, not less: the timeline scrolls away while the reader
    /// types. Collapsed it is a single touch row; the chevron opens the steps,
    /// and closing it is remembered per plan revision.
    fn render_composer_plan(&self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let session_id = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.selected_session_id.clone())?;
        let plan = {
            let timeline = self.display_timeline()?;
            current_mobile_plan(&timeline.items)?
        };
        let identity = (session_id.as_str().to_string(), plan.sequence);
        if self.dismissed_composer_plans.contains(&identity) {
            return None;
        }

        let total_steps = plan.steps.len();
        let completed_steps = plan.completed_step_count();
        let current_step_number = plan.current_step_number();
        let complete = plan.is_complete();
        let current_step = plan.steps.get(current_step_number.saturating_sub(1));
        let failed = current_step.is_some_and(|step| step.status == PlanStepStatus::Failed);
        let accent = if complete {
            theme::accent_success()
        } else if failed {
            theme::accent_red()
        } else {
            theme::accent_blue()
        };
        let plan_title = if plan.title.trim().is_empty() {
            locale::text("Current plan", "当前计划", "目前計劃").to_string()
        } else {
            plan.title.clone()
        };
        let current_step_title = current_step
            .map(|step| step.title.trim())
            .filter(|title| !title.is_empty())
            .unwrap_or_else(|| locale::text("Plan in progress", "计划进行中", "計劃進行中"))
            .to_string();
        let progress_label = format!("{current_step_number}/{total_steps}");
        let expanded = self.composer_plan_expanded.as_ref() == Some(&identity);

        let toggle_identity = identity.clone();
        let dismiss_identity = identity.clone();
        let summary = div()
            .id("mobile-composer-plan")
            .debug_selector(|| "mobile-composer-plan".to_string())
            .mb(px(theme::SPACING_SM))
            .min_h(px(theme::TOUCH_TARGET))
            .rounded(px(theme::RADIUS_CARD))
            .border_1()
            .border_color(if complete {
                theme::accent_success().opacity(0.32)
            } else {
                theme::border_default()
            })
            .bg(theme::bg_card())
            .flex()
            .items_center()
            .gap(px(theme::SPACING_SM))
            .pl(px(theme::SPACING_MD))
            .pr(px(theme::SPACING_XS))
            .cursor_pointer()
            .active(|style| style.bg(theme::row_pressed_bg()))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(move |this, _, _, cx| {
                    if this.composer_plan_expanded.as_ref() == Some(&toggle_identity) {
                        this.composer_plan_expanded = None;
                    } else {
                        this.composer_plan_expanded = Some(toggle_identity.clone());
                    }
                    cx.notify();
                }),
            )
            .child(
                div().flex_shrink_0().child(
                    svg()
                        .path(if complete {
                            "icons/check.svg"
                        } else {
                            "icons/list-checks.svg"
                        })
                        .size(px(theme::ICON_MD))
                        .text_color(accent),
                ),
            )
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .overflow_hidden()
                    .text_ellipsis()
                    .whitespace_nowrap()
                    .text_size(theme::font_caption())
                    .text_color(if complete {
                        theme::text_secondary()
                    } else {
                        theme::text_primary()
                    })
                    .child(format!("{plan_title} · {current_step_title}")),
            )
            .child(
                div()
                    .flex_shrink_0()
                    .text_size(theme::font_micro())
                    .text_color(if failed {
                        theme::accent_red()
                    } else {
                        theme::text_muted()
                    })
                    .child(progress_label),
            )
            .child(
                div()
                    .id("mobile-composer-plan-close")
                    .size(px(32.0))
                    .flex_shrink_0()
                    .rounded(px(theme::RADIUS_CONTROL))
                    .flex()
                    .items_center()
                    .justify_center()
                    .cursor_pointer()
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .aria_label(locale::text("Close plan", "关闭计划", "關閉計劃").to_string())
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(move |this, _, _, cx| {
                            cx.stop_propagation();
                            this.dismissed_composer_plans
                                .insert(dismiss_identity.clone());
                            if this.composer_plan_expanded.as_ref() == Some(&dismiss_identity) {
                                this.composer_plan_expanded = None;
                            }
                            cx.notify();
                        }),
                    )
                    .child(
                        svg()
                            .path("icons/x.svg")
                            .size(px(theme::ICON_SM))
                            .text_color(theme::text_muted()),
                    ),
            );

        if !expanded {
            return Some(summary.into_any_element());
        }

        let completed_label = format!(
            "{completed_steps}/{total_steps} {}",
            locale::text("completed", "已完成", "已完成")
        );
        let steps = div()
            .id("mobile-composer-plan-steps")
            .max_h(px(220.0))
            .overflow_y_scroll()
            .restrict_scroll_to_axis()
            .pb(px(theme::SPACING_XS))
            .children(plan.steps.iter().enumerate().map(|(index, step)| {
                let (status_color, status_glyph) = match step.status {
                    PlanStepStatus::Completed => (theme::accent_success(), "icons/check.svg"),
                    PlanStepStatus::Running => (theme::accent_blue(), "icons/loader-circle.svg"),
                    PlanStepStatus::Failed => (theme::accent_red(), "icons/triangle-alert.svg"),
                    PlanStepStatus::Pending => (theme::text_muted(), "icons/minus.svg"),
                };
                div()
                    .id(format!("mobile-composer-plan-step-{index}"))
                    .min_h(px(theme::TOUCH_TARGET))
                    .px(px(theme::SPACING_MD))
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_SM))
                    .child(
                        svg()
                            .path(status_glyph)
                            .size(px(theme::ICON_SM))
                            .text_color(status_color),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .text_size(theme::font_caption())
                            .text_color(if step.status == PlanStepStatus::Pending {
                                theme::text_secondary()
                            } else {
                                theme::text_primary()
                            })
                            .child(step.title.clone()),
                    )
                    .child(
                        div()
                            .flex_shrink_0()
                            .text_size(theme::font_micro())
                            .text_color(status_color)
                            .child(plan_step_status_label(step.status)),
                    )
            }));

        Some(
            div()
                .id("mobile-composer-plan-expanded")
                .debug_selector(|| "mobile-composer-plan-expanded".to_string())
                // The panel is the bar it was folded out of, plus the rows
                // above it: the bar keeps its own margin and its own border,
                // and the panel adds neither below them. Its frame is therefore
                // open along the bottom edge — the bar's border is the bottom
                // edge — which is what keeps the bar on exactly the line it was
                // on before the reader unfolded it.
                .rounded(px(theme::RADIUS_CARD))
                .border_t_1()
                .border_l_1()
                .border_r_1()
                .border_color(theme::border_default())
                .bg(theme::bg_card())
                .overflow_hidden()
                .flex()
                .flex_col()
                .child(
                    div()
                        .min_h(px(theme::TOUCH_TARGET))
                        .px(px(theme::SPACING_MD))
                        .flex()
                        .items_center()
                        .gap(px(theme::SPACING_SM))
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .overflow_hidden()
                                .text_ellipsis()
                                .whitespace_nowrap()
                                .text_size(theme::font_detail())
                                .font_weight(FontWeight::MEDIUM)
                                .text_color(theme::text_primary())
                                .child(plan_title),
                        )
                        .child(
                            div()
                                .flex_shrink_0()
                                .text_size(theme::font_micro())
                                .text_color(theme::text_muted())
                                .child(completed_label),
                        ),
                )
                .child(
                    div()
                        .h(px(1.0))
                        .mx(px(theme::SPACING_MD))
                        .bg(theme::border_subtle()),
                )
                .child(steps)
                .child(summary)
                .into_any_element(),
        )
    }

    /// The session's standing objective, as the authority last reported it.
    ///
    /// The goal is not a message: it is a durable instruction the Agent keeps
    /// working toward, and the desktop keeps it in a bar above the composer.
    /// The phone reads the same snapshot out of the timeline, so a goal set on
    /// either client shows up on both.
    fn current_goal(&self) -> Option<ActiveGoal> {
        let controller = self.controller.as_ref()?;
        let items = controller.state.timeline.items.as_slice();
        vibex_desktop_model::current_active_goal(items)
    }

    /// The goal bar: phase, objective, and what the provider is counting.
    ///
    /// Set and clear are not on the phone's wire — the protocol carries goal
    /// *snapshots* but no control call — so the bar is a read-out. Where the
    /// Agent offers a `goal` command, the expanded bar hands the reader the
    /// composer with that command spelled out, which is the one route to a new
    /// objective a phone actually has.
    fn render_composer_goal(&self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let active = self.current_goal()?;
        let expanded = self.composer_goal_expanded;
        let phase = active.goal.phase;
        let paused = phase == GoalPhase::Paused;
        let (phase_label, phase_color) = goal_phase_label(phase);
        let objective = active.goal.objective.clone();
        let progress = goal_progress_label(&active.goal);
        // A rewrite needs either the Agent's own goal command or a goal
        // surface that takes one; without either there is nothing to offer.
        let can_edit = self.composer_has_goal_command(cx) || self.goal_objective_action().is_some();
        let expanded_body = expanded.then(|| {
            div()
                .px(px(theme::SPACING_MD))
                .pb(px(theme::SPACING_SM))
                .flex()
                .flex_col()
                .gap(px(theme::SPACING_XS))
                .child(
                    div()
                        .text_size(theme::font_body())
                        .line_height(theme::line_height_for(theme::FONT_BODY))
                        .text_color(theme::text_primary())
                        .child(objective.clone()),
                )
                .children(progress.clone().map(|progress| {
                    div()
                        .text_size(theme::font_micro())
                        .text_color(theme::text_muted())
                        .child(progress)
                }))
                .child(
                    div()
                        .mt(px(theme::SPACING_XS))
                        .flex()
                        .items_center()
                        .gap(px(theme::SPACING_XS))
                        .child(
                            div()
                                .id("composer-goal-pause")
                                .flex_shrink_0()
                                .h(px(32.0))
                                .px(px(theme::SPACING_MD))
                                .rounded(px(theme::RADIUS_CONTROL))
                                .border_1()
                                .border_color(theme::border_default())
                                .flex()
                                .items_center()
                                .justify_center()
                                .text_size(theme::font_caption())
                                .text_color(theme::text_secondary())
                                .when(!self.operation_busy, |button| {
                                    button
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(move |this, _, _, cx| {
                                                this.control_session_goal(
                                                    if paused {
                                                        vibex_core::GoalAction::Resume
                                                    } else {
                                                        vibex_core::GoalAction::Pause
                                                    },
                                                    None,
                                                    cx,
                                                )
                                            }),
                                        )
                                })
                                .child(if paused {
                                    locale::text("Resume", "恢复", "恢復")
                                } else {
                                    locale::text("Pause", "暂停", "暫停")
                                }),
                        )
                        .child(
                            div()
                                .id("composer-goal-clear")
                                .flex_shrink_0()
                                .h(px(32.0))
                                .px(px(theme::SPACING_MD))
                                .rounded(px(theme::RADIUS_CONTROL))
                                .border_1()
                                .border_color(theme::border_default())
                                .flex()
                                .items_center()
                                .justify_center()
                                .text_size(theme::font_caption())
                                .text_color(theme::accent_red())
                                .when(!self.operation_busy, |button| {
                                    button
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(|this, _, _, cx| {
                                                this.control_session_goal(
                                                    vibex_core::GoalAction::Clear,
                                                    None,
                                                    cx,
                                                )
                                            }),
                                        )
                                })
                                .child(locale::text("Clear", "清除", "清除")),
                        ),
                )
                .when(can_edit, |body| {
                    body.child(
                        div()
                            .id("composer-goal-edit")
                            .mt(px(theme::SPACING_XS))
                            .min_h(px(36.0))
                            .px(px(theme::SPACING_MD))
                            .rounded(px(theme::RADIUS_CONTROL))
                            .border_1()
                            .border_color(theme::border_default())
                            .flex()
                            .items_center()
                            .justify_center()
                            .cursor_pointer()
                            .active(|style| style.bg(theme::row_pressed_bg()))
                            .text_size(theme::font_caption())
                            .text_color(theme::text_secondary())
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(|this, _, window, cx| {
                                    this.begin_composer_goal_edit(window, cx)
                                }),
                            )
                            .child(locale::text(
                                "Rewrite the objective",
                                "重写目标",
                                "重寫目標",
                            )),
                    )
                })
        });
        Some(
            div()
                .id("mobile-composer-goal")
                .debug_selector(|| "mobile-composer-goal".to_string())
                .mb(px(theme::SPACING_SM))
                .rounded(px(theme::RADIUS_CARD))
                .border_1()
                .border_color(theme::border_default())
                .bg(theme::bg_card())
                .overflow_hidden()
                .flex()
                .flex_col()
                .child(
                    div()
                        .id("mobile-composer-goal-header")
                        .min_h(px(theme::TOUCH_TARGET))
                        .px(px(theme::SPACING_MD))
                        .flex()
                        .items_center()
                        .gap(px(theme::SPACING_SM))
                        .cursor_pointer()
                        .active(|style| style.bg(theme::row_pressed_bg()))
                        .on_mouse_up(
                            MouseButton::Left,
                            cx.listener(|this, _, _, cx| {
                                this.composer_goal_expanded = !this.composer_goal_expanded;
                                cx.notify();
                            }),
                        )
                        .child(
                            svg()
                                .path("icons/crosshair.svg")
                                .size(px(theme::ICON_SM))
                                .flex_shrink_0()
                                .text_color(theme::primary()),
                        )
                        .child(
                            div()
                                .flex_shrink_0()
                                .text_size(theme::font_micro())
                                .text_color(phase_color)
                                .child(phase_label),
                        )
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .overflow_hidden()
                                .text_ellipsis()
                                .whitespace_nowrap()
                                .text_size(theme::font_caption())
                                .text_color(theme::text_primary())
                                .child(objective),
                        )
                        .child(
                            svg()
                                .path(if expanded {
                                    "icons/chevron-down.svg"
                                } else {
                                    "icons/chevron-right.svg"
                                })
                                .size(px(14.0))
                                .flex_shrink_0()
                                .text_color(theme::text_muted()),
                        ),
                )
                .children(expanded_body)
                .into_any_element(),
        )
    }

    /// Whether the open session's Agent offers a `goal` command.
    ///
    /// Only then can the phone hand the reader a way to set one: the control
    /// call the desktop makes is local-only, so an Agent that does not spell
    /// the command itself has no objective path from a phone at all.
    fn composer_has_goal_command(&self, cx: &gpui::App) -> bool {
        let _ = cx;
        self.composer_commands.iter().any(|command| {
            command
                .command_name
                .as_deref()
                .or(Some(command.label.as_str()))
                .is_some_and(|name| name.trim_start_matches('/').eq_ignore_ascii_case("goal"))
        })
    }

    /// Pauses, resumes, or clears the session's goal.
    ///
    /// The desktop does this through the local manager; a paired client goes
    /// through the same authority over the wire, which is what makes a goal
    /// controllable from the phone at all.
    fn control_session_goal(
        &mut self,
        action: vibex_core::GoalAction,
        objective: Option<String>,
        cx: &mut Context<Self>,
    ) {
        if self.operation_busy {
            return;
        }
        let Some(session_id) = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.selected_session_id.clone())
        else {
            return;
        };
        let Some(backend) = self.backend.clone().filter(|backend| {
            backend
                .capability_snapshot()
                .agent
                .supports(BackendOperation::AgentGoalControl)
        }) else {
            self.hint(
                Tone::Warning,
                locale::text(
                    "This desktop cannot control a goal",
                    "此桌面端不支持控制目标",
                    "此桌面版不支援控制目標",
                ),
            );
            cx.notify();
            return;
        };
        let expected_revision = self.current_goal().and_then(|active| active.goal.revision);
        let request = MutationRequest::new(vibex_core::AgentGoalControlRequest {
            session_id,
            action,
            objective,
            expected_revision,
            correlation_id: None,
        });
        self.operation_busy = true;
        let runner =
            gpui_tokio::Tokio::spawn(cx, async move { backend.control_goal(request).await });
        let task = cx.spawn(async move |entity: WeakEntity<Self>, cx| {
            let outcome = flatten_join(runner.await);
            let _ = entity.update(cx, |this, cx| {
                this.operation_busy = false;
                match outcome {
                    Ok(_) => {
                        // The control appends timeline items, so the window is
                        // re-read rather than patched.
                        this.reload_selected_session(cx);
                    }
                    Err(error) => this.fail(error),
                }
                cx.notify();
            });
        });
        self.tasks.push(task);
        cx.notify();
    }

    /// Prefills the composer with the Agent's own goal command.
    /// Whether the Agent's goal surface accepts a new objective at all.
    ///
    /// The vocabulary is the adapter's: one that spells the rewrite `set`,
    /// another that spells it `edit`, and one that offers neither.
    fn goal_objective_action(&self) -> Option<vibex_core::GoalAction> {
        let active = self.current_goal()?;
        if active.actions.contains(&vibex_core::GoalAction::Set) {
            Some(vibex_core::GoalAction::Set)
        } else if active.actions.contains(&vibex_core::GoalAction::Edit) {
            Some(vibex_core::GoalAction::Edit)
        } else {
            None
        }
    }

    /// Opens the objective editor, seeded with the goal on screen.
    ///
    /// The desktop edits the objective in its goal bar and issues a control;
    /// the phone used to prefill `/goal <objective>` into the composer and let
    /// the reader send it, which only worked on Agents that spell that command
    /// themselves. Where the goal surface takes a rewrite, this calls it; where
    /// it does not, the command is still the fallback.
    fn begin_composer_goal_edit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(active) = self.current_goal() else {
            return;
        };
        self.composer_goal_expanded = false;
        if self.goal_objective_action().is_none()
            || !self.backend.as_ref().is_some_and(|backend| {
                backend
                    .capability_snapshot()
                    .agent
                    .supports(BackendOperation::AgentGoalControl)
            })
        {
            let draft = format!("/goal {}", active.goal.objective);
            let selection_end = draft.len();
            self.composer_input.update(cx, |input, cx| {
                input.set_value(draft, window, cx);
                input.set_selected_range(0..selection_end, cx);
                input.focus(window, cx);
            });
            crate::platform::show_keyboard();
            cx.notify();
            return;
        }
        let objective = active.goal.objective.clone();
        let selection_end = objective.len();
        self.goal_objective_input.update(cx, |input, cx| {
            input.set_value(objective, window, cx);
            input.set_selected_range(0..selection_end, cx);
            input.focus(window, cx);
        });
        self.goal_objective_open = true;
        crate::platform::show_keyboard();
        cx.notify();
    }

    fn close_goal_objective(&mut self, cx: &mut Context<Self>) {
        if self.goal_objective_open {
            self.close_sheet(SheetKey::GoalObjective, cx);
        }
    }

    /// Sends the rewritten objective through the goal control.
    fn confirm_goal_objective(&mut self, cx: &mut Context<Self>) {
        let Some(action) = self.goal_objective_action() else {
            return;
        };
        let objective = self
            .goal_objective_input
            .read(cx)
            .value()
            .trim()
            .to_string();
        if objective.is_empty() {
            return;
        }
        self.goal_objective_open = false;
        self.control_session_goal(action, Some(objective), cx);
    }

