    /// The new-session page's choice list, along the bottom edge.
    ///
    /// It is a list rather than a cycle because the desktop picks from a list:
    /// a phone tapping through five projects to reach the last one is slower
    /// than reading five names, and there is no way to go back a step.
    /// Where the session will run.
    ///
    /// Two questions, one sheet: the project is the list on top and the
    /// workspaces under it are re-scoped by the choice above them, so the reader
    /// sees where they are about to start without opening a second sheet. The
    /// project row stays open on purpose — the answer below it is the point.
    fn render_new_session_picker_sheet(
        &self,
        presentation: SheetPresentation,
        body_scroll: ScrollHandle,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        match self.new_session_picker {
            Some(NewSessionPicker::Project) => {
                self.render_new_session_project_sheet(presentation, body_scroll, cx)
            }
            Some(NewSessionPicker::Location) => {
                self.render_new_session_location_sheet(presentation, body_scroll, cx)
            }
            Some(NewSessionPicker::BaseRef) => {
                self.render_new_session_base_ref_sheet(presentation, body_scroll, cx)
            }
            None => div().into_any_element(),
        }
    }

    /// The base branches a new worktree can be cut from.
    ///
    /// A list rather than a cycle: a repository has more branches than a chip
    /// can walk through, and the answer is a name the reader recognises rather
    /// than the next one in line.
    fn render_new_session_base_ref_sheet(
        &self,
        presentation: SheetPresentation,
        body_scroll: ScrollHandle,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let chosen = self.new_session_base_ref.clone();
        let rows = self
            .new_session_base_refs
            .iter()
            .map(|base_ref| {
                let selected = chosen.as_deref() == Some(base_ref.as_str());
                let value = base_ref.clone();
                let label = base_ref.clone();
                div()
                    .id(format!("new-session-base-ref:{base_ref}"))
                    .flex_shrink_0()
                    .min_h(px(theme::TOUCH_TARGET))
                    .px(px(theme::SPACING_LG))
                    .py(px(theme::SPACING_SM))
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_MD))
                    .cursor_pointer()
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .when(selected, |row| row.bg(theme::sidebar_selected_bg()))
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(move |this, _, _, cx| {
                            this.choose_new_session_base_ref(value.clone(), cx)
                        }),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_body())
                            .text_color(theme::text_primary())
                            .child(label),
                    )
                    .when(selected, |row| {
                        row.child(
                            svg()
                                .path("icons/check.svg")
                                .size(px(theme::ICON_SM))
                                .text_color(theme::accent_green()),
                        )
                    })
                    .into_any_element()
            })
            .collect::<Vec<_>>();

        let body = if !rows.is_empty() {
            div()
                .id("new-session-base-ref-rows")
                .flex_1()
                .min_h_0()
                .track_scroll(&body_scroll)
                .overflow_y_scroll()
                .restrict_scroll_to_axis()
                .flex()
                .flex_col()
                .pb(px(theme::SPACING_SM))
                .children(rows)
                .into_any_element()
        } else {
            div()
                .flex_1()
                .min_h_0()
                .px(px(theme::SPACING_LG))
                .py(px(theme::SPACING_MD))
                .child(
                    div()
                        .text_size(theme::font_caption())
                        .text_color(theme::text_muted())
                        .child(if self.new_session_base_refs_loading {
                            locale::text(
                                "Reading the branches…",
                                "正在读取分支…",
                                "正在讀取分支…",
                            )
                        } else {
                            locale::text(
                                "Git did not report any base branch for this workspace, so the worktree starts from the branch it is on.",
                                "Git 未报告该工作区的可选基线，Worktree 将从其当前分支创建。",
                                "Git 未回報此工作區的可選基線，Worktree 將從其目前分支建立。",
                            )
                        }),
                )
                .into_any_element()
        };

        let sheet = div()
            .min_h_0()
            .flex()
            .flex_col()
            .child(new_session_picker_header(
                locale::text("Base branch", "基线分支", "基線分支"),
                "new-session-base-ref-close",
                cx,
            ))
            .child(body);
        bottom_sheet_shell("mobile-new-session-base-ref", presentation)
            .on_dismiss(
                cx.listener(|this, _, _, cx| this.tap_sheet_scrim(SheetKey::NewSessionPicker, cx)),
            )
            .on_pan(cx.listener(|this, event, window, cx| {
                this.pull_sheet(SheetKey::NewSessionPicker, event, window, cx)
            }))
            .content(sheet)
            .into_any_element()
    }

    /// Performs what a pill's tap stands for.
    ///
    /// The page names the action and this resolves it, so the pill itself stays
    /// a piece of drawing and every surface it can open is still opened from the
    /// page that owns it.
    fn activate_composer_chip(
        &mut self,
        action: ComposerChipAction,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        match action {
            ComposerChipAction::NewSessionModel => {
                self.open_runtime_options(&noop_mouse_up(), window, cx)
            }
            ComposerChipAction::NewSessionProject => {
                self.open_new_session_picker(NewSessionPicker::Project, cx)
            }
            ComposerChipAction::NewSessionLocation => {
                self.open_new_session_picker(NewSessionPicker::Location, cx)
            }
            ComposerChipAction::SessionModel => {
                self.open_runtime_options(&noop_mouse_up(), window, cx)
            }
        }
    }

    /// The row that starts a session without a project.
    ///
    /// It is offered only where the authority can hand out the root: the phone
    /// cannot make a directory on the machine that runs the Agent, so the entry
    /// has to know whether that machine will make one.
    fn render_new_session_temporary_row(&self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let supported = self.supports_new_session_temporary_root();
        let selected = self.new_session_temporary;
        div()
            .id("new-session-temporary")
            .flex_shrink_0()
            .min_h(px(theme::TOUCH_TARGET))
            .px(px(theme::SPACING_LG))
            .py(px(theme::SPACING_SM))
            .flex()
            .items_center()
            .gap(px(theme::SPACING_MD))
            .when(selected, |row| row.bg(theme::sidebar_selected_bg()))
            .when(supported, |row| {
                row.cursor_pointer()
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(|this, _, _, cx| this.choose_new_session_temporary(cx)),
                    )
            })
            .when(!supported, |row| row.opacity(0.45))
            .child(
                svg()
                    .path("icons/box.svg")
                    .size(px(theme::ICON_SM))
                    .flex_shrink_0()
                    .text_color(if selected {
                        theme::primary()
                    } else {
                        theme::text_muted()
                    }),
            )
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .child(
                        div()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_body())
                            .text_color(theme::text_primary())
                            .child(locale::text(
                                "Temporary session",
                                "临时会话",
                                "臨時工作階段",
                            )),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_micro())
                            .text_color(theme::text_muted())
                            .child(if supported {
                                locale::text(
                                    "Starts in the desktop's own scratch directory",
                                    "在桌面端的临时目录中启动，不加入任何项目",
                                    "在桌面版的臨時目錄中啟動，不加入任何專案",
                                )
                            } else {
                                locale::text(
                                    "This runtime cannot start a session without a project",
                                    "该运行时不支持无项目的临时会话",
                                    "此執行環境不支援無專案的臨時工作階段",
                                )
                            }),
                    ),
            )
            .when(selected, |row| {
                row.child(
                    svg()
                        .path("icons/check.svg")
                        .size(px(theme::ICON_SM))
                        .text_color(theme::accent_green()),
                )
            })
            .into_any_element()
    }

    /// The project a new session belongs to, or none at all.
    ///
    /// One question, one list: the project decides the checkout the session is
    /// worked in, and a reader who wants to work somewhere else answers the
    /// chip beside this one instead of picking a worktree out of the folder
    /// tree.
    fn render_new_session_project_sheet(
        &self,
        presentation: SheetPresentation,
        body_scroll: ScrollHandle,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let project_id = self.new_session_project_id.clone();
        let rows = self
            .sidebar_projects()
            .into_iter()
            .map(|project| {
                let selected = !self.new_session_temporary
                    && project_id.as_deref() == Some(project.id.as_str());
                let workspaces = self
                    .workspace_summaries
                    .iter()
                    .filter(|summary| summary.project.id.as_str() == project.id)
                    .count();
                let subtitle = match workspaces {
                    0 => locale::text("No workspace yet", "暂无工作区", "尚無工作區").to_string(),
                    1 => locale::text("1 workspace", "1 个工作区", "1 個工作區").to_string(),
                    count => format!(
                        "{count} {}",
                        locale::text("workspaces", "个工作区", "個工作區")
                    ),
                };
                let id = project.id.clone();
                new_session_picker_row(
                    format!("new-session-project:{}", project.id),
                    "icons/folder.svg",
                    project.label,
                    subtitle,
                    selected,
                    true,
                )
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, _, _, cx| {
                        this.choose_new_session_project(id.clone(), cx)
                    }),
                )
                .into_any_element()
            })
            .collect::<Vec<_>>();

        let sheet = div()
            .min_h_0()
            .flex()
            .flex_col()
            .child(new_session_picker_header(
                locale::text("Project", "项目", "專案"),
                "new-session-project-close",
                cx,
            ))
            .child(
                div()
                    .id("new-session-project-rows")
                    .flex_1()
                    .min_h_0()
                    .track_scroll(&body_scroll)
                    .overflow_y_scroll()
                    .restrict_scroll_to_axis()
                    .flex()
                    .flex_col()
                    .pb(px(theme::SPACING_SM))
                    .children(rows)
                    // The answer for a session that belongs to no checkout yet.
                    // It sits under the list because it is the alternative to
                    // every row in it, not one more project.
                    .child(runtime_section_heading(locale::text(
                        "Without a project",
                        "不使用项目",
                        "不使用專案",
                    )))
                    .child(self.render_new_session_temporary_row(cx)),
            );
        bottom_sheet_shell("mobile-new-session-picker", presentation)
            .on_dismiss(
                cx.listener(|this, _, _, cx| this.tap_sheet_scrim(SheetKey::NewSessionPicker, cx)),
            )
            .on_pan(cx.listener(|this, event, window, cx| {
                this.pull_sheet(SheetKey::NewSessionPicker, event, window, cx)
            }))
            .content(sheet)
            .into_any_element()
    }

    /// Where the session runs: the project's own checkout, or a worktree cut
    /// for it before the session starts.
    ///
    /// The two answers are the lead of the drawer, and the worktree's own
    /// fields follow the answer that needs them — the name it is created under,
    /// the path it lands on, and the branch it is cut from. They are the same
    /// shape the desktop asks for in its own location menu.
    fn render_new_session_location_sheet(
        &self,
        presentation: SheetPresentation,
        body_scroll: ScrollHandle,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let mode = self.normalize_new_session_workspace_mode(self.new_session_workspace_mode);
        let worktree_supported = self.supports_new_session_worktree();
        let workspace_display = self
            .new_session_workspace_id
            .as_deref()
            .and_then(|id| {
                self.workspaces
                    .iter()
                    .find(|workspace| workspace.id.as_str() == id)
            })
            .map(|workspace| {
                let title = self
                    .sidebar_view
                    .worktree_titles
                    .get(workspace.id.as_str())
                    .cloned()
                    .unwrap_or_else(|| workspace_label(&workspace.root_path).to_string());
                let branch = self
                    .workspace_summaries
                    .iter()
                    .find(|summary| summary.workspace.id.as_str() == workspace.id.as_str())
                    .and_then(|summary| summary.git_branch.clone())
                    .filter(|branch| !branch.trim().is_empty());
                match branch {
                    Some(branch) => format!("{title} · {branch}"),
                    None => title,
                }
            })
            .unwrap_or_else(|| {
                locale::text("Choose a project first", "请先选择项目", "請先選擇專案").to_string()
            });
        let worktree_subtitle = if worktree_supported {
            locale::text(
                "Create a worktree for this session",
                "为此会话新建 Worktree",
                "為此工作階段新建 Worktree",
            )
            .to_string()
        } else {
            locale::text(
                "This runtime cannot create a worktree",
                "该运行时不支持创建 Worktree",
                "此執行環境不支援建立 Worktree",
            )
            .to_string()
        };

        let local_row = new_session_picker_row(
            "new-session-location:local",
            "icons/folder-open.svg",
            locale::text("Local", "本地", "本機"),
            workspace_display,
            mode == WorkspaceMode::CurrentCheckout,
            true,
        )
        .on_mouse_up(
            MouseButton::Left,
            cx.listener(|this, _, window, cx| this.choose_new_session_local(window, cx)),
        );
        let worktree_row = new_session_picker_row(
            "new-session-location:worktree",
            "icons/git-branch.svg",
            locale::text("New worktree", "新建 Worktree", "新建 Worktree"),
            worktree_subtitle,
            mode == WorkspaceMode::VibexWorktree,
            worktree_supported,
        )
        .on_mouse_up(
            MouseButton::Left,
            cx.listener(|this, _, window, cx| this.choose_new_session_worktree(window, cx)),
        );

        let busy = self.new_session_busy;
        let sheet = div()
            .min_h_0()
            .flex()
            .flex_col()
            .child(new_session_picker_header(
                locale::text("Where to run", "运行位置", "執行位置"),
                "new-session-location-close",
                cx,
            ))
            .child(
                div()
                    .id("new-session-location-rows")
                    .flex_1()
                    .min_h_0()
                    .track_scroll(&body_scroll)
                    .overflow_y_scroll()
                    .restrict_scroll_to_axis()
                    .flex()
                    .flex_col()
                    .pb(px(theme::SPACING_SM))
                    .child(local_row)
                    .child(worktree_row)
                    // The worktree's own fields, in place, and only while a new
                    // worktree is the answer.
                    .when(mode == WorkspaceMode::VibexWorktree, |body| {
                        body.child(self.render_new_session_worktree_fields(busy, cx))
                    }),
            );
        bottom_sheet_shell("mobile-new-session-picker", presentation)
            .on_dismiss(
                cx.listener(|this, _, _, cx| this.tap_sheet_scrim(SheetKey::NewSessionPicker, cx)),
            )
            .on_pan(cx.listener(|this, event, window, cx| {
                this.pull_sheet(SheetKey::NewSessionPicker, event, window, cx)
            }))
            .content(sheet)
            .into_any_element()
    }

    /// The new-session page.
    ///
    /// The prompt card is the page: an introduction above it for orientation,
    /// the message inside it, and the row under it naming where that message
    /// will run. The card's control row carries the runtime the same way the
    /// session composer's does — the model as the one value worth reading, the
    /// Agent's own options as the glyphs that open them — and the two chips
    /// under the card answer which project the session belongs to and where
    /// that project is worked. The desktop's creation panel draws the same
    /// split, which is the point: the phone used to open on a stack of cards and
    /// a button at the far end of the screen.
    fn render_new_session(&self, _window: &Window, cx: &mut Context<Self>) -> gpui::AnyElement {
        // The chip names the answer rather than the question: a temporary
        // session has no project, and saying so is more use than leaving the
        // chip on "Choose project" while the session is ready to start.
        let project_label = if self.new_session_temporary {
            locale::text("Temporary session", "临时会话", "臨時工作階段").to_string()
        } else {
            self.new_session_project_id
                .as_deref()
                .and_then(|id| {
                    self.sidebar_projects()
                        .into_iter()
                        .find(|project| project.id == id)
                })
                .map(|project| project.label)
                .unwrap_or_else(|| {
                    locale::text("Choose project", "选择项目", "選擇專案").to_string()
                })
        };
        let runtime_catalog = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.runtime_options.value.as_ref());
        let runtime_selection = self.new_session_runtime.as_ref().or_else(|| {
            self.controller
                .as_ref()
                .and_then(|controller| controller.state.runtime_selection.value.as_ref())
                .map(|state| &state.desired)
        });
        let runtime_summary = runtime_selection_summary(runtime_catalog, runtime_selection);
        let prompt = self.new_session_prompt_input.read(cx).value();
        let new_session_suggestions = self.new_session_suggestions(cx);
        // A first message may be a file on its own, the same way a prompt in
        // the composer may be: the field being empty is not the same as there
        // being nothing to send.
        let can_submit = (!prompt.trim().is_empty() || !self.new_session_attachments.is_empty())
            && !self.new_session_busy;
        let mode = self.normalize_new_session_workspace_mode(self.new_session_workspace_mode);
        let can_create_session = self.backend.as_ref().is_some_and(|backend| {
            backend
                .capability_snapshot()
                .agent
                .supports(BackendOperation::AgentCreateSession)
        });
        let runtime_ready = runtime_summary.available && can_create_session;
        // The page is the card. Everything above it is orientation, the card is
        // the message, and the chips under it are where that message will run.
        // Every runtime choice lives on the card's control row — the model as
        // the chip it is worth reading, the Agent's own options as the glyphs
        // that open them — so the first thing the page shows is the field it is
        // asking the reader to write in.
        //
        // The introduction stays while the reader writes: the keyboard already
        // takes the room it needs, and a page that rearranges itself on the
        // first keystroke is a page that jumps under the reader's thumb.
        let busy = self.new_session_busy;
        let location_label = if mode == WorkspaceMode::VibexWorktree {
            locale::text("New worktree", "新建 Worktree", "新建 Worktree").to_string()
        } else {
            // The desktop's own word for the project's checkout, so a reader
            // moving between the two clients reads the same answer.
            locale::text("Local", "本地", "本機").to_string()
        };
        // The two decisions the card reports rather than hides: which model will
        // answer, and what the session is allowed to do. Both are read off the
        // same projection the sheets write to, so a choice made in a sheet shows
        // up here on the next frame.
        let runtime_option = runtime_catalog
            .zip(runtime_selection)
            .and_then(|(catalog, selection)| matching_runtime_option(&catalog.options, selection));
        // The Agent this page would hand the work to, named the way the
        // sidebar rows and the runtime sheets name one: the catalogue's own
        // label when it has one, the id when it does not.
        let new_session_agent = runtime_selection.map(|selection| {
            let label = runtime_option
                .map(|option| option.agent_label.as_str())
                .unwrap_or_else(|| selection.agent_id.as_str());
            (&selection.agent_id, label)
        });
        let model_id = match runtime_selection.map(|selection| &selection.model) {
            Some(vibex_core::RuntimeModelSelection::Explicit { model_id }) => {
                Some(model_id.clone())
            }
            _ => None,
        };
        let model_label = runtime_option
            .map(|option| option.model_label.clone())
            .unwrap_or_else(|| {
                model_id
                    .clone()
                    .unwrap_or_else(|| locale::common("Default").to_string())
            });
        // The Agent's own options, read the way the control row's glyphs show
        // them: the projection says which groups this Agent offers at all, and
        // the selection says which of them the reader has already changed from
        // the Agent's own default.
        let projection = runtime_catalog
            .zip(runtime_selection)
            .map(|(catalog, selection)| RuntimeCascadeProjection::from_catalog(catalog, selection))
            .unwrap_or_default();
        let reasoning_offered = !projection.reasoning_efforts.is_empty();
        let modes_offered = !projection.modes.is_empty();
        let reasoning_set =
            runtime_selection.is_some_and(|selection| selection.reasoning_effort.is_some());
        let mode_set = runtime_selection.is_some_and(|selection| selection.mode_id.is_some());
        let options_set =
            runtime_selection.is_some_and(|selection| !selection.config_values.is_empty());

        div()
            .absolute()
            .inset_0()
            .bg(theme::bg_primary())
            .block_mouse_except_scroll()
            .flex()
            .flex_col()
            .child(self.render_overlay_header(
                "mobile-new-session",
                "New session",
                theme::font_heading(),
                None,
                true,
                OverlayHeaderRule::Open,
                cx,
            ))
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .flex()
                    .flex_col()
                    // ── where the page introduces itself ─────────────────────
                    .child(
                        div()
                            .flex_1()
                            .min_h_0()
                            .overflow_hidden()
                            .px(px(theme::SPACING_XL))
                            .flex()
                            .flex_col()
                            .items_center()
                            .justify_center()
                            .when(!busy, |hero| {
                                // The introduction fades in rather than
                                // appearing whole: the page opens over the list
                                // behind it, and the fade is what makes that
                                // read as a page arriving.
                                hero.child(
                                    div()
                                        .flex()
                                        .flex_col()
                                        .items_center()
                                        .with_animation(
                                            "mobile-new-session-intro",
                                            Animation::new(Duration::from_millis(PAGE_ENTRANCE_MS)),
                                            |intro, delta| intro.opacity(delta),
                                        )
                                        .child(self.render_pairing_brand())
                                        .child(new_session_slogan_line(new_session_agent, cx))
                                        .child(
                                            div()
                                                .mt(px(theme::SPACING_SM))
                                                .text_size(theme::font_caption())
                                                .text_color(theme::text_muted())
                                                .child(if self.new_session_temporary {
                                                    project_label.clone()
                                                } else {
                                                    format!("{project_label} · {location_label}")
                                                }),
                                        ),
                                )
                            }),
                    )
                    // ── the message, and what it will run on ────────────────
                    .child(
                        div()
                            .flex_shrink_0()
                            .px(px(theme::SPACING_LG))
                            .pb(px(theme::SPACING_MD))
                            .flex()
                            .flex_col()
                            .gap(px(theme::SPACING_SM))
                            .child(
                                div()
                                    .w_full()
                                    // The first message's field is the same
                                    // card as the session composer's: the same
                                    // radius on all four corners, and a fill a
                                    // step above the page.
                                    .rounded(px(theme::RADIUS_COMPOSER))
                                    .border_1()
                                    .border_color(theme::border_default())
                                    .bg(theme::composer_surface())
                                    .p(px(theme::SPACING_MD))
                                    .flex()
                                    .flex_col()
                                    .gap(px(theme::SPACING_SM))
                                    .child(
                                        div()
                                            .w_full()
                                            .min_h(px(theme::TOUCH_TARGET))
                                            .on_mouse_down(
                                                MouseButton::Left,
                                                resume_keyboard_on_tap,
                                            )
                                            .child(
                                                Textarea::new(&self.new_session_prompt_input)
                                                    .appearance(false)
                                                    .text_size(theme::font_composer())
                                                    .text_color(theme::text_primary()),
                                            ),
                                    )
                                    // The first message opens the same trigger
                                    // panels the session composer does — `/`
                                    // commands and quick phrases, `@` files and
                                    // collaborators, `$` skills — so a trigger
                                    // typed before the session exists behaves
                                    // the way it will once it does.
                                    .when_some(new_session_suggestions, |card, suggestions| {
                                        card.child(self.render_composer_suggestion_panel(
                                            &suggestions,
                                            ComposerSuggestionTarget::NewSession,
                                            cx,
                                        ))
                                    })
                                    // The first message carries what a prompt carries:
                                    // a picture the Agent should look at, or a file it
                                    // should read, before the session has even started.
                                    .when(!self.new_session_attachments.is_empty(), |card| {
                                        card.child(self.render_new_session_attachments(cx))
                                    })
                                    // The control row is the composer's own: the
                                    // plus against the card's leading edge, the
                                    // model chip beside it, then the Agent's own
                                    // options as glyphs, and the single commitment
                                    // on the right.
                                    .child(
                                        div()
                                            .w_full()
                                            .h(px(theme::TOUCH_TARGET))
                                            .flex()
                                            .items_center()
                                            .child(
                                                composer_icon_button(
                                                    "mobile-new-session-attach",
                                                    "icons/plus.svg",
                                                    locale::text(
                                                        "Attach a file",
                                                        "添加附件",
                                                        "新增附件",
                                                    )
                                                    .to_string(),
                                                    !busy,
                                                    cx.listener(Self::open_new_session_attach_menu),
                                                )
                                                .ml(px(-theme::SPACING_MD)),
                                            )
                                            .child(
                                                composer_chip(
                                                    "mobile-new-session-model",
                                                    runtime_model_icon(
                                                        model_id.as_deref(),
                                                        px(theme::ICON_MD),
                                                        theme::text_secondary(),
                                                    ),
                                                    model_label,
                                                    !runtime_ready,
                                                    false,
                                                    true,
                                                    ComposerChipAction::NewSessionModel,
                                                    cx,
                                                )
                                                .flex_1()
                                                .min_w_0(),
                                            )
                                            .when(reasoning_offered, |row| {
                                                row.child(composer_option_button(
                                                    "mobile-new-session-reasoning",
                                                    "icons/brain.svg",
                                                    locale::common("Reasoning").to_string(),
                                                    reasoning_set,
                                                    !busy,
                                                    cx.listener(
                                                        Self::open_runtime_reasoning_drawer,
                                                    ),
                                                ))
                                            })
                                            .when(modes_offered, |row| {
                                                row.child(composer_option_button(
                                                    "mobile-new-session-mode",
                                                    "icons/shield-alert.svg",
                                                    locale::common("Mode").to_string(),
                                                    mode_set,
                                                    !busy,
                                                    cx.listener(Self::open_runtime_mode_drawer),
                                                ))
                                            })
                                            // The title and the model's own options
                                            // share the last glyph: both are
                                            // settings for the session being made.
                                            .child(composer_option_button(
                                                "mobile-new-session-options",
                                                "icons/sliders-horizontal.svg",
                                                locale::text(
                                                    "Session options",
                                                    "会话选项",
                                                    "工作階段選項",
                                                )
                                                .to_string(),
                                                options_set,
                                                !busy,
                                                cx.listener(Self::open_session_options_drawer),
                                            ))
                                            .child(composer_primary_button(
                                                "mobile-new-session-submit",
                                                locale::common("Start session").to_string(),
                                                ComposerPrimaryAction::Send,
                                                can_submit && runtime_ready,
                                                busy,
                                                cx.listener(Self::submit_new_session),
                                            )),
                                    ),
                            )
                            // ── the two answers under the card ──────────────
                            // Which project it belongs to, and where that project
                            // is worked: the project's own checkout, or a worktree
                            // cut for the session. Each chip names its answer and
                            // folds down into the list that changes it.
                            .child(
                                div()
                                    .w_full()
                                    .flex()
                                    .items_center()
                                    .child(
                                        composer_chip(
                                            "mobile-new-session-project",
                                            svg()
                                                .path("icons/layers.svg")
                                                .size(px(theme::ICON_SM))
                                                .text_color(theme::text_muted())
                                                .into_any_element(),
                                            project_label.clone(),
                                            !self.new_session_temporary
                                                && self.new_session_project_id.is_none(),
                                            true,
                                            true,
                                            ComposerChipAction::NewSessionProject,
                                            cx,
                                        )
                                        .flex_1()
                                        .min_w_0(),
                                    )
                                    // A temporary session has no checkout, so
                                    // there is no second answer to offer: the
                                    // only place it can run is the authority's
                                    // own scratch directory.
                                    .when(!self.new_session_temporary, |row| {
                                        row.child(
                                            composer_chip(
                                                "mobile-new-session-location",
                                                svg()
                                                    .path(if mode == WorkspaceMode::VibexWorktree {
                                                        "icons/git-branch.svg"
                                                    } else {
                                                        "icons/folder-open.svg"
                                                    })
                                                    .size(px(theme::ICON_SM))
                                                    .text_color(theme::text_muted())
                                                    .into_any_element(),
                                                location_label.clone(),
                                                false,
                                                true,
                                                true,
                                                ComposerChipAction::NewSessionLocation,
                                                cx,
                                            )
                                            .flex_shrink_0(),
                                        )
                                    }),
                            )
                            // A page that cannot start says so next to the control
                            // that is holding it up, rather than in a sentence the
                            // reader has to connect to a row further up.
                            .when(!runtime_ready, |page| {
                                page.child(
                                    div()
                                        .px(px(theme::SPACING_XS))
                                        .text_size(theme::font_micro())
                                        .text_color(theme::accent_yellow())
                                        .child(locale::text(
                                            "Select an Agent runtime before starting.",
                                            "开始前请先选择 Agent 运行时。",
                                            "開始前請先選擇 Agent 執行環境。",
                                        )),
                                )
                            })
                            .when(busy, |page| {
                                page.child(
                                    div()
                                        .px(px(theme::SPACING_XS))
                                        .text_size(theme::font_micro())
                                        .text_color(theme::text_muted())
                                        .child(locale::text(
                                            "Creating the session…",
                                            "正在创建会话…",
                                            "正在建立工作階段…",
                                        )),
                                )
                            }),
                    ),
            )
            .into_any_element()
    }

    /// The worktree's own fields, under the answer that needs them.
    ///
    /// They used to be a card on every visit to the page with a sentence
    /// explaining worktrees under it; a reader starting in the current checkout
    /// needs neither, and even the reader who wants a worktree answers the
    /// question above these fields first.
    fn render_new_session_worktree_fields(
        &self,
        busy: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        div()
            .w_full()
            .px(px(theme::SPACING_LG))
            .pt(px(theme::SPACING_SM))
            .flex()
            .flex_col()
            .gap(px(theme::SPACING_SM))
            .child(
                div()
                    .text_size(theme::font_micro())
                    .text_color(theme::text_muted())
                    .child(locale::text("NEW WORKTREE", "新建 WORKTREE", "新建 WORKTREE")),
            )
            .child(
                div()
                    .h(px(theme::TOUCH_TARGET))
                    .rounded(px(theme::RADIUS_CONTROL))
                    .bg(theme::bg_card_dim())
                    .px_2()
                    .flex()
                    .items_center()
                    .when(!busy, |field| {
                        field.on_mouse_down(MouseButton::Left, resume_keyboard_on_tap)
                    })
                    .child(
                        Input::new(&self.new_session_worktree_name_input).appearance(false),
                    ),
            )
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_XS))
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .h(px(theme::TOUCH_TARGET))
                            .rounded(px(theme::RADIUS_CONTROL))
                            .bg(theme::bg_card_dim())
                            .px_2()
                            .flex()
                            .items_center()
                            .when(!busy, |field| {
                                field.on_mouse_down(MouseButton::Left, resume_keyboard_on_tap)
                            })
                            .child(
                                Input::new(&self.new_session_worktree_path_input).appearance(false),
                            ),
                    )
                    .child(
                        div()
                            .id("browse-worktree-path")
                            .size(px(theme::TOUCH_TARGET))
                            .flex_shrink_0()
                            .flex()
                            .items_center()
                            .justify_center()
                            .rounded(px(theme::RADIUS_CONTROL))
                            .aria_label(
                                locale::text(
                                    "Browse the desktop's folders",
                                    "浏览桌面端文件夹",
                                    "瀏覽桌面版資料夾",
                                )
                                .to_string(),
                            )
                            .when(!busy, |button| {
                                button
                                    .cursor_pointer()
                                    .active(|style| style.bg(theme::row_pressed_bg()))
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(Self::open_worktree_path_browser),
                                    )
                            })
                            .child(
                                svg()
                                    .path("icons/folder-open.svg")
                                    .size(px(theme::ICON_SM))
                                    .text_color(theme::text_secondary()),
                            ),
                    ),
            )
            // The line the worktree is cut from. It is a choice rather than a
            // fact about the origin, so it reads as one: the row names the
            // branch and opens the list Git reported for this workspace.
            .child(
                div()
                    .id("new-session-base-ref")
                    .h(px(theme::TOUCH_TARGET))
                    .rounded(px(theme::RADIUS_CONTROL))
                    .bg(theme::bg_card_dim())
                    .px_2()
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_SM))
                    .when(!busy, |row| {
                        row.cursor_pointer()
                            .active(|style| style.bg(theme::row_pressed_bg()))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| {
                                    this.open_new_session_picker(NewSessionPicker::BaseRef, cx)
                                }),
                            )
                    })
                    .child(
                        div()
                            .flex_shrink_0()
                            .text_size(theme::font_micro())
                            .text_color(theme::text_muted())
                            .child(locale::text("Base", "基线", "基線")),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_caption())
                            .text_color(theme::text_primary())
                            .child(match self.new_session_base_ref.as_deref() {
                                Some(base_ref) => base_ref.to_string(),
                                None if self.new_session_base_refs_loading => {
                                    locale::text("Reading…", "读取中…", "讀取中…").to_string()
                                }
                                None => locale::text(
                                    "The branch this workspace is on",
                                    "使用当前分支",
                                    "使用目前分支",
                                )
                                .to_string(),
                            }),
                    )
                    .child(
                        svg()
                            .path("icons/chevron-down.svg")
                            .size(px(theme::ICON_SM))
                            .text_color(theme::text_muted()),
                    ),
            )
            .child(
                div()
                    .text_size(theme::font_micro())
                    .text_color(theme::text_muted())
                    .child(locale::text(
                        "The worktree is created from the selected workspace's branch before the session starts.",
                        "会话启动前，会基于所选工作区的分支创建 Worktree。",
                        "工作階段啟動前，會基於所選工作區的分支建立 Worktree。",
                    )),
            )
            .into_any_element()
    }

    fn render_new_project(&self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let can_open_project = self.backend.as_ref().is_some_and(|backend| {
            backend
                .capability_snapshot()
                .workspace
                .supports(BackendOperation::WorkspaceOpen)
        });
        div()
            .absolute()
            .inset_0()
            .bg(theme::bg_primary())
            .block_mouse_except_scroll()
            .flex()
            .flex_col()
            .child(self.render_overlay_header(
                "mobile-new-project",
                "New project",
                theme::font_heading(),
                None,
                true,
                OverlayHeaderRule::Ruled,
                cx,
            ))
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .px(px(theme::SPACING_LG))
                    .py(px(theme::SPACING_MD))
                    .child(
                        div()
                            .mb(px(theme::SPACING_SM))
                            .text_size(theme::font_caption())
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(theme::text_muted())
                            .child(locale::common("Project path")),
                    )
                    .child(
                        div()
                            .h(px(theme::TOUCH_TARGET))
                            .w_full()
                            .rounded(px(theme::RADIUS_CONTROL))
                            .border_1()
                            .border_color(theme::border_default())
                            .bg(theme::bg_card())
                            .on_mouse_down(MouseButton::Left, resume_keyboard_on_tap)
                            .child(Input::new(&self.new_project_input).appearance(false)),
                    )
                    .when_some(self.new_project_error.as_ref(), |body, error| {
                        body.child(
                            div()
                                .mt(px(theme::SPACING_SM))
                                .text_size(theme::font_caption())
                                .text_color(theme::accent_red())
                                .child(error.clone()),
                        )
                    })
                    .child(
                        div()
                            .id("mobile-new-project-submit")
                            .h(px(theme::TOUCH_TARGET))
                            .w_full()
                            .mt(px(theme::SPACING_LG))
                            .rounded(px(theme::RADIUS_CONTROL))
                            .border_1()
                            .border_color(theme::border_default())
                            .bg(theme::bg_card())
                            .flex()
                            .items_center()
                            .justify_center()
                            .text_size(theme::font_body())
                            .text_color(theme::text_primary())
                            .when(can_open_project && !self.new_project_busy, |button| {
                                button
                                    .cursor_pointer()
                                    .active(|style| style.bg(theme::row_pressed_bg()))
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(Self::submit_new_project),
                                    )
                            })
                            .when(!can_open_project || self.new_project_busy, |button| {
                                button.opacity(0.45)
                            })
                            .child(if self.new_project_busy {
                                locale::common("Opening...")
                            } else {
                                locale::common("Open project")
                            }),
                    ),
            )
            .into_any_element()
    }

