    /// The About section's version row and the update surface under it.
    ///
    /// Without an updater — a build that carries no release verification key,
    /// or a platform whose store owns replacement — this is exactly the version
    /// row the app has always shown. With one, the row is followed by either
    /// the quiet state of the last check or the card for the release waiting to
    /// be installed.
    fn render_update_section(&self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let version_row = || {
            settings_info_row_base(
                "mobile-settings-version",
                locale::common("Version").to_string(),
                String::new(),
                update::installed_version(),
            )
            .debug_selector(|| "mobile-settings-version".to_string())
            .into_any_element()
        };
        // Only Android updates itself; the version row is the whole section
        // everywhere else.
        if !self.update_supported {
            return version_row();
        }
        let Some(snapshot) = self.update_snapshot.as_ref() else {
            // A build without the release verification key cannot check, but the
            // section still says so: an empty About is indistinguishable from a
            // missing feature.
            return settings_group(
                "",
                vec![version_row(), self.render_update_status_row(None, cx)],
            );
        };
        let Some(card) = update_card_model(&snapshot.state) else {
            return settings_group(
                "",
                vec![
                    version_row(),
                    self.render_update_status_row(Some(&snapshot.state), cx),
                ],
            );
        };
        div()
            .flex()
            .flex_col()
            .child(version_row())
            .child(self.render_update_card(&card, cx))
            .into_any_element()
    }

    /// The manual check, with the state of the last one beside it.
    ///
    /// Automatic checks already run at startup, on resume, and every six hours;
    /// this row exists so a user who wants to know now does not have to wait
    /// for the next one. Without an updater the row is information only, so it
    /// carries no tap target that would do nothing.
    fn render_update_status_row(
        &self,
        state: Option<&UpdateState>,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let row = settings_info_row_base(
            "mobile-settings-update-check",
            locale::text("Check for updates", "检查更新", "檢查更新").to_string(),
            update_status_detail(state),
            String::new(),
        )
        .debug_selector(|| "mobile-settings-update-check".to_string());
        if !self.update_available {
            return row.into_any_element();
        }
        row.aria_label(locale::text("Check for updates", "检查更新", "檢查更新"))
            .cursor_pointer()
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|_, _, _, cx| {
                    update::check_now();
                    cx.notify();
                }),
            )
            .into_any_element()
    }

    /// The release waiting to be installed, with both ways to install it.
    fn render_update_card(
        &self,
        card: &UpdateCardModel,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let title = format!(
            "{} {}",
            locale::text("Update available", "有新版本可用", "有新版本可用"),
            card.version
        );
        let mut actions = div().flex().gap(px(theme::SPACING_SM));
        if let Some(action) = card.primary.clone() {
            let label = match action {
                UpdateCardAction::Download => {
                    locale::text("Download & install", "下载并安装", "下載並安裝")
                }
                UpdateCardAction::Install(_) => locale::text("Install", "安装", "安裝"),
                UpdateCardAction::Retry => locale::common("Retry"),
            };
            actions = actions.child(
                update_card_button("mobile-settings-update-install", label.to_string(), true)
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(move |_, _, _, cx| {
                            match &action {
                                UpdateCardAction::Download => update::download_and_install(),
                                UpdateCardAction::Install(path) => update::install_staged(path),
                                UpdateCardAction::Retry => update::check_now(),
                            }
                            cx.notify();
                        }),
                    ),
            );
        }
        actions = actions.child(
            update_card_button(
                "mobile-settings-update-page",
                locale::text("Open download page", "打开下载页", "開啟下載頁").to_string(),
                false,
            )
            .on_mouse_up(
                MouseButton::Left,
                cx.listener({
                    let url = card.download_url.clone();
                    move |_, _, _, cx| {
                        update::open_download_page(&url);
                        cx.notify();
                    }
                }),
            ),
        );
        div()
            .id("mobile-settings-update-card")
            .debug_selector(|| "mobile-settings-update-card".to_string())
            .w_full()
            .mt(px(theme::SPACING_SM))
            .mb(px(theme::SPACING_MD))
            .rounded(px(theme::RADIUS_CARD))
            .bg(theme::bg_card_dim())
            .px(px(theme::SPACING_MD))
            .py(px(theme::SPACING_MD))
            .flex()
            .flex_col()
            .gap(px(theme::SPACING_MD))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_SM))
                    .child(
                        svg()
                            .path("icons/download.svg")
                            .size(px(theme::ICON_SM))
                            .text_color(card.accent),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .flex()
                            .flex_col()
                            .gap(px(1.0))
                            .child(
                                div()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .whitespace_nowrap()
                                    .text_size(theme::font_body())
                                    .text_color(theme::text_primary())
                                    .child(title),
                            )
                            .child(
                                div()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .whitespace_nowrap()
                                    .text_size(theme::font_micro())
                                    .text_color(theme::text_muted())
                                    .child(card.detail.clone()),
                            ),
                    ),
            )
            .when_some(card.progress, |body, fraction| {
                body.child(update_progress_bar(
                    "mobile-settings-update-progress",
                    fraction,
                ))
            })
            .child(actions)
            .into_any_element()
    }

    fn render_settings(
        &self,
        palette_sheet: Option<SheetPresentation>,
        palette_scroll: ScrollHandle,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let page = self.settings_page;
        div()
            .absolute()
            .inset_0()
            .bg(theme::bg_primary())
            .block_mouse_except_scroll()
            .flex()
            .flex_col()
            .child(if page == SettingsPage::Root {
                self.render_overlay_header(
                    "mobile-settings",
                    page.title(),
                    theme::font_title(),
                    None,
                    false,
                    OverlayHeaderRule::Ruled,
                    cx,
                )
            } else {
                self.render_settings_page_header(page, cx)
            })
            .child(
                div()
                    .id("mobile-settings-scroll")
                    .flex_1()
                    .min_h_0()
                    .track_scroll(&self.settings_scroll)
                    .overflow_y_scroll()
                    .restrict_scroll_to_axis()
                    .on_scroll_wheel(cx.listener(Self::consume_drawer_scroll))
                    .px(px(theme::SPACING_LG))
                    .pt(px(theme::SPACING_XL))
                    .pb(px(theme::SPACING_LG))
                    .children(match page {
                        SettingsPage::Root => self.render_settings_root(cx),
                        SettingsPage::Connection => self.render_settings_connection(cx),
                        SettingsPage::Appearance => self.render_settings_appearance(cx),
                        SettingsPage::Conversation => self.render_settings_conversation(cx),
                        SettingsPage::Notifications => self.render_settings_notifications(cx),
                        SettingsPage::About => self.render_settings_about(cx),
                    }),
            )
            .when_some(palette_sheet, |settings, presentation| {
                settings.child(self.render_settings_palette_sheet(presentation, palette_scroll, cx))
            })
            .into_any_element()
    }

    /// A sub-page's header: the same back chevron the rest of the app uses,
    /// then the topic's own name.
    ///
    /// It is the root's header with the back chevron retargeted one level in —
    /// same height, same glyph size, same page-name type — so stepping into a
    /// topic moves the page under the header rather than rebuilding the header
    /// around it.
    fn render_settings_page_header(
        &self,
        page: SettingsPage,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        div()
            .h(px(theme::DRAWER_HEADER_HEIGHT))
            .flex_shrink_0()
            .border_b_1()
            .border_color(theme::border_subtle())
            .px(px(theme::SPACING_LG))
            .flex()
            .items_center()
            .gap(px(theme::SPACING_SM))
            .child(
                div()
                    .id("mobile-settings-back")
                    .debug_selector(|| "mobile-settings-back".to_string())
                    .size(px(theme::HEADER_BUTTON_SIZE))
                    .ml(px(-theme::SPACING_SM))
                    .flex_shrink_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .cursor_pointer()
                    .aria_label(locale::common("Back"))
                    .active(|style| style.opacity(0.65))
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(|this, _, _, cx| {
                            this.open_settings_page(SettingsPage::Root, cx)
                        }),
                    )
                    .child(
                        svg()
                            .path("icons/chevron-left.svg")
                            .size(px(theme::ICON_SM))
                            .text_color(theme::text_secondary()),
                    ),
            )
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .overflow_hidden()
                    .text_ellipsis()
                    .whitespace_nowrap()
                    .text_size(theme::font_title())
                    .font_weight(FontWeight::SEMIBOLD)
                    .text_color(theme::text_primary())
                    .child(locale::common(page.title())),
            )
            .into_any_element()
    }

    fn open_settings_page(&mut self, page: SettingsPage, cx: &mut Context<Self>) {
        self.settings_page = page;
        self.settings_palette_open = false;
        self.settings_scroll.set_offset(gpui::Point::default());
        cx.notify();
    }

    /// The top level: one row per topic, no settings of its own.
    fn render_settings_root(&self, cx: &mut Context<Self>) -> Vec<gpui::AnyElement> {
        let mut sections = Vec::new();
        // A pending update is the one thing on this page the user has to act
        // on, so it leads instead of waiting at the bottom of About.
        let update_leads = self
            .update_snapshot
            .as_ref()
            .map(|snapshot| snapshot.state.clone())
            .and_then(|state| update_card_model(&state))
            .is_some();
        if update_leads {
            sections.push(self.render_update_section(cx));
        }
        let host_label = self.active_host_label();
        let host_status = self
            .active_host_status()
            .unwrap_or_else(RuntimeStatusView::inactive);
        let connected = self.backend.as_ref().is_some_and(|backend| {
            backend.connection_state().state == RemoteConnectionState::Online
        });
        let appearance = self.app_settings.theme.unwrap_or_default();
        let language = self.app_settings.language.unwrap_or_default();
        sections.extend([
            settings_index_group(
                locale::text("Runtime", "运行时", "執行環境"),
                vec![settings_index_row(
                    "mobile-settings-runtime",
                    "icons/server.svg",
                    locale::common("This phone's runtimes").to_string(),
                    format!("{host_label} · {}", host_status.label()),
                    if connected {
                        theme::accent_success()
                    } else {
                        theme::text_secondary()
                    },
                    cx.listener(|this, _, _, cx| {
                        this.open_settings_page(SettingsPage::Connection, cx)
                    }),
                )],
            ),
            settings_index_group(
                locale::text("This app", "本应用", "本應用"),
                vec![
                    settings_index_row(
                        "mobile-settings-appearance",
                        "icons/palette.svg",
                        locale::common("Appearance").to_string(),
                        locale::common(appearance.label()).to_string(),
                        theme::text_secondary(),
                        cx.listener(|this, _, _, cx| {
                            this.open_settings_page(SettingsPage::Appearance, cx)
                        }),
                    ),
                    settings_index_row(
                        "mobile-settings-conversation",
                        "icons/message-square.svg",
                        locale::text("Conversation", "会话", "會話").to_string(),
                        locale::text("Timeline display", "时间线显示", "時間線顯示").to_string(),
                        theme::text_secondary(),
                        cx.listener(|this, _, _, cx| {
                            this.open_settings_page(SettingsPage::Conversation, cx)
                        }),
                    ),
                    settings_index_row(
                        "mobile-settings-notifications",
                        "icons/activity.svg",
                        locale::common("Notifications").to_string(),
                        if self.app_settings.notifications {
                            locale::common("On").to_string()
                        } else {
                            locale::common("Off").to_string()
                        },
                        theme::text_secondary(),
                        cx.listener(|this, _, _, cx| {
                            this.open_settings_page(SettingsPage::Notifications, cx)
                        }),
                    ),
                    settings_index_row(
                        "mobile-settings-language",
                        "icons/globe.svg",
                        locale::common("Language").to_string(),
                        locale::localized_label(language.label()),
                        theme::text_secondary(),
                        cx.listener(|this, _, _, cx| this.cycle_language_setting(cx)),
                    ),
                ],
            ),
            settings_index_group(
                locale::common("About"),
                vec![settings_index_row(
                    "mobile-settings-about",
                    "icons/vibex-mark.svg",
                    locale::common("About").to_string(),
                    env!("CARGO_PKG_VERSION").to_string(),
                    theme::text_secondary(),
                    cx.listener(|this, _, _, cx| this.open_settings_page(SettingsPage::About, cx)),
                )],
            ),
        ]);
        sections
    }

    /// Runtime: what this phone is paired with, and how to leave it.
    fn render_settings_connection(&self, cx: &mut Context<Self>) -> Vec<gpui::AnyElement> {
        let Some(entry) = self.active_host_entry() else {
            return vec![settings_empty_note(locale::text(
                "No runtime is connected. Pair one to start a session.",
                "尚未连接运行时。配对后即可开始会话。",
                "尚未連線執行環境。配對後即可開始工作階段。",
            ))];
        };
        let host_label = self.active_host_label();
        let host_url = self.active_host_url();
        let server_id = entry.bundle.expected_server_id.clone();
        let connected = self.backend.as_ref().is_some_and(|backend| {
            backend.connection_state().state == RemoteConnectionState::Online
        });
        let mut rows = vec![settings_group(
            locale::common("Connection"),
            vec![
                settings_value_row(
                    "mobile-settings-host",
                    host_label,
                    String::new(),
                    if connected {
                        locale::common("Connected").to_string()
                    } else {
                        locale::common("Offline").to_string()
                    },
                ),
                settings_value_row(
                    "mobile-settings-host-url",
                    locale::common("Address").to_string(),
                    host_url,
                    String::new(),
                ),
                settings_value_row(
                    "mobile-settings-server-id",
                    locale::common("Server ID").to_string(),
                    server_id,
                    String::new(),
                ),
            ],
        )];
        rows.push(settings_group(
            locale::text("Manage", "管理", "管理"),
            vec![
                settings_nav_row(
                    "mobile-settings-switch-host",
                    locale::text("Switch runtime", "切换运行时", "切換執行環境").to_string(),
                    locale::text(
                        "Pair, rename, or remove a desktop",
                        "配对、重命名或移除桌面端",
                        "配對、重新命名或移除桌面版",
                    )
                    .to_string(),
                    String::new(),
                    cx.listener(Self::open_pairing),
                ),
                settings_nav_row(
                    "mobile-settings-reconnect-host",
                    locale::text("Reconnect", "重新连接", "重新連線").to_string(),
                    locale::text(
                        "Retry this runtime without re-pairing",
                        "无需重新配对即可重试",
                        "無需重新配對即可重試",
                    )
                    .to_string(),
                    String::new(),
                    cx.listener(Self::reconnect_active_host),
                ),
            ],
        ));
        if self.backend.is_some() {
            rows.push(settings_danger_note(
                "mobile-settings-disconnect",
                locale::text("Disconnect desktop", "断开桌面端", "中斷桌面版連線"),
                locale::text(
                    "Ends this connection. Nothing is unpaired.",
                    "仅结束本次连接，不会解除配对。",
                    "僅結束本次連線，不會解除配對。",
                ),
                cx.listener(|this, event, window, cx| this.disconnect_host(event, window, cx)),
            ));
        }
        rows
    }

    /// Appearance: how the app looks, then how it behaves.
    ///
    /// The language is not here: the root's own row steps it, and a second copy
    /// of the same control one page in only asks the reader which of the two is
    /// the real one.
    fn render_settings_appearance(&self, cx: &mut Context<Self>) -> Vec<gpui::AnyElement> {
        let preference = self.app_settings.theme.unwrap_or_default();
        let is_dark = theme::is_dark();
        let palette_id = theme_selection_id(&self.app_settings.theme_selection, is_dark)
            .map(str::to_string)
            .unwrap_or_else(|| vibex_ui::default_theme_id(theme::mode(is_dark)).to_string());
        let palette_name = vibex_ui::themes_for(theme::mode(is_dark))
            .find(|theme| theme.id == palette_id)
            .map(|theme| theme.name.to_string())
            .unwrap_or_else(|| palette_id.clone());
        vec![
            settings_group(
                locale::common("Appearance"),
                vec![
                    settings_nav_row(
                        "mobile-settings-theme",
                        locale::common("Theme").to_string(),
                        String::new(),
                        locale::common(preference.label()).to_string(),
                        cx.listener(|this, _, window, cx| {
                            let current = this.app_settings.theme.unwrap_or_default();
                            let next = match current {
                                theme::AppearanceMode::System => theme::AppearanceMode::Light,
                                theme::AppearanceMode::Light => theme::AppearanceMode::Dark,
                                theme::AppearanceMode::Dark => theme::AppearanceMode::System,
                            };
                            this.update_theme_mode(next, window, cx);
                        }),
                    ),
                    settings_nav_row(
                        "mobile-settings-palette",
                        locale::common("Palette").to_string(),
                        locale::text(
                            "Choose the light and dark palettes",
                            "选择浅色与深色调色板",
                            "選擇淺色與深色調色盤",
                        )
                        .to_string(),
                        palette_name.clone(),
                        cx.listener(|this, _, _, cx| {
                            this.settings_palette_open = true;
                            cx.notify();
                        }),
                    ),
                    settings_nav_row(
                        "mobile-settings-text-size",
                        locale::text("Text size", "文字大小", "文字大小").to_string(),
                        String::new(),
                        text_size_label(self.app_settings.font_scale_percent),
                        cx.listener(|this, _, window, cx| this.cycle_text_size(window, cx)),
                    ),
                ],
            ),
            settings_group(
                locale::text("Behaviour", "行为", "行為"),
                vec![
                    settings_switch_row(
                        "mobile-settings-reduce-motion",
                        locale::text("Reduce motion", "减少动效", "減少動效").to_string(),
                        locale::text(
                            "Skip page and sheet transitions",
                            "跳过页面与弹层的过渡动画",
                            "跳過頁面與彈層的轉場動畫",
                        )
                        .to_string(),
                        self.app_settings.reduce_motion,
                        true,
                        cx.listener(|this, _, _, cx| {
                            this.app_settings.reduce_motion = !this.app_settings.reduce_motion;
                            theme::set_reduce_motion(this.app_settings.reduce_motion);
                            this.persist_app_settings(cx);
                        }),
                    ),
                    settings_switch_row(
                        "mobile-settings-haptics",
                        locale::text("Haptic feedback", "触感反馈", "觸感回饋").to_string(),
                        locale::text(
                            "Vibrate for gestures and finished actions",
                            "手势与操作完成时振动",
                            "手勢與操作完成時震動",
                        )
                        .to_string(),
                        self.app_settings.haptics,
                        true,
                        cx.listener(|this, _, _, cx| {
                            let enabled = !this.app_settings.haptics;
                            this.app_settings.haptics = enabled;
                            // Turning feedback on gives the switch's own tick,
                            // which is the first one the reader will feel.
                            // Turning it off gives the last, and the new value
                            // has to land after it or the tick is dropped by
                            // the very preference it is confirming.
                            if enabled {
                                crate::platform::set_haptics_enabled(true);
                                crate::platform::haptic(crate::platform::Haptic::Selection);
                            } else {
                                crate::platform::haptic(crate::platform::Haptic::Selection);
                                crate::platform::set_haptics_enabled(false);
                            }
                            this.persist_app_settings(cx);
                        }),
                    ),
                    settings_switch_row(
                        "mobile-settings-keep-screen-on",
                        locale::text("Keep the screen on", "保持屏幕常亮", "保持螢幕常亮")
                            .to_string(),
                        locale::text(
                            "While a turn runs or the terminal is open",
                            "当回合运行中或终端打开时",
                            "當回合執行中或終端開啟時",
                        )
                        .to_string(),
                        self.app_settings.keep_screen_on,
                        true,
                        cx.listener(|this, _, _, cx| {
                            this.app_settings.keep_screen_on = !this.app_settings.keep_screen_on;
                            this.persist_app_settings(cx);
                            this.sync_keep_screen_on(cx);
                        }),
                    ),
                ],
            ),
        ]
    }

