    #[test]
    fn mobile_timeline_metadata_truncates_to_one_line() {
        assert_eq!(
            truncate_single_line("  provider\nmodel  ", 32),
            "provider model"
        );
        assert_eq!(truncate_single_line("abcdef", 5), "ab...");
        assert_eq!(truncate_single_line("abcdef", 3), "...");
        assert_eq!(truncate_single_line("abcdef", 2), "..");
        assert_eq!(truncate_single_line("abcdef", 0), "");
    }

    #[test]
    fn a_conversation_match_names_the_line_it_was_found_in() {
        // The search takes the row and the line, because a phone cannot mark a
        // word inside a Markdown view: the reader is shown where the match is.
        let row = |title: &str, body: &str| TimelineRow {
            id: format!("row:{title}"),
            kind: TimelineRowKind::AgentMessage,
            item_ids: Vec::new(),
            turn_id: None,
            turn_item_count: 0,
            turn_failed: false,
            turn_pending_permission: false,
            conclusion: false,
            first_sequence: 0,
            last_sequence: 0,
            timestamp_ms: 0,
            title: title.to_string(),
            body: body.to_string(),
            streaming: false,
            collapsible: false,
            pending_permission: false,
            failed: false,
            runtime_attribution: None,
            file_path: None,
        };
        let query = "needle";
        let body = "first line\nsecond line with a NEEDLE in it\nthird";
        let found = body
            .lines()
            .find(|line| line.to_lowercase().contains(query))
            .map(str::trim)
            .expect("the line is found case-insensitively");
        assert_eq!(found, "second line with a NEEDLE in it");
        // A row that only matches in its title reports the title.
        let titled = row("needle row", "nothing here");
        let line = if titled.body.to_lowercase().contains(query) {
            titled
                .body
                .lines()
                .find(|line| line.to_lowercase().contains(query))
        } else if titled.title.to_lowercase().contains(query) {
            Some(titled.title.as_str())
        } else {
            None
        };
        assert_eq!(line, Some("needle row"));
    }

    #[test]
    fn a_dollar_prefix_is_read_only_while_the_skill_is_being_typed() {
        assert_eq!(skill_prefix("$rust"), Some("rust"));
        assert_eq!(skill_prefix("write this $ru"), Some("ru"));
        assert_eq!(skill_prefix("$"), Some(""));
        // A finished token is part of the prompt, not a skill being named.
        assert_eq!(skill_prefix("$rust "), None);
        assert_eq!(skill_prefix("no skill here"), None);
        // A second dollar means the token is not a name any more.
        assert_eq!(skill_prefix("$a$b"), None);
    }

    /// A panel and every row in it are identified by the page that drew them.
    ///
    /// Both pages' fields can be on screen at once — the new-session overlay
    /// over the session it was opened from — and GPUI elements may not share an
    /// id, so the panel, its scroll body and its rows all carry the page.
    #[test]
    fn every_suggestion_panel_has_its_own_element_id() {
        let ids = [
            ComposerSuggestionTarget::Session.element_id(),
            ComposerSuggestionTarget::Session.scroll_id(),
            ComposerSuggestionTarget::NewSession.element_id(),
            ComposerSuggestionTarget::NewSession.scroll_id(),
        ];
        let unique = ids.iter().collect::<BTreeSet<_>>();
        assert_eq!(unique.len(), ids.len());
    }

    /// Each trigger opens the tabs the desktop's popup opens.
    ///
    /// `/` carries the Agent's commands and the reusable Prompts, `@` the
    /// workspace files and the collaborators, and `$` its single Skills list —
    /// which is why the last one draws no header at all.
    #[test]
    fn each_trigger_opens_the_desktops_tabs() {
        use AgentCommandTrigger::{Dollar, Mention, Slash};
        assert_eq!(
            ComposerSuggestionTab::tabs(Slash),
            [
                ComposerSuggestionTab::Commands,
                ComposerSuggestionTab::Phrases
            ]
        );
        assert_eq!(
            ComposerSuggestionTab::tabs(Mention),
            [
                ComposerSuggestionTab::Files,
                ComposerSuggestionTab::Delegation
            ]
        );
        assert_eq!(
            ComposerSuggestionTab::tabs(Dollar),
            [ComposerSuggestionTab::Commands]
        );

        // A tab left over from another trigger is clamped into the open one's
        // own list rather than showing rows the trigger does not carry.
        let at = ComposerSuggestions::loading(Mention);
        assert_eq!(
            at.active_tab(ComposerSuggestionTab::Phrases),
            ComposerSuggestionTab::Files
        );
        assert_eq!(
            at.active_tab(ComposerSuggestionTab::Delegation),
            ComposerSuggestionTab::Delegation
        );

        // The tap's meaning follows the tab, not the row.
        assert_eq!(
            suggestion_action(Slash, ComposerSuggestionTab::Commands),
            ComposerSuggestionAction::Command
        );
        assert_eq!(
            suggestion_action(Slash, ComposerSuggestionTab::Phrases),
            ComposerSuggestionAction::Phrase
        );
        assert_eq!(
            suggestion_action(Mention, ComposerSuggestionTab::Files),
            ComposerSuggestionAction::Mention
        );
        assert_eq!(
            suggestion_action(Mention, ComposerSuggestionTab::Delegation),
            ComposerSuggestionAction::Mention
        );
        assert_eq!(
            suggestion_action(Dollar, ComposerSuggestionTab::Commands),
            ComposerSuggestionAction::Skill
        );
    }

    #[test]
    fn a_zoomed_preview_cannot_be_pulled_off_the_screen() {
        let size = gpui::size(px(400.0), px(800.0));
        // At fit there is no slack at all, so every offset collapses to zero.
        assert_eq!(
            clamp_attachment_preview_offset(point(px(120.0), px(-90.0)), 1.0, size),
            point(px(0.0), px(0.0))
        );
        // At 2x the picture may travel by half the width the zoom added.
        assert_eq!(
            clamp_attachment_preview_offset(point(px(999.0), px(-999.0)), 2.0, size),
            point(px(200.0), px(-400.0))
        );
        // An offset already inside the slack is left exactly where it is.
        assert_eq!(
            clamp_attachment_preview_offset(point(px(30.0), px(-40.0)), 2.0, size),
            point(px(30.0), px(-40.0))
        );
    }

