    /// Building a `MobileApp` creates kit input states, which read kit globals.
    /// Those globals are process-wide, so every test that builds one must
    /// install them rather than relying on a sibling test having run first.
    fn init_kit_globals(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
    }

    /// Opens a window rooted at the kit's `Root`, the way the app does.
    ///
    /// Hints land on the notification layer that `Root` mounts, so a test that
    /// asserts one was announced — or that none was — has to open its window
    /// exactly as `open_root_window` does. The app is built inside the window
    /// because `MobileApp::new` needs one, and handed back through the slot.
    fn add_rooted_window_view(
        cx: &mut TestAppContext,
        build: impl FnOnce(&mut Window, &mut Context<MobileApp>) -> MobileApp,
    ) -> (Entity<MobileApp>, &mut gpui::VisualTestContext) {
        let slot: Rc<RefCell<Option<Entity<MobileApp>>>> = Rc::new(RefCell::new(None));
        let handle = slot.clone();
        let (_, cx) = cx.add_window_view(|window, cx| {
            let app = cx.new(|cx| build(window, cx));
            *handle.borrow_mut() = Some(app.clone());
            gpui_component::Root::new(app, window, cx)
        });
        let app = slot
            .borrow()
            .clone()
            .expect("the rooted window built its app");
        (app, cx)
    }

    /// How many hints the toast layer is showing.
    fn mounted_hints(cx: &mut gpui::VisualTestContext) -> usize {
        use gpui_component::WindowExt as _;
        cx.update(|window, cx| window.notifications(cx).len())
    }

    /// Whether a hint of this weight is on screen.
    ///
    /// The toast layer owns the card once it is pushed — the kit does not hand a
    /// notification's text back to its caller — so a test asks the laid-out
    /// bounds for the hint's own selector instead.
    fn hint_is_shown(cx: &mut gpui::VisualTestContext, tone: Tone) -> bool {
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        cx.debug_bounds(tone.selector()).is_some()
    }

    /// Takes every hint off the layer, so a test can watch what is announced
    /// strictly after this point.
    fn clear_hints(cx: &mut gpui::VisualTestContext) {
        use gpui_component::WindowExt as _;
        cx.update(|window, cx| window.clear_notifications(cx));
        // The layer animates a hint out instead of dropping it, so the clock
        // has to cross the exit before the layer is really empty.
        cx.executor().advance_clock(Duration::from_millis(400));
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    #[gpui::test]
    fn platform_event_streams_update_only_their_own_app(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let first_dir = tempfile::tempdir().expect("first mobile data directory");
        let second_dir = tempfile::tempdir().expect("second mobile data directory");
        let (first_sender, first_events) = futures_channel::mpsc::unbounded();
        let (second_sender, second_events) = futures_channel::mpsc::unbounded();
        let (first, cx) = cx.add_window_view(|window, cx| {
            MobileApp::with_platform_events(
                first_dir.path().to_path_buf(),
                PlatformEventStreams {
                    lifecycle_events: first_events,
                    ..PlatformEventStreams::disconnected()
                },
                window,
                cx,
            )
        });
        let second = cx.update(|window, cx| {
            cx.new(|cx| {
                MobileApp::with_platform_events(
                    second_dir.path().to_path_buf(),
                    PlatformEventStreams {
                        lifecycle_events: second_events,
                        ..PlatformEventStreams::disconnected()
                    },
                    window,
                    cx,
                )
            })
        });
        cx.run_until_parked();

        first_sender
            .unbounded_send(MobileLifecycleEvent::Backgrounded)
            .unwrap();
        cx.run_until_parked();
        assert!(first.read_with(cx, |app, _| app.app_backgrounded));
        assert!(!second.read_with(cx, |app, _| app.app_backgrounded));

        first_sender
            .unbounded_send(MobileLifecycleEvent::Resumed)
            .unwrap();
        second_sender
            .unbounded_send(MobileLifecycleEvent::Backgrounded)
            .unwrap();
        cx.run_until_parked();
        assert!(!first.read_with(cx, |app, _| app.app_backgrounded));
        assert!(second.read_with(cx, |app, _| app.app_backgrounded));

        drop(first_sender);
        drop(second_sender);
        cx.run_until_parked();
    }

    /// Lets a sheet finish leaving.
    ///
    /// A sheet keeps its own flag set while its panel falls — that is what
    /// keeps its content in the panel on the way down — so the page clears the
    /// flag only once the fall has landed.
    fn settle_sheet(app: &Entity<MobileApp>, cx: &mut gpui::VisualTestContext) {
        settle_motion(app, cx, theme::SHEET_FALL_MS + 32);
    }

    /// Lets a sheet finish rising, so its panel is where the reader sees it
    /// once it has arrived.
    fn settle_rise(app: &Entity<MobileApp>, cx: &mut gpui::VisualTestContext) {
        app.update(cx, |app, cx| {
            app.sheet.settle_flights();
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    /// Runs the clock past one of a sheet's flights and draws the frame it
    /// lands on.
    fn settle_motion(app: &Entity<MobileApp>, cx: &mut gpui::VisualTestContext, ms: u64) {
        cx.executor().advance_clock(Duration::from_millis(ms));
        app.update(cx, |app, cx| {
            app.sheet.settle_flights();
            cx.notify();
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    /// Draws one frame of a window opened by `add_rooted_window_view`.
    fn draw_rooted_window(cx: &mut gpui::VisualTestContext) {
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    fn click_mobile_control(cx: &mut gpui::VisualTestContext, selector: &'static str) {
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        let bounds = cx
            .debug_bounds(selector)
            .expect("control should be visible");
        cx.simulate_click(bounds.center(), gpui::Modifiers::none());
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    /// Drives one finger drag the way a phone reports it: mobile platforms
    /// synthesize a touch pan as scroll events carrying a `TouchPhase`.
    fn drag_finger(cx: &mut gpui::VisualTestContext, dx: f32, dy: f32) {
        let position = point(px(60.0), px(200.0));
        cx.simulate_event(ScrollWheelEvent {
            position,
            delta: ScrollDelta::Pixels(point(px(dx * 0.25), px(dy * 0.25))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Started,
        });
        cx.simulate_event(ScrollWheelEvent {
            position,
            delta: ScrollDelta::Pixels(point(px(dx * 0.75), px(dy * 0.75))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Moved,
        });
        cx.simulate_event(ScrollWheelEvent {
            position,
            delta: ScrollDelta::Lines(point(0.0, 0.0)),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Ended,
        });
        cx.run_until_parked();
    }

    /// A draft and the files waiting on it are on disk before the process dies
    /// — and a later launch is what reads them back, which is the point of
    /// writing them at all.
    ///
    /// The queue is deliberately not here: it belongs to the Desktop, and a copy
    /// this phone kept would be a second queue sending messages the Desktop
    /// never took.
    #[gpui::test]
    fn unsent_composer_work_survives_a_restart(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().unwrap();
        let session_id = VibexSessionId::new();
        let key = session_id.as_str().to_string();

        let (writing, _cx) = add_rooted_window_view(cx, |window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.composer_drafts
                .insert(key.clone(), "half a thought".to_string());
            app.composer_attachment_drafts.insert(
                key.clone(),
                vec![MessageAttachment {
                    label: "notes.txt".to_string(),
                    mime_type: Some("text/plain".to_string()),
                    uri: Some("data:text/plain;base64,aGVsbG8=".to_string()),
                    inline_text_offset: None,
                }],
            );
            app.flush_composer_state(cx);
            app
        });
        writing.read_with(cx, |app, _| {
            assert!(app.storage.composer_state_path().exists());
        });

        // The next launch: same data dir, nothing carried over in memory.
        let (reopened, cx) = add_rooted_window_view(cx, |window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        reopened.read_with(cx, |app, _| {
            assert_eq!(
                app.composer_drafts.get(&key).map(String::as_str),
                Some("half a thought")
            );
            let attachments = app
                .composer_attachment_drafts
                .get(&key)
                .expect("the files waiting on the draft came back");
            assert_eq!(attachments.len(), 1);
            assert_eq!(attachments[0].label, "notes.txt");
            assert_eq!(
                app.composer_queue_for_open_session().len(),
                0,
                "the queue is the Desktop's, so a cold start reads none of it"
            );
        });
    }

    /// A prompt written while a turn is live is taken, shown, and held — not
    /// dropped.
    ///
    /// This is the bug the queue was invisible for. The RPC that submits a
    /// prompt answers only when the whole turn does, so the phone spent every
    /// turn with an operation in flight. The composer read that as "busy": the
    /// field looked idle, Send did nothing, and the message that should have
    /// been waiting above it was never enqueued.
    #[gpui::test]
    fn a_prompt_written_during_a_turn_waits_in_the_visible_queue(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().unwrap();
        let session_id = VibexSessionId::parse("session_mobile_queue_visibility").unwrap();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            // The composer only exists on the workspace page.
            app.mode = RootMode::Workspace;
            let backend = vibex_backend::DisconnectedBackend::facade();
            let mut controller =
                AgentWorkflowController::new(backend.agent().clone(), backend.capabilities().agent);
            controller.state.selected_session_id = Some(session_id.clone());
            controller.state.active_session.resolve(AgentSession {
                id: session_id.clone(),
                title: "Queue visibility".to_string(),
                project_id: vibex_core::ProjectId::parse("project_queue").unwrap(),
                workspace_id: vibex_core::WorkspaceId::parse("workspace_queue").unwrap(),
                workspace_root: "/tmp/queue".to_string(),
                workspace_mode: WorkspaceMode::CurrentCheckout,
                agent_id: AgentId::parse("claude").unwrap(),
                state: AgentSessionState::Running,
                safety: vibex_core::AgentSessionSafety::workspace_write_ask_on_risk(),
                created_at_ms: 0,
                updated_at_ms: 0,
                last_message_at_ms: 0,
                archived_at_ms: None,
                deleted_at_ms: None,
            });
            app.controller = Some(controller);
            app
        });
        cx.run_until_parked();

        // The exact production state while a turn runs: this phone has already
        // submitted the prompt that started it, and that RPC has not answered
        // because it only answers when the turn does. The old gate read this as
        // a busy composer and returned without taking the message.
        app.update(cx, |app, _| {
            app.turn_submissions_in_flight = 1;
        });
        app.read_with(cx, |app, _| {
            assert!(app.session_turn_live(), "a running session is a live turn");
            assert!(
                !app.composer_busy(),
                "a turn on the wire must not close the composer"
            );
        });

        // Write, then send. Send must take the prompt rather than refuse it.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.composer_input.update(cx, |input, cx| {
                    input.set_value("and then one more", window, cx);
                });
            });
            let _ = window.draw(cx);
        });
        click_mobile_control(cx, "send-message");

        // The composer is emptied and the prompt is on its way to the Desktop's
        // queue. This client holds no copy: the snapshot is what brings the
        // entry back, and until it arrives the queue it can show is the Desktop's
        // last answer.
        app.update(cx, |app, cx| {
            assert!(
                app.composer_input.read(cx).value().is_empty(),
                "the prompt was taken instead of dropped"
            );
            assert_eq!(app.composer_queue_for_open_session().len(), 0);
        });

        // The queue as the Desktop publishes it is what the panel draws, so
        // seeding the view is seeding the panel — the same projection, not a
        // second list kept in parallel.
        app.update(cx, |app, _| {
            app.sidebar_view
                .queued_sends
                .push(vibex_desktop_model::SidebarQueuedSend {
                    message_id: 7,
                    session_id: session_id.as_str().to_string(),
                    text: "and then one more".to_string(),
                    attachments: Vec::new(),
                    mentions: Vec::new(),
                    scheduled_at_ms: None,
                });
        });
        draw_rooted_window(cx);
        assert!(
            cx.debug_bounds("mobile-composer-queue").is_some(),
            "a held prompt is visible above the composer"
        );
        assert!(
            cx.debug_bounds("mobile-composer-queue-clear").is_some(),
            "the queue names itself and offers to be cleared"
        );
        assert!(
            cx.debug_bounds("mobile-composer-queue-pause").is_some(),
            "and offers to pause itself"
        );
        assert!(
            cx.debug_bounds("mobile-composer-queue-mode").is_some(),
            "and to switch between automatic and manual sending"
        );
    }

    /// A send never jumps the messages already waiting.
    ///
    /// The Desktop releases the head of its queue, so a message that went out
    /// immediately while another was waiting would reorder a list the reader set
    /// on purpose. An idle session with a held queue therefore queues too — the
    /// same three admissions the Desktop makes.
    #[gpui::test]
    fn a_send_waits_behind_the_messages_already_held(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().unwrap();
        let session_id = VibexSessionId::parse("session_mobile_queue_order").unwrap();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            let backend = vibex_backend::DisconnectedBackend::facade();
            let mut controller =
                AgentWorkflowController::new(backend.agent().clone(), backend.capabilities().agent);
            controller.state.selected_session_id = Some(session_id.clone());
            // An idle session: nothing is running, so only the held queue can
            // keep this send from going out immediately.
            controller.state.active_session.resolve(AgentSession {
                id: session_id.clone(),
                title: "Queue order".to_string(),
                project_id: vibex_core::ProjectId::parse("project_order").unwrap(),
                workspace_id: vibex_core::WorkspaceId::parse("workspace_order").unwrap(),
                workspace_root: "/tmp/order".to_string(),
                workspace_mode: WorkspaceMode::CurrentCheckout,
                agent_id: AgentId::parse("claude").unwrap(),
                state: AgentSessionState::Idle,
                safety: vibex_core::AgentSessionSafety::workspace_write_ask_on_risk(),
                created_at_ms: 0,
                updated_at_ms: 0,
                last_message_at_ms: 0,
                archived_at_ms: None,
                deleted_at_ms: None,
            });
            app.controller = Some(controller);
            app.sidebar_view
                .queued_sends
                .push(vibex_desktop_model::SidebarQueuedSend {
                    message_id: 1,
                    session_id: session_id.as_str().to_string(),
                    text: "already waiting".to_string(),
                    attachments: Vec::new(),
                    mentions: Vec::new(),
                    scheduled_at_ms: None,
                });
            app
        });
        cx.run_until_parked();

        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.composer_input.update(cx, |input, cx| {
                    input.set_value("second in line", window, cx);
                });
            });
            let _ = window.draw(cx);
        });
        click_mobile_control(cx, "send-message");

        app.update(cx, |app, cx| {
            assert!(
                app.composer_input.read(cx).value().is_empty(),
                "the prompt was taken"
            );
            // The prompt did not leave as a prompt of its own: it is now the
            // Desktop's to hold behind the entry that was already waiting.
            assert!(
                app.pending_user_message.is_none(),
                "nothing was submitted ahead of the queue"
            );
        });
    }

    /// The pause and the send mode are the Desktop's state, not a local flag.
    ///
    /// Both controls read the published queue and write it back through the same
    /// sidebar channel every other shared mark uses, so a pause set on the phone
    /// is a pause the Desktop honours — which is the only way it can change when
    /// the Desktop releases the next message.
    #[gpui::test]
    fn the_queue_controls_read_and_write_the_shared_state(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().unwrap();
        let session_id = VibexSessionId::parse("session_mobile_queue_controls").unwrap();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            let backend = vibex_backend::DisconnectedBackend::facade();
            let mut controller =
                AgentWorkflowController::new(backend.agent().clone(), backend.capabilities().agent);
            controller.state.selected_session_id = Some(session_id.clone());
            app.controller = Some(controller);
            app.sidebar_view
                .queued_sends
                .push(vibex_desktop_model::SidebarQueuedSend {
                    message_id: 1,
                    session_id: session_id.as_str().to_string(),
                    text: "waiting".to_string(),
                    attachments: Vec::new(),
                    mentions: Vec::new(),
                    scheduled_at_ms: None,
                });
            app
        });
        cx.run_until_parked();

        app.read_with(cx, |app, _| {
            assert!(
                app.composer_queue_sends_automatically(),
                "a queue nobody has switched starts automatic"
            );
            assert!(!app.composer_queue_paused(), "and starts running");
        });

        app.update(cx, |app, _| {
            app.sidebar_view
                .manual_queue_session_ids
                .insert(session_id.as_str().to_string());
            app.sidebar_view
                .paused_queue_session_ids
                .insert(session_id.as_str().to_string());
        });
        app.read_with(cx, |app, _| {
            assert!(
                !app.composer_queue_sends_automatically(),
                "manual mode is what the Desktop published"
            );
            assert!(
                app.composer_queue_paused(),
                "and so is the pause the Desktop reports"
            );
        });

        draw_rooted_window(cx);
        assert!(
            cx.debug_bounds("mobile-composer-queue-pause").is_some(),
            "a paused queue still offers the way out of the pause"
        );
    }

    /// A repaint is where the Android keyboard is told what the focused field
    /// holds, so a held Backspace has something to repeat against.
    #[gpui::test]
    fn painting_publishes_the_focused_composer_to_the_keyboard(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().unwrap();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            // The composer only exists on the workspace page.
            app.mode = RootMode::Workspace;
            app.composer_input.update(cx, |input, cx| {
                input.set_value("你好", window, cx);
                input.focus(window, cx);
            });
            app
        });

        // The build itself paints, and the recorder is process-thread local, so
        // the frames this test is about are read from an empty one.
        crate::platform::clear_editor_documents();

        // The caret moving is what a repeat delete has to see, and moving it
        // does not emit a change event, so the next paint is what publishes it.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.composer_input.update(cx, |input, cx| {
                    // After "你": one UTF-16 unit in but three bytes in.
                    input.set_selected_range(3..3, cx);
                });
            });
            let _ = window.draw(cx);
        });
        assert_eq!(
            crate::platform::editor_documents(),
            vec![("你好".to_owned(), 1..1)],
            "the field's text and caret reach the keyboard in UTF-16 units"
        );

        // A frame that changed nothing does not cross the bridge again.
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert_eq!(crate::platform::editor_documents().len(), 1);

        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.composer_input.update(cx, |input, cx| {
                    input.set_selected_range(0..0, cx);
                });
            });
            let _ = window.draw(cx);
        });
        assert_eq!(
            crate::platform::editor_documents().last(),
            Some(&("你好".to_owned(), 0..0)),
            "every caret move is published, so a held delete can keep repeating"
        );

        // Text arriving with the caret staying put is published too: a commit
        // that replaces the draft in place must still reach the keyboard.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.composer_input.update(cx, |input, cx| {
                    input.set_value("你好呀", window, cx);
                    input.set_selected_range(0..0, cx);
                });
            });
            let _ = window.draw(cx);
        });
        assert_eq!(
            crate::platform::editor_documents().last(),
            Some(&("你好呀".to_owned(), 0..0)),
            "a text change publishes even when the caret did not move"
        );
    }

    /// A half-filled elicitation belongs to the session that asked for it.
    ///
    /// Opening another conversation replaces the timeline the form was painted
    /// from. The options the reader picked and the text they typed are an
    /// answer they have not sent yet, so they must still be there when the
    /// conversation comes back; only a request the timeline shows as settled
    /// clears its form.
    #[gpui::test]
    fn a_half_filled_elicitation_survives_a_session_switch(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let session_id = VibexSessionId::parse("session_elicitation_a").expect("session id");
        let other_session_id = VibexSessionId::parse("session_elicitation_b").expect("session id");
        let request = vibex_core::ElicitationRequest {
            id: RequestId::new(),
            session_id: session_id.clone(),
            provider_request_id: None,
            tool_call_id: None,
            message: "Which state model should the rail use?".into(),
            title: None,
            description: None,
            fields: vec![
                vibex_core::ElicitationField {
                    id: "approach".into(),
                    title: "Approach".into(),
                    description: None,
                    required: false,
                    kind: ElicitationFieldKind::Text {
                        min_length: None,
                        max_length: None,
                        pattern: None,
                        format: None,
                        default: None,
                        options: vec![vibex_core::ElicitationOption {
                            value: "global".into(),
                            title: "Global state".into(),
                            description: None,
                        }],
                    },
                },
                vibex_core::ElicitationField {
                    id: "notes".into(),
                    title: "Notes".into(),
                    description: None,
                    required: false,
                    kind: ElicitationFieldKind::Text {
                        min_length: None,
                        max_length: None,
                        pattern: None,
                        format: None,
                        default: None,
                        options: Vec::new(),
                    },
                },
            ],
            status: vibex_core::ElicitationRequestStatus::Pending,
            requested_at_ms: 1,
        };
        let timeline_item = |session_id: &VibexSessionId,
                             sequence: i64,
                             source: TimelineSource,
                             payload: TimelinePayload| TimelineItem {
            id: vibex_core::TimelineItemId::new(),
            session_id: session_id.clone(),
            sequence,
            timestamp_ms: sequence,
            source,
            kind: payload.kind(),
            correlation_id: None,
            provider_correlation_id: None,
            redaction_state: TimelineRedactionState::None,
            execution_attribution: None,
            payload_depth: vibex_core::TimelinePayloadDepth::Detail,
            payload,
        };
        let request_payload = TimelinePayload::ElicitationRequest(request.clone());
        let resolution_payload = |session_id: &VibexSessionId, sequence: i64| -> TimelinePayload {
            TimelinePayload::ElicitationResolution(vibex_core::ElicitationResolution {
                request_id: request.id.clone(),
                session_id: session_id.clone(),
                action: ElicitationResolutionAction::Accept,
                answers: BTreeMap::new(),
                responder_device_id: None,
                resolved_at_ms: sequence,
            })
        };

        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.backend = Some(backend.clone());
            let mut controller =
                AgentWorkflowController::new(backend.clone(), backend.capability_snapshot().agent);
            controller.state.selected_session_id = Some(session_id.clone());
            controller.state.timeline.replace_authoritative(
                session_id.clone(),
                [timeline_item(
                    &session_id,
                    1,
                    TimelineSource::Provider,
                    request_payload.clone(),
                )],
            );
            app.controller = Some(controller);
            app
        });
        cx.run_until_parked();

        let notes_key = (request.id.to_string(), "notes".to_string());
        app.update_in(cx, |app, window, cx| {
            app.sync_elicitation_form(window, cx);
            app.set_elicitation_option(request.id.clone(), "approach".into(), "global".into(), cx);
            let notes = app
                .elicitation_inputs
                .get(&notes_key)
                .cloned()
                .expect("text field input");
            notes.update(cx, |notes, cx| {
                notes.set_value("the rail stays compact", window, cx)
            });

            // Opening another conversation replaces the timeline the form was
            // painted from, which must not take the answer with it.
            if let Some(controller) = app.controller.as_mut() {
                controller.state.selected_session_id = Some(other_session_id.clone());
                controller.state.timeline.replace_authoritative(
                    other_session_id.clone(),
                    std::iter::empty::<TimelineItem>(),
                );
            }
            app.sync_elicitation_form(window, cx);
            let draft = app
                .elicitation_drafts
                .get(request.id.as_str())
                .expect("a pending form survives the conversation it was painted in");
            assert_eq!(draft.text("approach"), Some("global"));
            assert!(app.elicitation_inputs.contains_key(&notes_key));
            assert_eq!(notes.read(cx).value().as_ref(), "the rail stays compact");

            // Seeing the resolution is what settles it.
            if let Some(controller) = app.controller.as_mut() {
                controller.state.timeline.replace_authoritative(
                    session_id.clone(),
                    [
                        timeline_item(
                            &session_id,
                            1,
                            TimelineSource::Provider,
                            request_payload.clone(),
                        ),
                        timeline_item(
                            &session_id,
                            2,
                            TimelineSource::User,
                            resolution_payload(&session_id, 2),
                        ),
                    ],
                );
            }
            app.sync_elicitation_form(window, cx);
            assert!(!app.elicitation_drafts.contains_key(request.id.as_str()));
            assert!(!app.elicitation_inputs.contains_key(&notes_key));
        });
    }

    #[gpui::test]
    fn runtime_entry_opens_pairing_and_returns_without_replacing_the_session(
        cx: &mut TestAppContext,
    ) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let session_id = VibexSessionId::new();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.backend = Some(backend.clone());
            let mut controller =
                AgentWorkflowController::new(backend.clone(), backend.capability_snapshot().agent);
            controller.state.selected_session_id = Some(session_id.clone());
            app.controller = Some(controller);
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app.composer_input.update(cx, |input, cx| {
                input.set_value("unfinished message", window, cx);
            });
            app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
            app
        });
        cx.run_until_parked();

        for return_control in ["pairing-back", "escape", "pairing-runtime-runtime-a"] {
            app.update(cx, |app, cx| {
                app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
            });
            cx.executor()
                .advance_clock(Duration::from_millis(theme::DRAWER_OPEN_ANIMATION_MS));
            cx.run_until_parked();
            click_mobile_control(cx, "mobile-host-switcher");
            assert_eq!(
                app.read_with(cx, |app, _| app.overlay),
                Some(MobileOverlay::Pairing)
            );
            assert!(cx.debug_bounds("pairing-runtimes").is_some());
            let back = cx.debug_bounds("pairing-back").expect("return control");
            assert!(back.size.width >= px(theme::TOUCH_TARGET));
            assert!(back.size.height >= px(theme::TOUCH_TARGET));

            if return_control == "pairing-back" {
                click_mobile_control(cx, "pairing-manual-toggle");
                assert_eq!(
                    app.read_with(cx, |app, _| app.pairing_panel),
                    PairingPanel::Manual
                );
                cx.simulate_keystrokes("back");
                settle_sheet(&app, cx);
                assert_eq!(
                    app.read_with(cx, |app, _| app.pairing_panel),
                    PairingPanel::None
                );
                assert_eq!(
                    app.read_with(cx, |app, _| app.overlay),
                    Some(MobileOverlay::Pairing)
                );

                // A claim still in flight owns the page until it resolves.
                app.update(cx, |app, cx| {
                    app.pairing_busy = true;
                    cx.notify();
                });
                click_mobile_control(cx, "pairing-back");
                cx.simulate_keystrokes("back");
                click_mobile_control(cx, "pairing-runtime-menu-runtime-a");
                click_mobile_control(cx, "pairing-runtime-runtime-a");
                assert_eq!(
                    app.read_with(cx, |app, _| app.overlay),
                    Some(MobileOverlay::Pairing)
                );
                app.update(cx, |app, cx| {
                    app.pairing_busy = false;
                    cx.notify();
                });
            }

            if return_control == "escape" {
                cx.simulate_keystrokes("escape");
            } else {
                click_mobile_control(cx, return_control);
            }
            app.read_with(cx, |app, cx| {
                assert_eq!(app.mode, RootMode::Workspace);
                assert!(app.overlay.is_none());
                assert!(app.overlay_parents.is_empty());
                assert!(app.drawer_open, "return to the project/session page");
                assert!(Arc::ptr_eq(
                    app.backend.as_ref().expect("active backend"),
                    &backend
                ));
                assert_eq!(
                    app.controller
                        .as_ref()
                        .expect("active session")
                        .state
                        .selected_session_id,
                    Some(session_id.clone()),
                );
                assert_eq!(
                    app.composer_input.read(cx).value().as_ref(),
                    "unfinished message"
                );
            });
        }

        app.update(cx, |app, cx| {
            app.known_hosts.push(MobileHostEntry::from_bundle(
                &host_bundle("runtime-b", "cloud"),
                RemoteServerKind::Headless,
            ));
            app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
        });
        cx.executor()
            .advance_clock(Duration::from_millis(theme::DRAWER_OPEN_ANIMATION_MS));
        cx.run_until_parked();
        click_mobile_control(cx, "mobile-host-switcher");
        click_mobile_control(cx, "pairing-runtime-runtime-b");
        // A runtime whose stored credential carries no route cannot be reached,
        // and the failure is what the phone has to say about it. It says it as
        // a hint: nothing about a failed switch belongs in the pairing page's
        // own layout.
        assert!(hint_is_shown(cx, Tone::Error));
        app.read_with(cx, |app, _| {
            assert_eq!(app.overlay, Some(MobileOverlay::Pairing));
            assert!(Arc::ptr_eq(
                app.backend.as_ref().expect("original backend"),
                &backend
            ));
        });

        // The selected backend is idle in this fixture, so its menu offers
        // Cancel. It disconnects explicitly and retains the saved runtimes.
        click_mobile_control(cx, "pairing-runtime-menu-runtime-a");
        settle_rise(&app, cx);
        click_mobile_control(cx, "mobile-runtime-cancel");
        app.read_with(cx, |app, _| {
            assert_eq!(app.mode, RootMode::Pairing);
            assert!(app.backend.is_none());
            assert!(app.controller.is_none());
            assert!(app.overlay.is_none());
            assert_eq!(app.known_hosts.len(), 2);
        });
        assert!(cx.debug_bounds("pairing-back").is_none());
    }

    /// The unavailable-connection screen's Disconnect ends the connection
    /// attempt, not the pairing. The runtime keeps its stored credential, so the
    /// first screen this returns to still lists it — the reported bug was that
    /// the button deleted the runtime out from under that list.
    ///
    /// It also says nothing: the failure that put the phone on that screen
    /// described the connection the user has just ended, so the pairing page it
    /// returns to carries no transport message about it.
    #[gpui::test]
    fn disconnecting_an_unreachable_desktop_keeps_the_saved_runtime(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let host_id = bundle.host_id().to_string();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app.persist_known_hosts();
            app.backend = Some(backend);
            // The state a launch-time auto-connect leaves behind when the
            // desktop cannot be reached.
            app.mode = RootMode::Connecting;
            app.fail(BackendError::offline(
                "remote_transport_unreachable",
                "no route to host",
            ));
            app
        });
        cx.run_until_parked();

        // The failure that put the phone on that screen has already been
        // announced and read by now, so the layer starts empty and what lands
        // on it next is the disconnect's own doing.
        clear_hints(cx);

        click_mobile_control(cx, "disconnect-unavailable-desktop");

        app.read_with(cx, |app, _| {
            assert_eq!(app.mode, RootMode::Pairing);
            assert!(app.backend.is_none());
            assert!(app.controller.is_none());
            // Still saved and still the runtime the phone was on, so the list
            // about to paint leads with it while it probes whether it answers.
            assert_eq!(app.known_hosts.len(), 1);
            assert_eq!(app.known_hosts[0].id, host_id);
            assert_eq!(app.active_host_id.as_deref(), Some(host_id.as_str()));
            assert_eq!(
                app.host_reachability.get(&host_id),
                Some(&HostReachability::Probing)
            );
            // The credential is what a wrong handler would have deleted.
            let stored = app.storage.load_hosts().expect("stored hosts file");
            assert_eq!(stored.len(), 1);
            assert_eq!(stored[0].bundle.expected_server_id, "runtime-a");
        });
        // The failure the phone was on that screen for is not repeated on the
        // screen it leaves to. `click_mobile_control` already painted, so every
        // hint queued before it is on the layer by now, and the layer is empty
        // once the disconnect's own teardown has had its say.
        assert_eq!(mounted_hints(cx), 0, "disconnecting announces nothing");
    }

    /// The unavailable page really lays out what its renderer builds: the
    /// product wordmark, the failure line, and the three action rows — each
    /// one wide enough for a glyph and a label — in that order down the page.
    ///
    /// The source test above pins the markup; this one pins the result, because
    /// a glyph that is built but never laid out (an unregistered asset, a child
    /// on a row that paints nothing) is silent in both GPUI and a source scan.
    #[gpui::test]
    fn the_unavailable_page_paints_its_wordmark_and_all_three_actions(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        // The locked-down anchor: the sweep is the working state's, so a parked
        // lockup is what this page must paint. Reduce Motion also keeps the
        // frame this test measures from moving under it.
        cx.update(|cx| cx.set_reduce_motion(true));
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app.persist_known_hosts();
            app.backend = Some(backend);
            app.mode = RootMode::Connecting;
            app.fail(BackendError::offline(
                "remote_transport_unreachable",
                "no route to host",
            ));
            app
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        clear_hints(cx);

        let brand = cx
            .debug_bounds("connecting-brand")
            .expect("the failure page should wear the product wordmark");
        let retry = cx
            .debug_bounds("retry-desktop-connection")
            .expect("the failed connection should offer Retry");
        let disconnect = cx
            .debug_bounds("disconnect-unavailable-desktop")
            .expect("the failed connection should offer Disconnect");
        let switch = cx
            .debug_bounds("switch-host-while-connecting")
            .expect("a saved runtime should be switchable");

        // Brand above the actions, actions in the order the page reads.
        assert!(
            brand.bottom() <= retry.top(),
            "the wordmark should sit above the actions, got {brand:?} and {retry:?}"
        );
        assert!(retry.bottom() <= disconnect.top());
        assert!(disconnect.bottom() <= switch.top());

        // A glyph and a label need the row's height and its inner width, and a
        // row that collapsed to its text would leave the reader nothing to aim
        // at.
        for (name, bounds) in [
            ("Retry", retry),
            ("Disconnect", disconnect),
            ("Switch host", switch),
        ] {
            assert!(
                f32::from(bounds.size.height) >= theme::TOUCH_TARGET,
                "{name} should keep its touch target, got {bounds:?}"
            );
            assert!(
                f32::from(bounds.size.width) > theme::TOUCH_TARGET,
                "{name} should be wide enough for its glyph and label, got {bounds:?}"
            );
        }

        // The page is the unavailable one, not a spinner: the failure branch is
        // what painted, so the wordmark is parked rather than sweeping.
        assert!(!app.read_with(cx, |app, _| app.operation_busy));
    }

    /// A phone that comes back to a connection the transport never recovers
    /// must not keep the page it left behind. Holding that stale workspace is
    /// what made a backgrounded app look as if it had closed; the phone drops
    /// the dead connection instead and lands on the pairing page, where the
    /// runtime it was on is still listed and one tap connects again.
    #[gpui::test]
    fn a_resume_the_transport_never_recovers_returns_to_the_pairing_page(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let host_id = bundle.host_id().to_string();
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app.persist_known_hosts();
            app.mode = RootMode::Workspace;
            app.backend = Some(backend.clone());
            app.controller = Some(AgentWorkflowController::new(
                backend.clone(),
                backend.capability_snapshot().agent,
            ));
            app
        });
        cx.run_until_parked();

        app.update(cx, |app, cx| {
            app.wait_for_resume_recovery(backend.clone(), cx);
        });
        // The transport never reaches Online and never reports a state a retry
        // cannot leave, so the poll window is the only thing that can end the
        // wait; a connection that recovers first takes the other branch.
        cx.executor().advance_clock(
            RESUME_RECOVERY_POLL_INTERVAL * (RESUME_RECOVERY_POLL_ATTEMPTS as u32 + 1),
        );
        cx.run_until_parked();

        app.read_with(cx, |app, _| {
            assert_eq!(app.mode, RootMode::Pairing);
            assert!(app.backend.is_none(), "the dead connection is dropped");
            assert!(app.controller.is_none());
            assert!(app.overlay.is_none());
            // Still saved and still the runtime the phone was on, so the page
            // that just painted leads with it.
            assert_eq!(app.known_hosts.len(), 1);
            assert_eq!(app.active_host_id.as_deref(), Some(host_id.as_str()));
            let stored = app.storage.load_hosts().expect("stored hosts file");
            assert_eq!(stored.len(), 1);
        });
        assert!(
            hint_is_shown(cx, Tone::Warning),
            "the phone says why it left the workspace"
        );
    }

    /// Settings' Disconnect is the same contract as the unavailable screen's:
    /// it ends the connection and keeps every saved runtime, including the ones
    /// it was not connected to. Deleting one stays the runtime action sheet's
    /// separate, confirmed Remove.
    #[gpui::test]
    fn disconnecting_from_settings_keeps_every_saved_runtime(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let routed = |server_id: &str, display_name: &str| {
            let mut bundle = host_bundle(server_id, display_name);
            bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
                local_network: None,
                direct_candidates: vec![bundle.record.server_url.clone()],
                relay: None,
            });
            bundle
        };
        let bundle = routed("runtime-a", "studio");
        let backend = bundle.backend().expect("valid saved runtime");
        let other = routed("runtime-b", "cloud");
        let (app, cx) = cx.add_window_view(|window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app.known_hosts.push(MobileHostEntry::from_bundle(
                &other,
                RemoteServerKind::Headless,
            ));
            app.persist_known_hosts();
            app.backend = Some(backend);
            app.open_settings(&noop_mouse_up(), window, cx);
            app
        });
        cx.run_until_parked();
        // Disconnect lives on the Runtime page, behind the root list.
        click_mobile_control(cx, "mobile-settings-runtime");
        cx.run_until_parked();
        app.update(cx, |app, cx| {
            app.settings_scroll.scroll_to_bottom();
            cx.notify();
        });

        click_mobile_control(cx, "mobile-settings-disconnect");

        app.read_with(cx, |app, _| {
            assert_eq!(app.mode, RootMode::Pairing);
            assert!(app.backend.is_none());
            assert!(app.overlay.is_none(), "disconnecting closes Settings");
            assert_eq!(app.known_hosts.len(), 2);
            // Both credentials survive, not just the runtime the phone was on.
            let stored = app.storage.load_hosts().expect("stored hosts file");
            assert_eq!(stored.len(), 2);
        });
    }

    #[gpui::test]
    fn runtime_management_returns_through_pairing_to_its_original_parent(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.remember_host(
                &host_bundle("runtime-a", "studio"),
                RemoteServerKind::Desktop,
            );
            app.known_hosts.push(MobileHostEntry::from_bundle(
                &host_bundle("runtime-b", "cloud"),
                RemoteServerKind::Headless,
            ));
            app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
            app.open_settings(&noop_mouse_up(), window, cx);
            app.open_pairing(&noop_mouse_up(), window, cx);
            app
        });
        cx.run_until_parked();
        click_mobile_control(cx, "pairing-runtime-menu-runtime-b");
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::HostActions)
        );
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.open_host_detail(&noop_mouse_up(), window, cx)
            });
            let _ = window.draw(cx);
        });

        for expected in [MobileOverlay::HostActions, MobileOverlay::Pairing] {
            cx.simulate_keystrokes("back");
            assert_eq!(app.read_with(cx, |app, _| app.overlay), Some(expected));
        }
        assert!(app.read_with(cx, |app, _| app.is_pairing_visible()));

        // Removing another runtime returns to this same list and preserves
        // Settings beneath it, with no stale sheet targeting the removed row.
        click_mobile_control(cx, "pairing-runtime-menu-runtime-b");
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.open_host_remove(&noop_mouse_up(), window, cx);
                app.remove_host("runtime-b".to_string(), window, cx);
            });
            let _ = window.draw(cx);
        });
        app.read_with(cx, |app, _| {
            assert_eq!(app.known_hosts.len(), 1);
            assert_eq!(app.overlay, Some(MobileOverlay::Pairing));
            assert_eq!(app.overlay_parents, vec![MobileOverlay::Settings]);
            assert!(app.host_overlay_target.is_none());
        });

        cx.simulate_keystrokes("back");
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Settings)
        );
        cx.simulate_keystrokes("back");
        app.read_with(cx, |app, _| {
            assert!(app.overlay.is_none());
            assert!(app.drawer_open);
        });
    }

    #[gpui::test]
    fn back_keystroke_pops_the_top_of_the_page_stack(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        app.update(cx, |app, cx| {
            app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.back_stack.clone()),
            vec![BackScreen::SessionsDrawer]
        );

        // The constructor leaves the window root focused, so the keystroke has
        // a dispatch path even before any text input has taken focus; this
        // assertion fails if back navigation silently dead-ends again.
        cx.simulate_keystrokes("back");

        let (stack, drawer_open) =
            app.read_with(cx, |app, _| (app.back_stack.clone(), app.drawer_open));
        assert!(stack.is_empty(), "back stack after back key: {stack:?}");
        assert!(!drawer_open, "sessions drawer must close on back");
    }

    /// Back at the root has nothing left to close, and that is all it does. The
    /// system's own back gesture is the same rightward edge swipe the sessions
    /// drawer is dragged open with, so a root back that left the app would exit
    /// the app on a swipe meant for the drawer.
    #[gpui::test]
    fn back_keystroke_at_the_root_keeps_the_app_in_the_foreground(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        app.read_with(cx, |app, _| {
            assert!(app.back_stack.is_empty(), "the session page is the root");
            assert!(!app.drawer_open, "the sessions drawer starts closed");
        });

        cx.simulate_keystrokes("back");
        app.read_with(cx, |app, _| {
            assert_eq!(app.mode, RootMode::Workspace);
            assert!(app.overlay.is_none());
            assert!(app.back_stack.is_empty());
            assert!(!app.drawer_open, "a root back must not move the drawer");
        });
    }

