    /// The dot is the whole reading of a runtime's state on the first screen,
    /// so each answer owns a color and words for the row's accessible name.
    #[test]
    fn every_reachability_answer_reads_as_its_own_state() {
        let states = [
            HostReachability::Probing,
            HostReachability::Online,
            HostReachability::Offline,
        ];
        for state in states {
            assert!(!state.label().is_empty(), "{state:?}");
        }
        assert_ne!(
            HostReachability::Online.label(),
            HostReachability::Offline.label()
        );
        assert_ne!(
            HostReachability::Online.dot_color(),
            HostReachability::Offline.dot_color()
        );
        assert_ne!(
            HostReachability::Online.dot_color(),
            HostReachability::Probing.dot_color()
        );
    }

    #[test]
    fn pairing_entry_routing_distinguishes_links_from_bare_codes() {
        for link in [
            "vibex://open/direct#/pair/encoded-offer",
            "vibex://pair#/code/eyJzY2hlbWE",
            "#/pair/encoded-offer",
            "  #/code/eyJzY2hlbWE  ",
        ] {
            assert!(is_pairing_link_entry(link), "{link} is a complete link");
        }
        // A bare code is the only shape that needs the server address typed
        // separately, which is what decides whether that field is shown.
        for code in ["482913", "4829 13", ""] {
            assert!(!is_pairing_link_entry(code), "{code} needs an address");
        }
    }

    #[test]
    fn pairing_failure_copy_names_the_recovery_step() {
        let expired = describe_pairing_error(BackendError::failed(
            "remote_pairing_code_expired",
            "pairing claim rejected",
        ));
        assert_eq!(
            expired.message,
            pairing_error_copy("remote_pairing_code_expired").expect("mapped")
        );
        // An unmapped failure keeps the transport's own message rather than
        // being replaced by a guess.
        let unmapped = describe_pairing_error(BackendError::failed(
            "remote_transport_unreachable",
            "no route to host",
        ));
        assert_eq!(unmapped.message, "no route to host");
    }

    #[gpui::test]
    fn pairing_page_renders_each_fallback_expanded(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = add_rooted_window_view(cx, |window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();

        // The denied-permission state is the one that used to leave the user
        // with an explanation and no way out, so it is worth painting.
        app.update(cx, |app, cx| {
            app.pairing_panel = PairingPanel::Nearby;
            app.nearby_pairing_state = NearbyPairingState::PermissionDenied;
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        // A failure raised while the manual panel is open is announced on the
        // toast layer. The panel keeps its own layout whatever the failure was:
        // the field the user is filling in is not where the answer belongs.
        app.update(cx, |app, cx| {
            app.pairing_panel = PairingPanel::Manual;
            app.fail(BackendError::failed(
                "remote_pairing_code_expired",
                "pairing claim rejected",
            ));
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(hint_is_shown(cx, Tone::Error));
    }

    /// The first screen leads with the runtimes the phone already knows, as
    /// full-width rows that scroll once they stop fitting. A real paint is the
    /// only thing between a layout mistake in that list and a blank first
    /// screen.
    #[gpui::test]
    fn pairing_page_paints_the_saved_runtime_list(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();

        // Enough runtimes to overflow whatever screen the test runs on, so the
        // list is exercised as a scrollable list rather than as a short stack.
        let bundles = (0..20)
            .map(|index| host_bundle(&format!("runtime-{index}"), &format!("studio-{index}")))
            .collect::<Vec<_>>();
        app.update(cx, |app, cx| {
            app.active_host_id = Some(bundles[0].host_id().to_string());
            app.known_hosts = bundles
                .iter()
                .map(|bundle| MobileHostEntry::from_bundle(bundle, RemoteServerKind::Desktop))
                .collect();
            // One of each answer, so the row draws the dot and the spinner
            // branches this page can show.
            for (index, host) in app.known_hosts.iter().enumerate() {
                let reachability = match index % 3 {
                    0 => HostReachability::Online,
                    1 => HostReachability::Offline,
                    _ => HostReachability::Probing,
                };
                app.host_reachability.insert(host.id.clone(), reachability);
            }
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        // The rows take the width of the page's column rather than sitting in a
        // clump against its left edge, and the list stops at its share of the
        // page and scrolls instead of growing the page.
        let list = cx
            .debug_bounds("pairing-runtimes")
            .expect("the runtime list should be laid out");
        assert_eq!(
            list.size.width,
            px(theme::CARD_WIDTH),
            "a runtime row should span the column: {:?}",
            list.size
        );
        let cap = cx.update(|window, _| pairing_runtimes_max_height(window, true));
        assert!(
            list.size.height <= cap,
            "the list should stop at its share of the page: {:?} vs {cap:?}",
            list.size
        );
        let max_offset = app.read_with(cx, |app, _| app.pairing_runtimes_scroll.max_offset());
        assert!(
            max_offset.y > px(0.0),
            "the list should overflow downwards: {max_offset:?}"
        );
        assert_eq!(
            max_offset.x,
            px(0.0),
            "the list itself never scrolls sideways"
        );

        // The three ways to add a runtime sit on one row at the foot of the
        // page, so the row is a single touch target tall.
        let actions = cx
            .debug_bounds("pairing-actions")
            .expect("the action row should be laid out");
        assert!(
            actions.size.height < px(2.0 * theme::TOUCH_TARGET),
            "the three entries should share one row: {:?}",
            actions.size
        );

        cx.simulate_event(ScrollWheelEvent {
            position: point(
                list.origin.x + list.size.width / 2.0,
                list.origin.y + list.size.height / 2.0,
            ),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-120.0))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Moved,
        });
        cx.run_until_parked();
        assert!(
            app.read_with(cx, |app, _| app.pairing_runtimes_scroll.offset().y) < px(0.0),
            "a pan down the list should scroll it"
        );

        // A fallback opens as a sheet over the page, so the entries stay exactly
        // where the finger left them — opening one used to reflow the row.
        app.update(cx, |app, cx| {
            app.pairing_panel = PairingPanel::Nearby;
            app.nearby_pairing_state = NearbyPairingState::Discovering;
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("pairing-sheet").is_some(),
            "the find sheet should be laid out"
        );
        assert_eq!(
            cx.debug_bounds("pairing-actions").expect("the row stays"),
            actions,
            "opening a sheet must not move the bottom row"
        );
        assert_eq!(
            cx.debug_bounds("pairing-runtimes").expect("the list stays"),
            list,
            "opening a sheet must not move the runtime list"
        );

        // A long result list grows into the page only up to the sheet's cap,
        // and then scrolls inside it: the sheet never swallows the whole page.
        app.update(cx, |app, cx| {
            app.nearby_candidates = (0..20)
                .map(|index| {
                    (
                        format!("candidate-{index}"),
                        crate::discovery::LanDiscoveryCandidate {
                            advertisement_id: format!("advertisement-{index}"),
                            service_instance: format!("instance-{index}"),
                            display_name: format!("studio-{index}"),
                            origin: "studio.local".to_string(),
                            mode: crate::discovery::LanDiscoveryMode::ZeroConfig,
                            server_id: None,
                            server_identity_public_key: None,
                            interface_scope: String::new(),
                        },
                    )
                })
                .collect();
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        let sheet = cx
            .debug_bounds("pairing-sheet")
            .expect("the find sheet should stay laid out");
        let cap = cx.update(|window, _| bottom_sheet_max_height(window));
        assert!(
            sheet.size.height <= cap,
            "the sheet should stop at its cap: {:?} vs {cap:?}",
            sheet.size
        );
        assert!(
            app.update(cx, |app, _| app
                .sheet
                .body_scroll(SheetKey::PairingFallback)
                .max_offset()
                .y)
                > px(0.0),
            "a long result list should scroll inside the sheet"
        );

        app.update(cx, |app, cx| {
            app.nearby_candidates.clear();
            app.dismiss_pairing_panel(cx);
        });
        // The panel is still on screen while it falls; it leaves when it lands.
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("pairing-sheet").is_some(),
            "a closing sheet is still on screen while it falls"
        );
        settle_sheet(&app, cx);
        assert!(
            cx.debug_bounds("pairing-sheet").is_none(),
            "dismissing should take the sheet away"
        );

        // The same page with the runtime list empty is what a fresh install
        // paints: no rows, no empty-state copy, and the three entries stacked
        // in the middle of the page instead of hanging off the bottom edge.
        app.update(cx, |app, cx| {
            app.known_hosts.clear();
            app.active_host_id = None;
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("pairing-runtimes").is_none(),
            "an empty runtime list should render no rows"
        );
        assert!(
            cx.debug_bounds("pairing-actions").is_none(),
            "the bottom row belongs to the page that has runtimes to show"
        );
        let region = cx
            .debug_bounds("pairing-entry-region")
            .expect("the entry region should be laid out");
        let stack = cx
            .debug_bounds("pairing-actions-stack")
            .expect("the stacked entries should be laid out");
        assert!(
            stack.size.height >= px(3.0 * theme::TOUCH_TARGET),
            "the three entries should stack into three rows: {:?}",
            stack.size
        );
        let above = stack.origin.y - region.origin.y;
        let below = region.origin.y + region.size.height - (stack.origin.y + stack.size.height);
        assert!(
            above - below < px(1.0) && below - above < px(1.0),
            "the stacked entries should sit in the middle: above={above:?} below={below:?}"
        );

        // The stacked entries keep their place under the "link" sheet too.
        app.update(cx, |app, cx| {
            app.pairing_panel = PairingPanel::Manual;
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("pairing-sheet").is_some(),
            "the link sheet should be laid out"
        );
        assert_eq!(
            cx.debug_bounds("pairing-actions-stack")
                .expect("the stack stays"),
            stack,
            "opening a sheet must not move the stacked entries"
        );
    }

    /// The runtime switcher is the pairing page opened over a live connection:
    /// the saved runtimes, the three ways on pinned to the foot of the page, and
    /// no product wordmark — the wordmark belongs to the first screen the app
    /// starts on.
    #[gpui::test]
    fn the_runtime_switcher_lists_runtimes_without_the_wordmark(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let (app, cx) = cx.add_window_view(|window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();

        // A phone that has not connected yet starts on the first screen with the
        // runtimes it already knows, and that page names the product.
        app.update(cx, |app, cx| {
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert_eq!(app.read_with(cx, |app, _| app.mode), RootMode::Pairing);
        assert!(
            cx.debug_bounds("pairing-brand").is_some(),
            "the first screen should keep the wordmark"
        );
        assert!(cx.debug_bounds("pairing-runtimes").is_some());

        // Switching runtimes opens the same page over the running connection:
        // the rows and the three entries stay, the wordmark goes.
        app.update(cx, |app, cx| {
            app.mode = RootMode::Workspace;
            app.backend = Some(backend.clone());
            app.controller = Some(AgentWorkflowController::new(
                backend.clone(),
                backend.capability_snapshot().agent,
            ));
            cx.notify();
        });
        cx.update(|window, cx| {
            app.update(cx, |app, cx| app.open_pairing(&noop_mouse_up(), window, cx));
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Pairing)
        );
        assert!(
            cx.debug_bounds("pairing-runtimes").is_some(),
            "the switcher should list the saved runtimes"
        );
        assert!(
            cx.debug_bounds("pairing-brand").is_none(),
            "the switcher should carry no wordmark"
        );
        let actions = cx
            .debug_bounds("pairing-actions")
            .expect("the three entries should stay pinned to the foot of the page");
        let below = cx.update(|window, _| {
            f32::from(window.viewport_size().height)
                - f32::from(actions.origin.y + actions.size.height)
        });
        assert!(
            below.abs() < 1.0,
            "the three entries should sit at the foot of the page, not {below} below it"
        );
        // The rows start under the back button: the switcher has no wordmark
        // line to hold empty above them.
        let back = cx
            .debug_bounds("pairing-back")
            .expect("the switcher keeps a way back");
        let list = cx
            .debug_bounds("pairing-runtimes")
            .expect("the switcher lists the saved runtimes");
        let gap = f32::from(list.origin.y) - f32::from(back.origin.y + back.size.height);
        assert!(
            (0.0..=f32::from(px(theme::SPACING_LG))).contains(&gap),
            "the list should start one small gap under the back button, not {gap} below it"
        );
    }

    /// The runtime switcher and Settings are pages opened on top of the one the
    /// phone is on, so a rightward finger swipe leaves them the way the system
    /// back event does — and only a deliberate, clearly horizontal pull does.
    #[gpui::test]
    fn a_rightward_swipe_leaves_an_overlay_page(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let mut bundle = host_bundle("runtime-a", "studio");
        bundle.route = Some(crate::pairing::MobileRemoteRouteBundle {
            local_network: None,
            direct_candidates: vec![bundle.record.server_url.clone()],
            relay: None,
        });
        let backend = bundle.backend().expect("valid saved runtime");
        let (app, cx) = cx.add_window_view(|window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.backend = Some(backend.clone());
            app.controller = Some(AgentWorkflowController::new(
                backend.clone(),
                backend.capability_snapshot().agent,
            ));
            app.remember_host(&bundle, RemoteServerKind::Desktop);
            app
        });
        cx.run_until_parked();

        // A short pull is not the gesture: without an interactive drag, only a
        // deliberate rightward swipe may leave the page.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| app.open_pairing(&noop_mouse_up(), window, cx));
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        drag_finger(cx, theme::OVERLAY_BACK_SWIPE_TRAVEL - 8.0, 0.0);
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Pairing),
            "a short pull should keep the switcher"
        );

        // The switcher itself follows a swipe that does clear the travel.
        drag_finger(cx, theme::OVERLAY_BACK_SWIPE_TRAVEL, 0.0);
        assert!(
            app.read_with(cx, |app, _| app.overlay.is_none()),
            "the swipe should leave the runtime switcher"
        );
        assert_eq!(
            app.read_with(cx, |app, _| app.mode),
            RootMode::Workspace,
            "leaving the switcher returns to the session page"
        );

        // Settings is a page in the same position, so the same swipe leaves it.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.open_settings(&noop_mouse_up(), window, cx)
            });
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Settings)
        );
        drag_finger(cx, theme::OVERLAY_BACK_SWIPE_TRAVEL, 0.0);
        assert!(
            app.read_with(cx, |app, _| app.overlay.is_none()),
            "the swipe should leave Settings"
        );

        // A pan that is mostly vertical belongs to the list under the finger,
        // not to the page.
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.open_settings(&noop_mouse_up(), window, cx)
            });
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        drag_finger(cx, theme::DRAWER_DRAG_THRESHOLD * 2.0, 96.0);
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Settings),
            "a vertical pan should keep the page it scrolls"
        );
    }

    /// A pairing card is the phone's whole runtime surface on this page, so it
    /// carries the runtime's own state and the way into its actions — including
    /// removing it.
    #[gpui::test]
    fn pairing_cards_show_state_and_remove_their_runtime(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();

        let bundles = (0..2)
            .map(|index| host_bundle(&format!("runtime-{index}"), &format!("studio-{index}")))
            .collect::<Vec<_>>();
        let active_id = bundles[0].host_id().to_string();
        let inactive_id = bundles[1].host_id().to_string();
        app.update(cx, |app, cx| {
            app.active_host_id = Some(active_id.clone());
            app.known_hosts = bundles
                .iter()
                .map(|bundle| MobileHostEntry::from_bundle(bundle, RemoteServerKind::Desktop))
                .collect();
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        let list = cx.debug_bounds("pairing-runtimes").expect("the list");

        // A card's own menu opens the runtime sheet the rest of the app uses,
        // and the list behind it keeps its place.
        cx.update(|window, cx| {
            let inactive_id = inactive_id.clone();
            app.update(cx, |app, cx| app.open_host_actions(inactive_id, window, cx));
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("mobile-runtime-actions-sheet").is_some(),
            "the runtime actions should paint over the pairing page"
        );
        assert_eq!(
            cx.debug_bounds("pairing-runtimes").expect("the list stays"),
            list,
            "a runtime's own sheet must not move the list"
        );

        // Back closes that sheet first: it is the topmost surface on the page.
        cx.simulate_keystrokes("back");
        assert!(app.read_with(cx, |app, _| app.overlay.is_none()));
        assert_eq!(
            app.read_with(cx, |app, _| app.known_hosts.len()),
            2,
            "back must not touch the runtimes"
        );

        // Removing a runtime the phone is not on leaves the page where it is,
        // with the card gone and nothing left pointing at it.
        cx.update(|window, cx| {
            let inactive_id = inactive_id.clone();
            app.update(cx, |app, cx| app.remove_host(inactive_id, window, cx));
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert_eq!(app.read_with(cx, |app, _| app.known_hosts.len()), 1);
        assert!(app.read_with(cx, |app, _| app.overlay.is_none()));
        assert!(app.read_with(cx, |app, _| matches!(app.mode, RootMode::Pairing)));
        assert!(
            cx.debug_bounds("mobile-runtime-actions-sheet").is_none(),
            "the removed runtime's sheet should be gone"
        );

        // Removing the last one, which is also the runtime the phone is on,
        // hands the page back to the stacked entries.
        cx.update(|window, cx| {
            let active_id = active_id.clone();
            app.update(cx, |app, cx| app.remove_host(active_id, window, cx));
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(app.read_with(cx, |app, _| app.known_hosts.is_empty()));
        assert!(app.read_with(cx, |app, _| app.overlay.is_none()));
        assert!(app.read_with(cx, |app, _| matches!(app.mode, RootMode::Pairing)));
        assert!(
            cx.debug_bounds("pairing-runtimes").is_none(),
            "the list goes with the last runtime"
        );
        assert!(
            cx.debug_bounds("pairing-actions-stack").is_some(),
            "the entries take the page again"
        );
    }

    /// One renderer out of `app.rs`, from its signature to the item after it,
    /// so a test can assert on the page a helper builds.
    fn renderer_source<'a>(source: &'a str, name: &str) -> &'a str {
        let (_, tail) = source
            .split_once(&format!("    fn {name}("))
            .unwrap_or_else(|| panic!("{name} should remain inspectable"));
        let end = tail
            .find("\n    /// ")
            .or_else(|| tail.find("\n    fn "))
            .unwrap_or(tail.len());
        &tail[..end]
    }

    /// The pairing page is the product wordmark plus the runtimes this phone
    /// already paired — but only while it is the first screen. A title above
    /// the wordmark, or rows that wrap instead of scrolling, would both undo
    /// what the page is for.
    #[test]
    fn the_pairing_page_keeps_the_wordmark_on_the_first_screen_alone() {
        let source = include_str!("app.rs");
        let page = renderer_source(source, "render_pairing");
        for call in [
            "self.render_pairing_brand()",
            "self.render_pairing_runtimes(runtimes_max_height, cx)",
            "self.render_pairing_actions(scan_busy, scan_enabled, cx)",
            "self.render_pairing_stack(",
            "self.render_pairing_sheet(presentation, frame.pairing_scroll, cx)",
            // The cards here are a runtime list, so a runtime's own surfaces
            // belong to this page too.
            "self.render_mobile_overlay(overlay, sheets.clone(), window, cx)",
        ] {
            assert!(page.contains(call), "the page should still render {call}");
        }
        // The row is for a page that has runtimes; the stack replaces it when
        // there are none, and the empty page carries no copy about it.
        assert!(page.contains(".when(saved_runtimes, |page|"));
        assert!(!page.contains("No runtimes yet") && !page.contains("Add a device"));
        // The wordmark belongs to the first screen; the runtime switcher is the
        // same page opened over a live connection, so it starts with the rows,
        // gives the band the wordmark held to the list, and starts them one gap
        // under the back button instead of at the wordmark's baseline.
        assert!(page.contains("let first_screen = !self.is_pairing_overlay_open();"));
        assert!(page.contains(".when(first_screen, |page|"));
        assert!(page.contains("pairing_runtimes_max_height(window, first_screen)"));
        assert!(page.contains("PAIRING_SWITCHER_TOP_PAD"));

        // The mark supplies the capital "V" and the label completes the name,
        // and the lockup sits in the middle of the page rather than at its
        // left edge.
        let brand = renderer_source(source, "render_pairing_brand");
        assert!(brand.contains("icons/vibex-mark.svg"));
        assert!(brand.contains("\"ibex\""));
        assert!(brand.contains(".justify_center()"));
        assert!(!brand.contains("brand/logo.svg"));
        // The mark is sized from the label's rendered size, not from a pixel
        // box of its own.
        assert!(brand.contains("theme::wordmark_mark("));

        // Every saved runtime is reachable, and the row scrolls sideways once
        // they stop fitting.
        let rows = renderer_source(source, "render_pairing_runtimes");
        assert!(rows.contains("self.known_hosts"));
        assert!(rows.contains(".overflow_y_scroll()"));
        assert!(rows.contains(".max_h(max_height)"));

        // A row is a runtime's whole surface on this page: whether it is up as
        // the leading dot, what it is as a glyph, and the way into its own
        // actions — removing it included. The active runtime reports its live
        // connection; the others report reachability.
        let card = renderer_source(source, "render_pairing_runtime_card");
        assert!(card.contains(".host_reachability"));
        assert!(card.contains("HostReachability::Probing"));
        assert!(card.contains("sidebar_running_indicator("));
        assert!(card.contains("sidebar_status_dot("));
        assert!(card.contains("host_kind_icon(host.server_kind)"));
        assert!(card.contains("self.active_host_status()"));
        for marker in [
            "icons/ellipsis-vertical.svg",
            "open_host_actions(",
            ".stop_propagation()",
        ] {
            assert!(card.contains(marker), "the card should keep {marker}");
        }
        // The words for the kind and the state survive only in the row's
        // accessible name; nothing on the row renders them.
        assert_eq!(card.matches("host_kind_label(host.server_kind)").count(), 1);
        assert!(card.contains(".aria_label(format!("));
        assert!(!card.contains("text_size(px(theme::FONT_MICRO))"));

        // Both layouts offer the same three entries, and the stack keeps them
        // at their touch-target height instead of flexing them tall.
        for layout in ["render_pairing_actions", "render_pairing_stack"] {
            let source = renderer_source(source, layout);
            assert!(source.contains("self.render_pairing_scan_action("));
            for entry in ["pairing-nearby-toggle", "pairing-manual-toggle"] {
                assert!(source.contains(entry), "{layout} should keep {entry}");
            }
        }
        assert!(
            renderer_source(source, "render_pairing_stack")
                .matches(".flex_none()")
                .count()
                >= 3
        );
        assert!(renderer_source(source, "render_pairing_scan_action").contains("scan-pairing-qr"));

        // The sheet is a bottom sheet: the scrim, the panel's rise and the
        // grabber belong to the shared shell, so what is left here is its own
        // content, its body's scroll, and the way out.
        let sheet = renderer_source(source, "render_pairing_sheet");
        assert!(sheet.contains("bottom_sheet_shell(\"pairing-sheet\", presentation)"));
        assert!(sheet.contains(".on_dismiss("));
        assert!(sheet.contains(".on_pan("));
        assert!(sheet.contains("track_scroll(&body_scroll)"));
        for panel in ["PairingPanel::Nearby", "PairingPanel::Manual"] {
            assert!(sheet.contains(panel), "the sheet should serve {panel}");
        }
    }

    /// The connecting page wears the same lockup as every other brand moment,
    /// and it is the launch page's sweep that runs through it while the phone
    /// is actually connecting.
    ///
    /// The old mark was the bare `brand/logo.svg` glyph: no word, and no
    /// indication that the screen was working rather than stuck. The sweep is
    /// the desktop startup page's own effect, so the two products open the same
    /// way, but it belongs to the working state only — the failure state is a
    /// page the reader acts on.
    #[test]
    fn the_connecting_page_sweeps_its_wordmark_only_while_it_works() {
        let source = include_str!("app.rs");
        let page = renderer_source(source, "render_connecting");
        // The wordmark replaces the old glyph lockup entirely.
        assert!(!page.contains("brand/logo.svg"));
        assert!(page.contains("self.render_connecting_brand(self.operation_busy)"));

        let brand = renderer_source(source, "render_connecting_brand");
        assert!(brand.contains("icons/vibex-mark.svg"));
        assert!(brand.contains("\"ibex\""));
        assert!(brand.contains("theme::wordmark_mark("));
        assert!(brand.contains(".text_size(font)"));
        assert!(brand.contains("CONNECTING_WORDMARK_SHIMMER_DURATION"));
        assert!(brand.contains("with_max_fps(CONNECTING_WORDMARK_SHIMMER_MAX_FPS)"));
        assert!(brand.contains(".repeat()"));
        // Motion is parked for the reader who asked for less of it, and for an
        // app with no frame to spend.
        assert!(brand.contains("theme::reduce_motion()"));
        assert!(brand.contains("crate::lifecycle::is_backgrounded()"));

        // The sweep is the desktop's pace, not a faster phone-only variant.
        assert_eq!(
            CONNECTING_WORDMARK_SHIMMER_DURATION,
            Duration::from_secs(12)
        );
        assert_eq!(CONNECTING_WORDMARK_SCAN_PASSES, 10.0);
        assert_eq!(CONNECTING_WORDMARK_SCAN_SPREAD, 0.42);

        // The lockup is the pairing page's size, not a splash-poster step over
        // it: on a phone an oversized wordmark read as a wasted screen rather
        // than as the product's name.
        assert_eq!(CONNECTING_WORDMARK_FONT, theme::FONT_WORDMARK);
        // The brand sits on the ladder's own wordmark step; it may not outgrow
        // it into a splash-poster size.
        const {
            assert!(CONNECTING_WORDMARK_FONT <= theme::FONT_WORDMARK);
        }
        // Parked is the foreground, exactly as the desktop draws its startup
        // wordmark with no sweep. The muted base is the *start* of the moving
        // gradient only; using it while still painted the lockup as disabled.
        assert!(brand.contains("scan_position.map_or(glow,"));
        assert!(!brand.contains("scan_position.map_or(base,"));
    }

    /// The root paints its own text in the foreground, so a page that does not
    /// choose a colour inherits body text rather than a dimmed step.
    ///
    /// The desktop shell does exactly this (`cx.theme().foreground`) and lets
    /// each row descend the ladder on purpose. The phone inherited its secondary
    /// shade instead, which turned every page that set no colour for itself into
    /// a screen of disabled-looking copy.
    #[test]
    fn the_root_inherits_the_foreground_not_a_dimmed_step() {
        let source = include_str!("app.rs");
        let root = source
            .split_once("\"mobile-app-swipe-back\"")
            .map(|(_, tail)| tail)
            .expect("the app shell wrapper should stay inspectable");
        let root = root
            .split(".child(match visible_mode")
            .next()
            .unwrap_or(root);
        assert!(
            root.contains(".text_color(theme::text_primary())"),
            "the shell should hand pages the foreground"
        );
        assert!(
            !root.contains(".text_color(theme::text_secondary())"),
            "inheriting a faded shade dims every page that does not set its own"
        );
    }

    /// Every action on the unavailable-connection page leads with a glyph, so
    /// the three choices read at a glance instead of as three bare lines of
    /// text.
    ///
    /// Each glyph is a different idea — the failure turns back, the link is cut,
    /// the runtime changes — and each is the icon the app already uses for that
    /// action elsewhere, so the screen does not invent a second vocabulary.
    #[test]
    fn the_unavailable_page_gives_each_action_its_glyph() {
        let source = include_str!("app.rs");
        let page = renderer_source(source, "render_connecting");
        let failure = page
            .split_once(".when(!self.operation_busy, |panel|")
            .map(|(_, tail)| tail)
            .expect("the unavailable page should keep its failure branch");

        for (id, icon) in [
            ("retry-desktop-connection", "icons/rotate-ccw.svg"),
            ("disconnect-unavailable-desktop", "icons/plug-zap.svg"),
            (
                "switch-host-while-connecting",
                "icons/chevrons-right-left.svg",
            ),
        ] {
            let row = failure
                .split_once(id)
                .map(|(_, tail)| tail)
                .unwrap_or_else(|| panic!("{id} should still exist"));
            // The row ends at the next control, not at the page's end.
            let row = row.split(".id(\"").next().unwrap_or(row);
            assert!(
                row.contains(icon),
                "{id} should lead with {icon} instead of a bare label"
            );
            assert!(
                row.contains(".gap(px(theme::SPACING_SM))"),
                "{id} should space its glyph from its label"
            );
        }
    }

    /// The sweep's colour walks from the idle tone to the foreground, and the
    /// scan position covers the whole lockup without ever resting on it.
    #[test]
    fn the_connecting_sweep_moves_and_never_washes_out_the_mark() {
        let base = gpui::hsla(0.0, 0.0, 0.45, 1.0);
        let glow = gpui::hsla(0.0, 0.0, 0.98, 1.0);

        // Dead on the scan line the glyph takes the glow; far from it, the
        // idle tone, unchanged.
        assert_eq!(
            connecting_wordmark_color(base, glow, 0.5, 0.5),
            glow,
            "the scan line is the highlight"
        );
        assert_eq!(
            connecting_wordmark_color(base, glow, 0.0, 1.0),
            base,
            "a glyph the light left behind keeps the idle tone"
        );

        // Halfway out of the band the value is between the two, so the sweep
        // reads as light rather than as a hard edge crossing the letters.
        let edge = connecting_wordmark_color(base, glow, 0.5, 0.5 + 0.21);
        assert!(edge.l > base.l && edge.l < glow.l);

        // One loop is the desktop's ten passes, each starting left of the
        // lockup and ending past its right edge.
        let mut previous = connecting_wordmark_scan_position(0.0);
        assert!(previous < 0.0, "the light enters from the left");
        for step in 1..=200 {
            let position = connecting_wordmark_scan_position(step as f32 / 200.0);
            assert!(position.is_finite());
            assert!(
                (-0.35..=1.35).contains(&position),
                "the sweep stays on the lockup, got {position}"
            );
            previous = position;
        }
        assert!(previous <= 1.35);
        // A hundredth of the loop moves the light a visible distance: it is a
        // sweep, not a hue that slowly drifts.
        let moved = (connecting_wordmark_scan_position(0.20)
            - connecting_wordmark_scan_position(0.19))
        .abs();
        assert!(moved > 0.05, "the light should travel, moved {moved}");
    }

    /// Some nearby runtimes for a fallback sheet to list.
    fn nearby_candidates(
        count: usize,
    ) -> BTreeMap<String, crate::discovery::LanDiscoveryCandidate> {
        (0..count)
            .map(|index| {
                (
                    format!("candidate-{index}"),
                    crate::discovery::LanDiscoveryCandidate {
                        advertisement_id: format!("advertisement-{index}"),
                        service_instance: format!("instance-{index}"),
                        display_name: format!("studio-{index}"),
                        origin: "studio.local".to_string(),
                        mode: crate::discovery::LanDiscoveryMode::ZeroConfig,
                        server_id: None,
                        server_identity_public_key: None,
                        interface_scope: String::new(),
                    },
                )
            })
            .collect()
    }

    /// A finger that drags up anywhere on a sheet pulls it open: the panel grows
    /// toward the height a sheet is allowed, and stops short of the whole screen
    /// however far the pull goes.
    #[gpui::test]
    fn a_sheet_pulled_open_grows_short_of_the_whole_screen(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();
        app.update(cx, |app, cx| {
            app.pairing_panel = PairingPanel::Nearby;
            app.nearby_pairing_state = NearbyPairingState::Discovering;
            // More results than the sheet can show, so there is height to take.
            app.nearby_candidates = nearby_candidates(20);
            cx.notify();
        });
        settle_rise(&app, cx);
        let resting = cx
            .debug_bounds("pairing-sheet")
            .expect("the find sheet should be laid out");
        let (viewport, expanded) = cx.update(|window, _| {
            (
                window.viewport_size().height,
                crate::bottom_sheet::sheet_size(window).expanded,
            )
        });
        assert!(
            resting.size.height < px(expanded),
            "there should be height left to take: {:?} against {expanded}",
            resting.size
        );

        // The finger lands a little under the panel's top edge, which is the
        // worst case a listener that travelled with the panel could survive.
        let touch = point(resting.center().x, resting.origin.y + px(24.0));
        for (phase, dy) in [(TouchPhase::Started, -40.0), (TouchPhase::Moved, -400.0)] {
            cx.simulate_event(ScrollWheelEvent {
                position: touch,
                delta: ScrollDelta::Pixels(point(px(0.0), px(dy))),
                modifiers: Default::default(),
                touch_phase: phase,
            });
            cx.update(|window, cx| {
                let _ = window.draw(cx);
            });
        }
        let opened = cx
            .debug_bounds("pairing-sheet")
            .expect("a pulled sheet stays on screen");
        assert!(
            opened.size.height > resting.size.height,
            "the sheet should have grown: {opened:?} against {resting:?}"
        );
        assert!(
            opened.size.height <= px(expanded) + px(1.0),
            "the sheet should stop at the height it is allowed: {opened:?} vs {expanded}"
        );
        assert!(
            opened.size.height < px(f32::from(viewport)),
            "no sheet fills the screen: {opened:?} of {viewport:?}"
        );
        assert!(
            opened.origin.y < resting.origin.y,
            "it grows upward, away from the foot of the page"
        );
        assert!(
            opened.origin.y + opened.size.height
                >= resting.origin.y + resting.size.height - px(1.0),
            "and its foot stays where it was"
        );
    }

    /// A finger that drags down inside a sheet pulls the panel with it for as
    /// long as the drag lasts.
    ///
    /// The gesture is watched from the scrim, which covers the page and never
    /// moves. Watched from the panel instead, the listener travelled away from
    /// the contact point with the panel, so the drag died after a few pixels —
    /// the higher up the panel the finger landed, the sooner it stopped.
    #[gpui::test]
    fn a_dragged_sheet_follows_the_finger_all_the_way_down(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();
        app.update(cx, |app, cx| {
            app.sidebar_row_menu = Some(SidebarRowMenu {
                row: SidebarRow {
                    item: SidebarOrganizationItem::Project("project-1".to_string()),
                    kind: SidebarRowKind::Project,
                    depth: 0,
                    indent: 0.0,
                    label: "Vibex".to_string(),
                    project_id: Some("project-1".to_string()),
                    workspace_id: None,
                    detail: None,
                    child_count: 2,
                    lifecycle: None,
                    collapsed: false,
                    pinned: false,
                    selected: false,
                    state: None,
                    session_id: None,
                    unread: false,
                    auto_continue: false,
                    auto_continue_paused: false,
                    delegated_child: false,
                },
            });
            cx.notify();
        });
        settle_rise(&app, cx);
        let sheet = cx
            .debug_bounds("mobile-sidebar-row-menu-sheet")
            .expect("the row's actions should be laid out");

        // The contact point stays where it is while the panel travels under it,
        // which is what a phone reports, and it sits at the panel's very top —
        // the worst case for a listener that moved with the panel.
        let touch = point(sheet.center().x, sheet.origin.y + px(2.0));
        for (phase, dy) in [
            (TouchPhase::Started, 20.0),
            (TouchPhase::Moved, 40.0),
            (TouchPhase::Moved, 40.0),
        ] {
            cx.simulate_event(ScrollWheelEvent {
                position: touch,
                delta: ScrollDelta::Pixels(point(px(0.0), px(dy))),
                modifiers: Default::default(),
                touch_phase: phase,
            });
            cx.update(|window, cx| {
                let _ = window.draw(cx);
            });
        }
        let pulled = cx
            .debug_bounds("mobile-sidebar-row-menu-sheet")
            .expect("a dragged sheet stays on screen");
        assert!(
            pulled.origin.y >= sheet.origin.y + px(90.0),
            "the panel should have followed the whole drag: {pulled:?} against {sheet:?}"
        );

        // Letting go that far takes the sheet with it.
        cx.simulate_event(ScrollWheelEvent {
            position: touch,
            delta: ScrollDelta::Pixels(point(px(0.0), px(0.0))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Ended,
        });
        settle_sheet(&app, cx);
        assert!(
            app.read_with(cx, |app, _| app.sidebar_row_menu.is_none()),
            "a pull this long dismisses the sheet"
        );
    }

    /// A finger dragging a sheet's own horizontal list is not pulling the
    /// sheet, nor leaving the page the sheet is drawn over.
    ///
    /// The Agent strip in the runtime sheet is that list: moving it back to the
    /// first Agent takes the finger sideways, and the runtime sheet must still
    /// be on screen — at the height it was — when the finger lifts.
    #[gpui::test]
    fn a_swipe_along_a_sheets_list_does_not_take_the_sheet(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app.runtime_options_open = true;
            app.runtime_options_target = RuntimeOptionsTarget::ActiveSession;
            // The sheet is a page in the back stack, so a rightward swipe over
            // it is the page's own way out — the gesture this test is keeping
            // the strip's drag out of.
            app.push_back_screen(BackScreen::RuntimeOptions);
            app
        });
        settle_rise(&app, cx);
        let sheet = cx
            .debug_bounds("mobile-runtime-options")
            .expect("the Agent settings should be laid out");
        let band = app
            .read_with(cx, |app, _| app.runtime_agent_strip_frame.get())
            .expect("the Agent strip should have recorded the band it was painted in");

        // The finger crosses the strip faster than it descends, the way a thumb
        // swiping back to the first logo does.
        let touch = point(sheet.center().x, px((band.0 + band.1) / 2.0));
        for (phase, dx, dy) in [
            (TouchPhase::Started, 18.0, 3.0),
            (TouchPhase::Moved, 90.0, 10.0),
            (TouchPhase::Moved, 90.0, 10.0),
        ] {
            cx.simulate_event(ScrollWheelEvent {
                position: touch,
                delta: ScrollDelta::Pixels(point(px(dx), px(dy))),
                modifiers: Default::default(),
                touch_phase: phase,
            });
            cx.update(|window, cx| {
                let _ = window.draw(cx);
            });
        }
        let crossed = cx
            .debug_bounds("mobile-runtime-options")
            .expect("a swipe along a list leaves the sheet on screen");
        assert_eq!(
            crossed.origin.y, sheet.origin.y,
            "the panel must not have travelled under the finger"
        );

        cx.simulate_event(ScrollWheelEvent {
            position: touch,
            delta: ScrollDelta::Pixels(point(px(0.0), px(0.0))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Ended,
        });
        settle_sheet(&app, cx);
        assert!(
            app.read_with(cx, |app, _| app.runtime_options_open),
            "letting go of a sideways swipe leaves the sheet up"
        );
        assert!(
            cx.debug_bounds("mobile-runtime-options").is_some(),
            "and the panel is still drawn"
        );
    }

    /// The request an Agent parked on in [`app_with_a_parked_question`].
    const PARKED_QUESTION: &str = "request_mobile_parked";

    /// A workspace whose Agent has parked on a question, laid out with the panel
    /// at rest over the composer — the state every question-panel gesture starts
    /// from.
    ///
    /// The request reaches the controller the way a live one does: as a pending
    /// elicitation in the session's timeline.
    fn app_with_a_parked_question<'a>(
        cx: &'a mut TestAppContext,
        data_dir: &std::path::Path,
    ) -> (Entity<MobileApp>, &'a mut gpui::VisualTestContext) {
        cx.update(|cx| {
            gpui_component::init(cx);
            cx.set_reduce_motion(true);
        });
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.to_path_buf(), window, cx);
            let backend = vibex_backend::DisconnectedBackend::facade();
            let mut controller =
                AgentWorkflowController::new(backend.agent().clone(), backend.capabilities().agent);
            let session_id = VibexSessionId::parse("session_mobile_question").unwrap();
            let request = ElicitationRequest {
                id: RequestId::parse(PARKED_QUESTION).unwrap(),
                session_id: session_id.clone(),
                provider_request_id: None,
                tool_call_id: None,
                message: "Which state model should the rail use?".into(),
                title: None,
                description: None,
                fields: vec![ElicitationField {
                    id: "approach".into(),
                    title: "Approach".into(),
                    description: None,
                    required: true,
                    kind: ElicitationFieldKind::Text {
                        min_length: None,
                        max_length: None,
                        pattern: None,
                        format: None,
                        default: None,
                        options: vec![ElicitationOption {
                            value: "global".into(),
                            title: "Global state".into(),
                            description: None,
                        }],
                    },
                }],
                status: vibex_core::ElicitationRequestStatus::Pending,
                requested_at_ms: 1,
            };
            controller.state.selected_session_id = Some(session_id.clone());
            controller.state.timeline.replace_authoritative(
                session_id.clone(),
                vec![TimelineItem {
                    id: vibex_core::TimelineItemId::parse("timeline_mobile_question").unwrap(),
                    session_id,
                    sequence: 1,
                    timestamp_ms: 1,
                    source: TimelineSource::Agent,
                    kind: TimelineItemKind::ElicitationRequest,
                    correlation_id: None,
                    provider_correlation_id: None,
                    redaction_state: TimelineRedactionState::None,
                    execution_attribution: None,
                    payload_depth: vibex_core::TimelinePayloadDepth::Detail,
                    payload: TimelinePayload::ElicitationRequest(request),
                }],
            );
            app.controller = Some(controller);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();
        // The first frame is what opens the panel; the rest of the rise is then
        // run out so every gesture starts from the panel the reader sees.
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        settle_rise(&app, cx);
        (app, cx)
    }

    /// A finger that throws the question panel down the screen puts it away for
    /// good — the same thing a tap on the scrim means.
    ///
    /// The panel's own flag is the pending request, which the runtime owns, so
    /// the page has to remember the dismissal itself. Without that, the fall
    /// lands, the request is still waiting, and the panel rises straight back up
    /// under the finger that just threw it away.
    #[gpui::test]
    fn a_question_panel_thrown_down_stays_away(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = app_with_a_parked_question(cx, data_dir.path());
        let panel = cx
            .debug_bounds("mobile-agent-question")
            .expect("the parked question rises over the composer");

        // The finger lands on the scrim above the panel and drags further than
        // a dismissal asks for.
        let touch = point(panel.center().x, panel.origin.y - px(12.0));
        for (phase, dy) in [(TouchPhase::Started, 20.0), (TouchPhase::Moved, 140.0)] {
            cx.simulate_event(ScrollWheelEvent {
                position: touch,
                delta: ScrollDelta::Pixels(point(px(0.0), px(dy))),
                modifiers: Default::default(),
                touch_phase: phase,
            });
            cx.update(|window, cx| {
                let _ = window.draw(cx);
            });
        }
        cx.simulate_event(ScrollWheelEvent {
            position: touch,
            delta: ScrollDelta::Pixels(point(px(0.0), px(0.0))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Ended,
        });
        settle_sheet(&app, cx);
        assert!(
            !app.read_with(cx, |app, _| app.question_form_open()),
            "a pull past the dismissal distance puts the question away"
        );
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("mobile-agent-question").is_none(),
            "and the panel must not rise back up once its fall has landed"
        );

        // A dismissal is not a decline: the request is still waiting, and its
        // timeline row is the way back to the panel.
        app.update(cx, |app, cx| {
            app.reopen_question(PARKED_QUESTION.to_string(), cx);
        });
        settle_rise(&app, cx);
        assert!(
            cx.debug_bounds("mobile-agent-question").is_some(),
            "the row brings the same question back"
        );
    }

    /// A tap on the scrim means the same as a pull: the question is put away
    /// unanswered, the page behind the panel never sees the tap, and the panel
    /// stays down.
    #[gpui::test]
    fn a_tap_beside_the_question_puts_it_away(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = app_with_a_parked_question(cx, data_dir.path());
        let panel = cx
            .debug_bounds("mobile-agent-question")
            .expect("the parked question rises over the composer");

        cx.simulate_click(
            point(panel.center().x, panel.origin.y - px(12.0)),
            gpui::Modifiers::none(),
        );
        settle_sheet(&app, cx);
        assert!(
            !app.read_with(cx, |app, _| app.question_form_open()),
            "a tap on the scrim puts the question away"
        );
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(
            cx.debug_bounds("mobile-agent-question").is_none(),
            "and the panel stays down"
        );
    }

    /// The page behind an open question panel is not the reader's to touch.
    ///
    /// The capture that moves the drawer sits above the sheet's scrim, so a
    /// swipe across the open panel still reached it and switched screens under
    /// the question being answered. The page stands down while a panel is up,
    /// without stopping the pan: the sheet's own pull still gets it.
    #[gpui::test]
    fn an_open_question_panel_holds_the_page_still(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = app_with_a_parked_question(cx, data_dir.path());

        let position = point(px(120.0), px(120.0));
        for (phase, dx) in [(TouchPhase::Started, 24.0), (TouchPhase::Moved, 80.0)] {
            cx.simulate_event(ScrollWheelEvent {
                position,
                delta: ScrollDelta::Pixels(point(px(dx), px(0.0))),
                modifiers: Default::default(),
                touch_phase: phase,
            });
        }
        assert_eq!(
            app.read_with(cx, |app, _| app.drawer_offset),
            0.0,
            "a swipe over the open panel must not move the page behind it"
        );
        cx.simulate_event(ScrollWheelEvent {
            position,
            delta: ScrollDelta::Lines(point(0.0, 0.0)),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Ended,
        });
        cx.run_until_parked();
        assert!(
            app.read_with(cx, |app, _| (
                app.drawer_offset,
                app.drawer_open,
                app.workbench_open
            )) == (0.0, false, false),
            "and lifting the finger must not settle the phone on another page"
        );
        assert!(
            cx.debug_bounds("mobile-agent-question").is_some(),
            "the panel the reader is answering stays where it was"
        );
    }

    /// The drawer's header wears the same lockup as the pairing page, from the
    /// drawer's own title step.
    ///
    /// The label is where the reader's text-size step enters the lockup, so the
    /// mark has to be scaled from that same size: a box frozen in pixels leaves
    /// the label's baseline as soon as the step moves, which is the drift the
    /// drawer used to show. The mark's own chain is checked rather than the
    /// whole renderer, so the header's buttons stay free to size in pixels.
    #[test]
    fn the_drawer_wordmark_scales_both_halves_from_one_size() {
        let source = include_str!("app.rs");
        let drawer = renderer_source(source, "render_drawer");
        assert!(
            drawer.contains("theme::wordmark_mark("),
            "the drawer's mark should be scaled from the label's own size"
        );
        assert!(
            drawer.contains(".text_size(theme::font_title())"),
            "the drawer's wordmark should take the title step"
        );
        let mark = drawer
            .split_once("icons/vibex-mark.svg")
            .map(|(_, tail)| tail)
            .and_then(|tail| tail.split_once("\"ibex\"").map(|(mark, _)| mark))
            .expect("the drawer's header should still wear the mark beside its label");
        assert!(mark.contains(".w(brand_mark.width)"));
        assert!(mark.contains(".h(brand_mark.height)"));
        assert!(mark.contains(".top(brand_mark.top_offset)"));
        assert!(
            !mark.contains(".size(px("),
            "a frozen box is what put the mark off the label's baseline"
        );
    }

