    /// A live request parks the row even before the persisted state catches up,
    /// and an answer or a new prompt releases it.
    #[test]
    fn a_live_request_holds_the_waiting_state_until_it_is_answered() {
        fn live(sequence: i64, payload: TimelinePayload) -> TimelineLiveEvent {
            TimelineLiveEvent {
                session_id: VibexSessionId::parse("session_waiting").unwrap(),
                sequence,
                item: TimelineItem {
                    id: vibex_core::TimelineItemId::new(),
                    session_id: VibexSessionId::parse("session_waiting").unwrap(),
                    sequence,
                    timestamp_ms: sequence,
                    source: TimelineSource::Agent,
                    kind: payload.kind(),
                    correlation_id: None,
                    provider_correlation_id: None,
                    redaction_state: TimelineRedactionState::None,
                    execution_attribution: None,
                    payload_depth: vibex_core::TimelinePayloadDepth::Detail,
                    payload,
                },
            }
        }

        let request_id = RequestId::new();
        let request = live(
            1,
            TimelinePayload::PermissionRequest(vibex_core::PermissionRequest {
                id: request_id.clone(),
                session_id: VibexSessionId::parse("session_waiting").unwrap(),
                project_id: None,
                workspace_id: None,
                provider_request_id: None,
                risk_category: PermissionRiskCategory::Command,
                title: "Run a command".into(),
                details: Vec::new(),
                allowed_responses: vec![PermissionResponseKind::Approve],
                response_options: Vec::new(),
                status: vibex_core::PermissionRequestStatus::Pending,
                requested_at_ms: 1,
                expires_at_ms: None,
            }),
        );

        let mut pending = BTreeMap::new();
        assert!(track_pending_user_request(&mut pending, &request));
        assert!(
            session_awaits_user_input(AgentSessionState::Running, &pending, "session_waiting"),
            "a request that arrived while the turn is running still parks the row"
        );
        assert!(
            !session_awaits_user_input(AgentSessionState::Idle, &pending, "session_waiting"),
            "a settled session is not waiting on anything"
        );

        // A resolution retires the request and the row stops asking.
        let resolution = live(
            2,
            TimelinePayload::PermissionResolution(vibex_core::PermissionResolution {
                request_id,
                session_id: VibexSessionId::parse("session_waiting").unwrap(),
                response: PermissionResponseKind::Approve,
                responder_device_id: None,
                provider_resolution_id: None,
                note: None,
                resolved_at_ms: 2,
            }),
        );
        assert!(track_pending_user_request(&mut pending, &resolution));
        assert!(pending.is_empty());
        assert!(!session_awaits_user_input(
            AgentSessionState::Running,
            &pending,
            "session_waiting"
        ));
    }

    /// A queued send takes the state words and the hour, and answers with a
    /// clock.
    #[test]
    fn a_queued_send_takes_the_state_words_and_the_hour() {
        let starting = sidebar_session_column(
            AgentSessionState::Initializing,
            false,
            false,
            false,
            false,
            false,
            true,
        );
        assert!(starting.show_scheduled);
        assert_eq!(
            starting.label, None,
            "the row is waiting on the clock, not starting up"
        );
        assert!(
            !starting.show_status,
            "the clock answers instead of the pulse"
        );
        assert!(
            starting.show_time,
            "and the countdown takes the slot the state words would have"
        );

        // A failed session keeps its own dot beside the clock: the row reports
        // both what it is and what happens next.
        let failed = sidebar_session_column(
            AgentSessionState::Error,
            false,
            false,
            false,
            false,
            false,
            true,
        );
        assert!(failed.show_scheduled && failed.show_error);
        assert!(!failed.show_time, "a failure takes no countdown with it");

        // A pinned row keeps the clock and yields the text slot to its pin.
        let pinned = sidebar_session_column(
            AgentSessionState::Idle,
            false,
            true,
            false,
            false,
            false,
            true,
        );
        assert!(pinned.show_scheduled);
        assert!(!pinned.show_time);

        // Without a queued send the column is what it always was.
        let plain = sidebar_session_column(
            AgentSessionState::Idle,
            false,
            false,
            false,
            false,
            false,
            false,
        );
        assert!(!plain.show_scheduled);
        assert!(plain.show_time);
    }

    /// The countdown's two shapes, at the desktop's own boundary.
    #[test]
    fn the_schedule_countdown_switches_shape_at_a_day() {
        assert_eq!(mobile_schedule_countdown(0), "00:00:00");
        assert_eq!(mobile_schedule_countdown(1_000), "00:00:01");
        // Rounded up, so a row that is still waiting never reads 00:00:00.
        assert_eq!(mobile_schedule_countdown(59_001), "00:01:00");
        assert_eq!(mobile_schedule_countdown(23 * 3_600_000), "23:00:00");
        // A day or more leads with the day.
        assert_eq!(mobile_schedule_countdown(24 * 3_600_000), "1d 00:00");
        assert_eq!(mobile_schedule_countdown(50 * 3_600_000), "2d 02:00");
    }

    /// A folder's archive entry says which window is on, and every window the
    /// desktop offers can be chosen from the phone.
    #[test]
    fn a_folder_offers_the_archive_window_the_desktop_offers() {
        assert!(!mobile_folder_archive_label(None).is_empty());
        assert!(mobile_folder_archive_label(Some(3)).contains('3'));
        assert_ne!(
            mobile_folder_archive_label(None),
            mobile_folder_archive_label(Some(3)),
            "off and a window cannot read the same"
        );

        let source = include_str!("app.rs");
        let sheet = renderer_source(source, "render_folder_archive_menu");
        assert!(
            sheet.contains("SIDEBAR_AUTO_ARCHIVE_MAX_DAYS"),
            "the list ends where the desktop's does"
        );
        assert!(
            sheet.contains("days == current"),
            "the window in force is the one marked"
        );
        assert!(
            sheet.contains("SetFolderAutoArchive"),
            "and choosing one writes it to the authority"
        );
    }

    /// A suspension the shell installed can be lifted from the session's sheet.
    #[test]
    fn a_suspended_session_can_be_resumed_from_its_sheet() {
        let source = include_str!("app.rs");
        let sheet = renderer_source(source, "render_sidebar_row_menu");
        assert!(
            sheet.contains("row.auto_continue_paused"),
            "the entry is offered only while a suspension is in force"
        );
        assert!(
            sheet.contains("mobile-row-menu-resume-auto-continue"),
            "and it is an entry of the same sheet every other command lives in"
        );
        assert!(
            sheet.contains("SetSessionAutoContinuePaused"),
            "which lifts the suspension on the authority"
        );
    }

    /// A container row's checkbox governs every session the container shows:
    /// the whole project for a project row, and for a folder the sessions of
    /// every group and project filed anywhere beneath it.
    #[test]
    fn container_batch_ids_cover_everything_the_row_governs() {
        use vibex_desktop_model::SidebarOrganizationState;

        fn session(id: &str, project_id: &str) -> AgentSession {
            AgentSession {
                id: VibexSessionId::parse(id).expect("valid session id"),
                title: id.to_string(),
                project_id: vibex_core::ProjectId::parse(project_id).expect("valid project"),
                workspace_id: vibex_core::WorkspaceId::parse("workspace_a")
                    .expect("valid workspace"),
                workspace_root: "/tmp/a".to_string(),
                workspace_mode: WorkspaceMode::CurrentCheckout,
                agent_id: AgentId::parse("claude").expect("valid agent id"),
                state: AgentSessionState::Idle,
                safety: vibex_core::AgentSessionSafety::workspace_write_ask_on_risk(),
                created_at_ms: 0,
                updated_at_ms: 0,
                last_message_at_ms: 0,
                archived_at_ms: None,
                deleted_at_ms: None,
            }
        }

        let sessions = vec![
            session("session_a", "project_a"),
            session("session_b", "project_a"),
            session("session_c", "project_a"),
            session("session_other", "project_b"),
        ];

        // A project answers with its own sessions and no one else's.
        assert_eq!(
            sidebar_project_batch_ids(&sessions, "project_a"),
            vec!["session_a", "session_b", "session_c"]
        );

        // A root folder holding project_a governs that project's sessions; a
        // session filed under a second project is not reached.
        let mut organization = SidebarOrganizationState::default();
        assert!(organization.create_folder("folder_root", "Root", None, None));
        organization
            .placements
            .push(vibex_desktop_model::SidebarOrganizationPlacement {
                item: SidebarOrganizationItem::Project("project_a".into()),
                parent_folder_id: Some("folder_root".into()),
            });
        let mut governed = sidebar_folder_batch_ids(&organization, &sessions, "folder_root");
        governed.sort();
        assert_eq!(governed, vec!["session_a", "session_b", "session_c"]);
        assert!(
            !governed.contains(&"session_other".to_string()),
            "a folder never reaches a session filed outside it"
        );

        // A project-scoped folder owns the groups filed inside it, and answers
        // through their membership rather than only through placements.
        assert!(organization.create_folder("folder_a", "A", Some("project_a".into()), None,));
        let session_workspaces =
            BTreeMap::from([("session_c".to_string(), "workspace_a".to_string())]);
        assert!(organization.create_group(
            "group_one",
            "Group",
            "project_a",
            "workspace_a",
            &["session_c".to_string()],
            &session_workspaces,
            Some("folder_a".into()),
        ));
        assert_eq!(
            sidebar_folder_batch_ids(&organization, &sessions, "folder_a"),
            vec!["session_c"]
        );
    }

    /// A delegated row reads its live session from the tree page that named it.
    ///
    /// The root session list the phone syncs leaves owned children out, so the
    /// row used to report nothing at all — no state, no hour — for the sessions
    /// the ownership tree had just told it about.
    #[test]
    fn a_delegated_row_reads_the_session_its_tree_page_carried() {
        fn session(id: &str, state: AgentSessionState) -> AgentSession {
            AgentSession {
                id: VibexSessionId::parse(id).expect("valid session id"),
                title: id.to_string(),
                project_id: vibex_core::ProjectId::parse("project_a").expect("valid project"),
                workspace_id: vibex_core::WorkspaceId::parse("workspace_a")
                    .expect("valid workspace"),
                workspace_root: "/tmp/a".to_string(),
                workspace_mode: WorkspaceMode::CurrentCheckout,
                agent_id: AgentId::parse("claude").expect("valid agent id"),
                state,
                safety: vibex_core::AgentSessionSafety::workspace_write_ask_on_risk(),
                created_at_ms: 0,
                updated_at_ms: 0,
                last_message_at_ms: 0,
                archived_at_ms: None,
                deleted_at_ms: None,
            }
        }

        let listed = session("session_listed", AgentSessionState::Running);
        let child = session("session_child", AgentSessionState::NeedsInput);
        let sessions = vec![listed];
        let delegated = BTreeMap::from([("session_child".to_string(), child)]);

        assert_eq!(
            sidebar_row_session(&sessions, &delegated, "session_listed").map(|s| s.state),
            Some(AgentSessionState::Running),
            "the ordinary list answers for the sessions the phone syncs"
        );
        assert_eq!(
            sidebar_row_session(&sessions, &delegated, "session_child").map(|s| s.state),
            Some(AgentSessionState::NeedsInput),
            "a child the root list omits is answered by its tree page"
        );
        assert!(sidebar_row_session(&sessions, &delegated, "session_gone").is_none());
    }

    /// Both tree reads keep the metadata they carried, and a host switch drops
    /// it with the tree.
    #[test]
    fn a_tree_page_carries_the_state_of_the_children_it_names() {
        let source = include_str!("app.rs");
        // Read the production source only: the needle below is a literal in
        // this test too, and counting the test's own copy would make the
        // assertion about itself.
        // The test module is the last one; the file carries `#[cfg(test)]`
        // helpers long before it, so the split is taken from the module itself.
        let production = source
            .rsplit_once("\n#[cfg(test)]\nmod tests {")
            .expect("the crate has a test module")
            .0;
        assert_eq!(
            production
                .matches("record_delegated_sessions(&page.registry)")
                .count(),
            2,
            "the root refresh and the child fetch both record what they carried"
        );
        let reset = renderer_source(source, "reset_sidebar_ui");
        assert!(
            reset.contains("self.delegated_sessions.clear()"),
            "a host switch takes the tree's snapshots with it"
        );
        assert!(
            reset.contains("self.delegated_nodes.clear()"),
            "and the records the snapshots belong to"
        );
    }

    /// A session waiting on a queued send is named by that send.
    ///
    /// The manager names a session created without one `<agent> session`, so a
    /// row that shows that is showing the placeholder; the desktop borrows the
    /// message's own words instead, and reads its attachments while doing it.
    #[test]
    fn a_waiting_session_is_named_by_the_send_it_waits_for() {
        fn session(title: &str) -> AgentSession {
            AgentSession {
                id: VibexSessionId::parse("session_waiting").expect("valid session id"),
                title: title.to_string(),
                project_id: vibex_core::ProjectId::parse("project_a").expect("valid project"),
                workspace_id: vibex_core::WorkspaceId::parse("workspace_a")
                    .expect("valid workspace"),
                workspace_root: "/tmp/a".to_string(),
                workspace_mode: WorkspaceMode::CurrentCheckout,
                agent_id: AgentId::parse("claude").expect("valid agent id"),
                state: AgentSessionState::Idle,
                safety: vibex_core::AgentSessionSafety::workspace_write_ask_on_risk(),
                created_at_ms: 0,
                updated_at_ms: 0,
                last_message_at_ms: 0,
                archived_at_ms: None,
                deleted_at_ms: None,
            }
        }
        fn send(
            text: &str,
            attachments: Vec<MessageAttachment>,
        ) -> vibex_desktop_model::SidebarScheduledSend {
            vibex_desktop_model::SidebarScheduledSend {
                session_id: "session_waiting".to_string(),
                message_id: 7,
                text: text.to_string(),
                attachments,
                scheduled_at_ms: 1_800_000_000_000,
            }
        }

        assert_eq!(
            scheduled_session_title(
                &session("claude session"),
                &send("ship the release", Vec::new())
            ),
            Some("ship the release".to_string()),
            "the placeholder gives way to what the send says"
        );
        assert_eq!(
            scheduled_session_title(
                &session("Release train"),
                &send("ship the release", Vec::new())
            ),
            None,
            "a session the reader named keeps its name"
        );
        assert_eq!(
            scheduled_session_title(
                &session("ship the release"),
                &send("ship the release", Vec::new())
            ),
            Some("ship the release".to_string()),
            "a title that already says the same words is left as it is"
        );
        assert_eq!(
            scheduled_session_title(
                &session("claude session"),
                &send(
                    "",
                    vec![message_attachment("shot.png", Some("image/png"), None)]
                )
            ),
            Some("shot.png".to_string()),
            "a message with no words is named by what it will send"
        );
        assert_eq!(
            scheduled_session_title(&session("claude session"), &send("   ", Vec::new())),
            None,
            "a message with neither has no name to lend"
        );
    }

    /// Every reschedule entry says how far off it moves the send.
    #[test]
    fn a_reschedule_entry_says_how_far_off_it_moves_the_send() {
        let labels = MOBILE_RESCHEDULE_CHOICES.map(mobile_reschedule_label);
        for label in &labels {
            assert!(!label.is_empty());
        }
        // The English "In an hour" carries no digit, so what the entries have to
        // do is read differently from one another — a sheet of four identical
        // rows would be no choice at all.
        let distinct = labels.iter().collect::<BTreeSet<_>>();
        assert_eq!(distinct.len(), labels.len());
        assert!(labels[0].contains("15"), "the minutes entry says how many");
        assert!(labels[2].contains('3'), "and so does the hours one");
    }

